/* ===========================================================================
 * Game Boy Color Emulation tab, area 3 of four: The Color picture
 * gbcPpuEmulationTabHTML(d) returns this area's HTML; the tab's composer in
 * gbc-emulation-tab.js calls every area in order (2 November 2026: the tab
 * was split into area files so a builder can read one area at a time).
 * Loaded by a plain <script src> tag (the site must open over file://).
 * =========================================================================== */

function gbcPpuEmulationTabHTML(d) {
  return '<div class="gbemu-area" id="gbcemu-area-ppu">' +

  '<section class="sect gbemu-area-head" id="gbcemu-area-ppu-head"><h3 class="sect-h">Area 3 of four: The Color picture</h3>' +
    '<p class="gbemu-key">Video memory banking and the attribute byte, palette memory and the colour pipeline, priority, objects, compatibility mode, and where the picture processor departs from the original (the timing table, the interrupt sources and LY, the LCDC train, the window).</p>' +
    '<p class="hw-readable">This area is the file <code>gbc-ppu-emulation-tab.js</code>, one of the four area files that together make the Game Boy Color Emulation tab. It can be read on its own; the build checklist is in the first area, and the rule for what a build must implement is beside it.</p>' +
    '<p class="hw-readable"><b>Where the rest of this page is.</b> When a sentence here points to a section or appendix that is not in this area, it is in one of these files (the links work on the assembled page):</p><ul class="gbemu-bullets"><li><b>Overview, checklist, and what differs from the Game Boy</b> (<code>gbc-machine-emulation-tab.js</code>): <a href="#gbce-1">1. What changes, and what does not</a> <a href="#gbce-2">2. Where the Color starts</a> <a href="#gbce-15">15. Revisions, and why one core cannot be both</a> <a href="#gbce-16">16. What to test with</a> <a href="#gbce-17">17. What the evidence here is worth</a> <a href="#gbce-18">18. What is not settled</a></li><li><b>Processor-visible timing, double speed, transfers, registers</b> (<code>gbc-timing-emulation-tab.js</code>): <a href="#gbce-3">3. Double speed</a> <a href="#gbce-4">4. Work RAM, and the two questions every register asks</a> <a href="#gbce-11">11. The block transfer</a> <a href="#gbce-12">12. Sprite-memory transfer on the Color</a> <a href="#gbce-14">14. The undocumented registers</a> <a href="#gbce-regs">Appendix A. The Color&rsquo;s registers, bit by bit</a></li><li><b>The Color sound</b> (<code>gbc-apu-emulation-tab.js</code>): <a href="#gbce-13">13. Sound</a></li></ul>' +
  '</section>' +
  '<div class="gbemu-toc"><b>In this area</b><a href="#gbce-5">5. Video memory banking and the attribute byte</a><a href="#gbce-6">6. Palette memory and the colour pipeline</a><a href="#gbce-7">7. Priority: the bit that means two things</a><a href="#gbce-8">8. Objects</a><a href="#gbce-9">9. Compatibility mode</a><a href="#gbce-10">10. Where the picture processor departs</a></div>' +

  '<section class="sect" id="gbce-5"><h3 class="sect-h">5. Video memory banking and the attribute byte</h3>' +
    '<p class="hw-readable"><b>Scale in sections 5 and 6.</b> Every dot number in these two sections is on the <b>access scale</b> of the Game Boy tab&rsquo;s section 14 (&ldquo;Access windows, as the dots a processor access sees&rdquo;): an access on dot D is made when dots 0 to D&nbsp;&minus;&nbsp;1 of the line are done and dot D is not begun, counted from the line&rsquo;s dot 0. One dot is one T-cycle at both speeds, so one machine cycle covers 4 dots at single speed and 2 dots in double speed. &ldquo;Line&rdquo; is the picture processor&rsquo;s own line counter, 0 to 153. <b>Colour mode</b> is a Color running a cartridge with the Color flag; <b>compatibility mode</b> is a Color running a cartridge without it (section 9).</p>' +

    '<div class="gbemu-rule" id="gbcr-5-1"><b>Rule C5/1.</b> Video memory must be 16 KB in two 8 KB banks, both mapped at ' +
    '<code>0x8000&ndash;0x9FFF</code>. Bit 0 of <code>0xFF4F</code> selects which bank <b>the ' +
    'processor</b> sees. <b>The picture processor must see both banks at once</b>: bank 0 holds tile data and the two tile maps exactly as on the original, and bank 1 ' +
    'holds more tile data <em>and</em> a parallel attribute byte for every tile-map cell, at the ' +
    'same offset as that cell in bank 0. The attribute bits are in the table below.</div>' +
    '<div class="gbemu-why"><b>Why.</b> The picture processor seeing both banks at once is the whole trick of the Color&rsquo;s background: one tile-map cell gets its tile number from bank 0 and its attribute from bank 1 at the same address.</div>' +
    '<table class="gbemu-table"><thead><tr><th>Attribute bit (bit 0 = least significant)</th><th>Meaning (colour mode)</th></tr></thead><tbody>' +
      '<tr><td><code>0&ndash;2</code></td><td>Background palette, 0 to 7</td></tr>' +
      '<tr><td><code>3</code></td><td>Take this tile&rsquo;s data from bank 1</td></tr>' +
      '<tr><td><code>4</code></td><td>Unused</td></tr>' +
      '<tr><td><code>5</code></td><td>Flip horizontally</td></tr>' +
      '<tr><td><code>6</code></td><td>Flip vertically</td></tr>' +
      '<tr><td><code>7</code></td><td>Background wins over objects (the exact test is Rule C7/2)</td></tr>' +
    '</tbody></table>' +
    '<div class="gbemu-example"><b>Example.</b> The tile-map cell at <code>0x9800</code> in bank 0 holds the tile number; the byte at <code>0x9800</code> in bank 1 is that cell&rsquo;s attribute. An attribute of <code>0x2B</code> (binary <code>0010 1011</code>) means: background palette 3 (bits 0&ndash;2 = <code>011</code>), tile data from bank 1 (bit 3 = 1), flipped horizontally (bit 5 = 1), not flipped vertically (bit 6 = 0), and the background does not win over objects through this bit (bit 7 = 0).</div>' +

    '<div class="gbemu-rule" id="gbcr-5-2"><b>Rule C5/2.</b> <b>The bank cannot travel inside the address.</b> Both banks are mapped ' +
    'at the same addresses, so every video-memory read that needs a specific bank must carry the bank beside ' +
    'the address, not folded into it. The vertical flip, by contrast, <em>is</em> folded into the address: it selects the ' +
    'row within the tile.</div>' +
    '<div class="gbemu-example"><b>Example.</b> A background tile with attribute bits 3 and 6 set (bank 1, flipped vertically), drawn on the tile&rsquo;s row 2 of 8: the read takes row 5 of that tile (the flip changes the address), from bank 1 (the bank is a separate input to the read, beside the address). A renderer that mixes the two up works for every unflipped tile and for flipped tiles in bank 0, and fails first on a flipped tile out of bank 1.</div>' +
    '<div class="gbemu-why"><b>Why.</b> The two being different is exactly the sort of thing that ' +
    'produces a renderer which works until a flipped tile comes out of bank 1.</div>' +

    '<h4 class="gbemu-sub">The discipline that makes the original path provably unchanged</h4>' +
    '<div class="gbemu-rule" id="gbcr-5-3"><b>Rule C5/3.</b> Outside colour mode (compatibility mode, and the original), every background attribute byte must act as <code>0x00</code>: palette 0, bank 0, no flips, no priority.</div>' +
    '<p class="gbemu-key"><b>How to build Rule C5/3 (recommended, worth copying wholesale).</b> <b>Force the attribute byte to zero outside ' +
    'colour mode</b> rather than branching on the mode at each consumer. A zero attribute means ' +
    'palette 0, bank 0, no flips, no priority, so every downstream expression reduces ' +
    '<em>textually</em> to the original&rsquo;s, with no second code path and no device test of its ' +
    'own. Do the same one level down: make the picture processor&rsquo;s plain video read always ' +
    'take bank 0, so every existing caller is unchanged and the monochrome render is bit-identical ' +
    'by construction rather than by testing.</p>' +
    '<div class="gbemu-why"><b>Why.</b> A colour port that leaves the original&rsquo;s output ' +
    'measurably intact is one you can bisect; one that does not is a rewrite wearing a port&rsquo;s ' +
    'name.</div>' +

    '<h4 class="gbemu-sub">Access rules</h4>' +
    '<div class="gbemu-rule" id="gbcr-5-4"><b>Rule C5/4.</b> A read of <code>0xFF4F</code> must return <code>0xFE | bank</code> (bit 0 is the selected bank; the unused bits 1 to 7 read 1), ' +
      '<b>in compatibility mode as well as in colour mode</b>. In compatibility mode, writes to <code>0xFF4F</code> must be ignored.</div>' +
    '<div class="gbemu-example"><b>Example.</b> Colour mode: write <code>0x01</code>, then a read gives <code>0xFF</code>; write <code>0x02</code> (bit 0 clear, so bank 0), then a read gives <code>0xFE</code>. Compatibility mode: a write of <code>0x01</code> changes nothing, and the read still gives <code>0xFE | bank</code> for the bank already selected: the register is answered in compatibility mode, not left to open bus.</div>' +

    '<div class="gbemu-rule" id="gbcr-5-5"><b>Rule C5/5.</b> A processor access to video memory or sprite memory that falls where the tables below say &ldquo;closed&rdquo; is blocked: a blocked read must return <code>0xFF</code>, and a blocked write must be dropped (memory keeps its old byte). The ' +
        'read closes on the <em>live</em> mode (the picture processor&rsquo;s own phase), and the write closes on the <em>reported</em> mode (the mode STAT returns), ' +
        'which is the same asymmetry the original has.</div>' +
    '<div class="gbemu-example"><b>Example.</b> On the power-on line at single speed, an access on dot 85 to 89 finds video memory open to a read and closed to a write (single-speed table below, row &ldquo;Power-on line, 85 to 89&rdquo;): a read there returns the stored byte, and a write there is dropped. From dot 90 a read returns <code>0xFF</code> too.</div>' +

    '<div class="gbemu-rule" id="gbcr-5-6"><b>Rule C5/6.</b> <b>The windows are the Color&rsquo;s own, in compatibility mode as well as in colour mode.</b> At single speed a build must reproduce the single-speed table below, dot for dot. Its edges, in words:' +
    '<ol class="gbemu-steps">' +
      '<li>Video memory closes when drawing starts: on an ordinary line an access on dot 83 or 84 finds it open and one on dot 85 finds it closed. (The original closes it six dots before drawing starts; the Game Boy tab, section 14.)</li>' +
      '<li>Video memory and sprite memory both reopen on the dot STAT reports mode 0, not at the last pixel (dot 255 at SCX 0 with no objects).</li>' +
      '<li>A sprite-memory write is refused from the first dot of the line (access dot 0) on; there is no write window where the scan ends. On an ordinary line the scan&rsquo;s one open access dot, 4, is open to reads and writes alike. Line 0 after vertical blank has no open dot: sprite memory is closed to reads and writes from its dot 0 until it reopens at the mode-0 report (the table&rsquo;s two line-0 rows).</li>' +
      '<li>On the power-on line, video memory still reads for the first 6 dots of drawing: an access on dot 85 to 89 reads, one on dot 90 is blocked.</li>' +
    '</ol></div>' +
    '<div class="gbemu-why"><b>Why.</b> The windows follow the status register. For step 1 the hardware table allows that dot or two dots later; this is the one with a reason. For step 4 the table allows 5 to 8 dots. ' +
      'FITTED as a set; AGE <code>oam-read</code>, <code>vram-read</code> and ' +
      '<code>oam-write</code> in compatibility mode pass with it.</div>' +

    '<div class="gbemu-rule" id="gbcr-5-7"><b>Rule C5/7.</b> In double speed a build must reproduce the double-speed table below, dot for dot. Its edges, in words:' +
    '<ol class="gbemu-steps">' +
      '<li>Video memory is closed exactly while STAT reports mode 3, and sprite memory exactly while STAT ' +
      'reports mode 2 or 3, both edges on the dot STAT changes, with the two exceptions of steps 2 and 3.</li>' +
      '<li>A sprite-memory write meets the closing edge one dot sooner than a read: it is refused from access dot 4, one dot before STAT reports mode 2 on dot 5, and only on that one dot before it (not from the start of the line).</li>' +
      '<li>At the end of drawing the video-memory write opens on dot 257, one dot before STAT reports mode 0; the rest open on the next dot.</li>' +
      '<li>On the power-on line, STAT reports mode 3 three dots after drawing starts (from access dot 87) and mode 0 one ' +
      'dot later than at single speed (from access dot 260). Both reads follow that report. The writes do not: the video-memory write is closed from access dot 85 (drawing starts) and opens again one dot before the mode-0 report (259 at SCX 0 with no objects; it moves with that report); the sprite-memory write is closed from access dot 86, one dot before the mode-3 report, to the mode-0 report. The double-speed table&rsquo;s power-on rows give every dot.</li>' +
    '</ol></div>' +
    '<div class="gbemu-why"><b>Why.</b> Step 1 is MECHANISM: the single-speed rule at the ' +
      'other speed. Step 2 is FITTED: 1 ' +
      'and 2 both fit, because the table samples even dots only. Step 4 is FITTED; why that line differs is not known. The colour-mode AGE ' +
      'runs <code>vram-read</code>, <code>oam-read</code> and <code>oam-write</code> pass at both speeds ' +
      '(section 16).</div>' +

    '<div class="gbemu-rule" id="gbcr-5-8"><b>Rule C5/8.</b> The Color&rsquo;s power-on line is one dot ' +
      'shorter than the original&rsquo;s, so at single speed, after a screen-on write, the processor&rsquo;s accesses fall on dots 2, 6, 10, ..., 78, 82, 86 (4k&nbsp;+&nbsp;2) of every ' +
      'later line, where the original&rsquo;s fall on 1, 5, ..., 77, 81, 85 (4k&nbsp;+&nbsp;1).</div>' +
    '<div class="gbemu-example"><b>Example.</b> At single speed on an ordinary line, the processor&rsquo;s accesses nearest the start of drawing fall on dots 82 and 86: by the single-speed table the one on 82 finds video memory open, the one on 86 finds it closed. On the original the same two accesses fall on 81 and 85.</div>' +

    '<p class="hw-readable"><b>Not modelled here:</b> the Color&rsquo;s revision-dependent open-bus behaviour at the ' +
        'end of drawing. Recorded as a gap rather than approximated, because a guess at a corruption ' +
        'is worse than its absence.</p>' +

    '<p class="gbemu-key"><b>The Color&rsquo;s single-speed windows, dot by dot (Rule C5/6).</b> The same table as the Game Boy tab&rsquo;s section 14 (&ldquo;Access windows, as the dots a processor access sees&rdquo;), copied here so this page holds it whole; the two copies are one measurement and must change together. Dots are on that section&rsquo;s access scale: an access on dot D sees dots 0 to D &minus; 1 done. INSTRUMENT-MEASURED with the probe <code>test/tabprobe</code> (compatibility mode, no objects, SCX 0). Double speed is in Rule C5/7 and, dot by dot, in the second table below.</p>' +
    '<table class="gbemu-table"><thead><tr><th>The Colour at single speed, access on dot (access scale, from the line&rsquo;s dot 0)</th><th>Video memory ' +
    'read</th><th>Video memory write</th><th>Sprite memory read</th><th>Sprite memory ' +
    'write</th><th>STAT mode (reported)</th></tr></thead><tbody>' +
    '<tr><td>Ordinary line, 0 to 2</td><td>open</td><td>open</td><td>closed</td><td><b>closed</b></td><td>0</td></tr>' +
    '<tr><td>Ordinary line, 3</td><td>open</td><td>open</td><td>closed</td><td>closed</td><td>2</td></tr>' +
    '<tr><td>Ordinary line, 4</td><td>open</td><td>open</td><td>open</td><td>open</td><td>2</td></tr>' +
    '<tr><td>Ordinary line, 5 to 82</td><td>open</td><td>open</td><td>closed</td><td>closed</td><td>2</td></tr>' +
    '<tr><td>Ordinary line, 83 and 84</td><td><b>open</b></td><td>open</td><td>closed</td><td>closed</td><td>3</td></tr>' +
    '<tr><td>Ordinary line, 85 to the dot before mode 0 is reported (254 at SCX 0 with no objects)</td><td>closed</td><td>closed</td><td>closed</td><td>closed</td><td>3</td></tr>' +
    '<tr><td>Ordinary line, from the mode-0 report (255 at SCX 0 with no objects) to 455</td><td>open</td><td>open</td><td>open</td><td>open</td><td>0</td></tr>' +
    '<tr><td>Power-on line, 8 to 84</td><td>open</td><td>open</td><td>open</td><td>open</td><td>0</td></tr>' +
    '<tr><td>Power-on line, 85 to 89</td><td><b>open</b></td><td>closed</td><td>closed</td><td>closed</td><td>3</td></tr>' +
    '<tr><td>Power-on line, 90 up to the mode-0 report on 259</td><td>closed</td><td>closed</td><td>closed</td><td>closed</td><td>3</td></tr>' +
    '<tr><td>Power-on line, 259 to its last dot, 457</td><td>open</td><td>open</td><td>open</td><td>open</td><td>0</td></tr>' +
    '<tr><td>Line 0 after vertical blank, 0 to 2</td><td>open</td><td>open</td><td>closed</td><td>closed</td><td>0</td></tr>' +
    '<tr><td>Line 0 after vertical blank, 3 to 82</td><td>open</td><td>open</td><td>closed</td><td>closed</td><td>2</td></tr>' +
    '<tr><td>Line 0 after vertical blank, 83 on</td><td colspan="5">as an ordinary line</td></tr>' +
    '<tr><td>Line 144, 0 to 3</td><td>open</td><td>open</td><td>open</td><td>open</td><td>0</td></tr>' +
    '<tr><td>Line 144 from dot 4, and lines 145 to 153, every dot</td><td>open</td><td>open</td><td>open</td><td>open</td><td>1</td></tr>' +
    '</tbody></table>' +
    '<p class="gbemu-key"><b>Double speed, an ordinary line, dot by dot (Rule C5/7)</b> (access scale, from the line&rsquo;s dot 0, the same scale as the single-speed table above; colour mode, SCX 0, no objects; INSTRUMENT-MEASURED with <code>test/tabprobe</code>). Steps 2 and 3 of Rule C5/7 are the bold cells.</p>' +
    '<table class="gbemu-table"><thead><tr><th>Double speed, access on dot (access scale, from the line&rsquo;s dot 0); an ordinary line unless the row names another</th><th>Video memory read</th><th>Video memory write</th><th>Sprite memory read</th><th>Sprite memory write</th><th>STAT mode (reported)</th></tr></thead><tbody>' +
    '<tr><td>0 to 3</td><td>open</td><td>open</td><td>open</td><td>open</td><td>0</td></tr>' +
    '<tr><td>4</td><td>open</td><td>open</td><td>open</td><td><b>closed</b></td><td>0</td></tr>' +
    '<tr><td>5 to 84</td><td>open</td><td>open</td><td>closed</td><td>closed</td><td>2</td></tr>' +
    '<tr><td>85 to 256</td><td>closed</td><td>closed</td><td>closed</td><td>closed</td><td>3</td></tr>' +
    '<tr><td>257</td><td>closed</td><td><b>open</b></td><td>closed</td><td>closed</td><td>3</td></tr>' +
    '<tr><td>from the mode-0 report (the dot after 257) to 455</td><td>open</td><td>open</td><td>open</td><td>open</td><td>0</td></tr>' +
    '<tr><td>Line 0 after vertical blank, 0 to 3</td><td>open</td><td>open</td><td>open</td><td>open</td><td><b>1</b></td></tr>' +
    '<tr><td>Line 0 after vertical blank, 4</td><td>open</td><td>open</td><td>open</td><td><b>closed</b></td><td><b>1</b></td></tr>' +
    '<tr><td>Line 0 after vertical blank, 5 on</td><td colspan="5">as an ordinary line</td></tr>' +
    '<tr><td>Line 144, 0 to 5</td><td>open</td><td>open</td><td>open</td><td>open</td><td>0</td></tr>' +
    '<tr><td>Line 144 from dot 6, and lines 145 to 153, every dot</td><td>open</td><td>open</td><td>open</td><td>open</td><td>1</td></tr>' +
    '<tr><td>Power-on line, 8 to 84</td><td>open</td><td>open</td><td>open</td><td>open</td><td>0</td></tr>' +
    '<tr><td>Power-on line, 85</td><td>open</td><td><b>closed</b></td><td>open</td><td>open</td><td>0</td></tr>' +
    '<tr><td>Power-on line, 86</td><td>open</td><td>closed</td><td>open</td><td><b>closed</b></td><td>0</td></tr>' +
    '<tr><td>Power-on line, 87 up to the dot before 259</td><td>closed</td><td>closed</td><td>closed</td><td>closed</td><td>3</td></tr>' +
    '<tr><td>Power-on line, 259</td><td>closed</td><td><b>open</b></td><td>closed</td><td>closed</td><td>3</td></tr>' +
    '<tr><td>Power-on line, 260 to its last dot, 455</td><td>open</td><td>open</td><td>open</td><td>open</td><td>0</td></tr>' +
    '</tbody></table>' +
    '<div class="gbemu-example"><b>Example.</b> On the double-speed power-on line, accesses on dots 84, 85, 86 and 87: a sprite-memory write lands on 84 and 85 and is dropped on 86 and 87; a video-memory write lands on 84 only; both reads return the stored byte up to 86 and <code>0xFF</code> from 87. STAT reads mode 0 on all four up to 86 and mode 3 on 87. So on this line the two writes do <em>not</em> follow the mode-3 report: the video-memory write closes when drawing starts (85) and the sprite-memory write one dot before the report (86), exactly as Rule C5/7 step 2&rsquo;s one-dot-sooner write does on an ordinary line. INSTRUMENT-MEASURED (<code>test/tabprobe</code>), and read from our source.</div>' +
    '</section>' +

  /* ------------------------------------------------------------------- 6 */
  '<section class="sect" id="gbce-6"><h3 class="sect-h">6. Palette memory and the colour pipeline</h3>' +
    '<p class="hw-readable">Dots in this section are on the access scale of section 5&rsquo;s head (from the line&rsquo;s dot 0; one dot is one T-cycle at both speeds).</p>' +
    '<table class="gbemu-table"><thead><tr><th>Register</th><th>What it is</th></tr></thead><tbody>' +
      '<tr><td><code>0xFF68</code></td><td>Background palette index: bits 0&ndash;5 the byte, bit 7 auto-increment. Bit 6 reads 1</td></tr>' +
      '<tr><td><code>0xFF69</code></td><td>Background palette data: 64 bytes behind that index</td></tr>' +
      '<tr><td><code>0xFF6A</code></td><td>Object palette index, same shape</td></tr>' +
      '<tr><td><code>0xFF6B</code></td><td>Object palette data, 64 bytes</td></tr>' +
    '</tbody></table>' +

    '<div class="gbemu-rule" id="gbcr-6-1"><b>Rule C6/1.</b> Each 64-byte palette store is <b>eight palettes of four colours, two bytes ' +
    'each</b>: palette p, colour c starts at byte p&nbsp;&times;&nbsp;8 + c&nbsp;&times;&nbsp;2. The pair is little-endian (low byte first) and holds five bits per channel: <b>red in bits ' +
    '0&ndash;4, green in 5&ndash;9, blue in 10&ndash;14</b>. <b>Bit 15</b> (bit 7 of the high byte) holds no colour, but it is <b>stored as written</b>, a read of the data port returns it, and the picture carries it: the value the picture puts out for a pixel is the whole 16-bit pair exactly as stored, bit 15 included, never masked to 15 bits. Background and object palettes are two separate 64-byte stores behind two separate index registers.</div>' +
    '<div class="gbemu-example"><b>Example.</b> Background palette 3, colour 2 is bytes 28 and 29 of the background store. If byte 28 holds <code>0xEF</code> and byte 29 holds <code>0x1B</code>, the palette word is <code>0x1BEF</code>: red = <code>0x1BEF &amp; 31</code> = 15, green = <code>(0x1BEF &gt;&gt; 5) &amp; 31</code> = 31, blue = <code>(0x1BEF &gt;&gt; 10) &amp; 31</code> = 6. A colour written as <code>0xFF</code>, <code>0xFF</code> is white, and the pixel word the picture puts out for it is <code>0xFFFF</code>, not <code>0x7FFF</code>. Read from our source (the picture returns the stored pair unmasked). An independent build that masked bit 15 drew the same colours but differed in the word of every pixel whose stored high byte has bit 7 set, on six rows (daid <code>speed_switch_timing_ly</code>, <code>_div</code>, <code>_stat</code>; ax6 <code>rtc3test-1</code> to <code>-3</code>); with only this rule changed, all six matched word for word.</div>' +

    '<div class="gbemu-rule" id="gbcr-6-2"><b>Rule C6/2.</b> <b>The auto-increment happens on a ' +
    'write to the data port and not on a read</b>, and it happens whether that write lands or is dropped (Rule C6/3). <b>At index 63 it WRAPS to 0; it does not saturate.</b> The index is six bits and the increment ' +
    'is masked back into them, with the auto-increment flag re-applied: after a write with bit 7 set, the stored index register becomes <code>0x80 | ((index + 1) &amp; 0x3F)</code>. A read of the index register returns the stored value with bit 6 set. So <b>the stored value ' +
    'goes <code>0xBF</code> to <code>0x80</code> and the register <em>reads</em> ' +
    '<code>0xFF</code> to <code>0xC0</code></b>. <b>Those are two different quantities and the ' +
    'read-back is the one to compare against.</b></div>' +
    '<table class="gbemu-table"><thead><tr><th>Access to <code>0xFF69</code> or <code>0xFF6B</code> (colour mode)</th><th>Index bit 7 (auto-increment)</th><th>Palette byte at the index</th><th>Index register afterwards</th></tr></thead><tbody>' +
      '<tr><td>Write, port open</td><td>1</td><td>Written</td><td><code>0x80 OR ((index + 1) &amp; 0x3F)</code></td></tr>' +
      '<tr><td>Write, port busy (Rule C6/3)</td><td>1</td><td>Unchanged (write dropped)</td><td><code>0x80 OR ((index + 1) &amp; 0x3F)</code></td></tr>' +
      '<tr><td>Write, port open</td><td>0</td><td>Written</td><td>Unchanged</td></tr>' +
      '<tr><td>Write, port busy</td><td>0</td><td>Unchanged (write dropped)</td><td>Unchanged</td></tr>' +
      '<tr><td>Read (open: the byte; busy: <code>0xFF</code>)</td><td>0 or 1</td><td>Unchanged</td><td>Unchanged</td></tr>' +
    '</tbody></table>' +
    '<div class="gbemu-example"><b>Example.</b> Write <code>0xBF</code> to <code>0xFF68</code> (auto-increment on, index 63); a read of <code>0xFF68</code> now gives <code>0xFF</code>. Write a byte to <code>0xFF69</code>: it lands in byte 63, the stored index becomes <code>0x80</code> (index 0, not 63 and not 64), and a read of <code>0xFF68</code> gives <code>0xC0</code>. A second write to <code>0xFF69</code> lands in byte 0, palette 0&rsquo;s first byte. A read of <code>0xFF69</code> in between would have left the index where it was.</div>' +
    '<div class="gbemu-why"><b>Why.</b> The read/write asymmetry is the kind of asymmetry that costs an afternoon if you ' +
    'assume symmetry. The wrap has to be ' +
    'said, because six bits of index and an increment with no end condition leave it open and ' +
    '<b>both answers yield a working-looking machine</b>: a title that fills all eight ' +
    'palettes in one run never reaches 63 with more to write, so the two behaviours are ' +
    'indistinguishable on everything this project scores. <b>Bit 6 reads 1</b> (appendix A&rsquo;s ' +
    '<code>FF68</code> row says so outright), so an implementer comparing a read-back against ' +
    'the stored <code>0x80</code> sees <code>0xC0</code> and concludes the wrap is broken when it ' +
    'is not. <b>Read-back is the observable this page insists on everywhere else</b>, including ' +
    'Rule C6/4, where the data register is open bus. <b>Read from our own source; NOT MEASURED on ' +
    'hardware.</b> <b>What would settle it:</b> a cartridge that sets the index to 63 with ' +
    'auto-increment on, writes twice, and reads back palette 0&rsquo;s first byte.</div>' +

    '<div class="gbemu-rule" id="gbcr-6-3"><b>Rule C6/3.</b> <b>The palette data ports are busy while the picture draws.</b> A write to <code>0xFF69</code> or <code>0xFF6B</code> that lands in the busy window is <b>dropped, and the auto-increment still happens</b> (Rule C6/2); a read there returns <code>0xFF</code>. The busy window, on the access scale, on lines 0 to 143 with the display on: an access on dot 84 at single speed (87 in double speed, 3 dots later) up to the last-pixel dot + 3 is blocked, and one on the last-pixel dot + 4 or later lands. The <b>last-pixel dot</b> is the dot the line&rsquo;s 160th pixel leaves the queue (256 at SCX 0 with no objects). The close is keyed to the last pixel, not to STAT&rsquo;s mode-0 report, which leads it; the open is keyed to drawing, not to the STAT mode-3 report, which on the Color comes on dot 82 at single speed (section 10). On lines 144 to 153, and with the display off, the ports are always open. The index registers <code>0xFF68</code> and <code>0xFF6A</code> are never busy.</div>' +
    '<table class="gbemu-table"><thead><tr><th>Line (picture processor line counter) and display</th><th>Speed</th><th>Access on dot (access scale, from the line&rsquo;s dot 0); L = last-pixel dot</th><th>Write to <code>0xFF69</code> / <code>0xFF6B</code></th><th>Read of <code>0xFF69</code> / <code>0xFF6B</code></th></tr></thead><tbody>' +
      '<tr><td>Display off (LCDC bit 7 = 0), any line</td><td>Either</td><td>Any</td><td>Lands</td><td>The byte</td></tr>' +
      '<tr><td>Lines 144 to 153, display on</td><td>Either</td><td>Any</td><td>Lands</td><td>The byte</td></tr>' +
      '<tr><td rowspan="3">Lines 0 to 143, display on</td><td>Single</td><td>0 to 83</td><td>Lands</td><td>The byte</td></tr>' +
      '<tr><td>Single</td><td>84 to L + 3</td><td><b>Dropped</b>, index still advances</td><td><code>0xFF</code></td></tr>' +
      '<tr><td>Single</td><td>L + 4 to the line&rsquo;s last dot</td><td>Lands</td><td>The byte</td></tr>' +
      '<tr><td rowspan="3">Lines 0 to 143, display on</td><td>Double</td><td>0 to 86</td><td>Lands</td><td>The byte</td></tr>' +
      '<tr><td>Double</td><td>87 to L + 3</td><td><b>Dropped</b>, index still advances</td><td><code>0xFF</code></td></tr>' +
      '<tr><td>Double</td><td>L + 4 to the line&rsquo;s last dot</td><td>Lands</td><td>The byte</td></tr>' +
    '</tbody></table>' +
    '<div class="gbemu-example"><b>Example.</b> SCX 0, no objects: the 160th pixel leaves the queue on dot 256, so L = 256. At single speed accesses on dots 84 to 259 are blocked and one on 260 is open; in double speed accesses on 87 to 259 are blocked and one on 260 is open (the close is the same at both speeds; only the open differs). With <code>0xFF68</code> = <code>0x85</code> (auto-increment, byte 5), a write to <code>0xFF69</code> on dot 259 is dropped, byte 5 keeps its old value, and <code>0xFF68</code> then reads <code>0xC6</code> (index 6); the same write on dot 260 lands in byte 5 and also leaves the index at 6. On the processor&rsquo;s own access grid (single speed 4k + 2, Rule C5/8; double speed even dots) the first blocked access is on dot 86 at single speed and 88 in double.</div>' +
    '<div class="gbemu-why"><b>Why.</b> INSTRUMENT-MEASURED (the probe <code>test/tabprobe</code>, colour mode, SCX 0, no objects). MECHANISM for the block itself (Pan Docs, the community&rsquo;s reference document, which says palette data cannot be accessed while the line is drawn and that a blocked write still advances the index: both statements are reproduced in full in Rules C6/2 and C6/3, so the document need not be opened; the reference blocks too; Magical Drop rewrites a colour 46 times per line and depends on it); the window&rsquo;s edges are FITTED to the reference&rsquo;s outputs on 112 probe cells, all of which agree. Read from our source (<code>CGB_PAL_BLOCK</code> 1). The evidence that bears on the block is under &ldquo;Blocking during drawing: the evidence&rdquo; at the end of this section.</div>' +

    '<div class="gbemu-rule" id="gbcr-6-4"><b>Rule C6/4.</b> In compatibility mode, after the boot program has finished, <b>the index register moves and the data register is ' +
    'open bus</b>: writes to <code>0xFF68</code> and <code>0xFF6A</code> are stored and read back (bit 6 reading 1); writes to <code>0xFF69</code> and <code>0xFF6B</code> are ignored and do not advance the index; reads of <code>0xFF69</code> and <code>0xFF6B</code> are open bus. While the boot program is mapped, the data registers accept writes (Rule C6/5).</div>' +
    '<table class="gbemu-table"><thead><tr><th>Machine state (Color)</th><th>Index register <code>0xFF68</code> / <code>0xFF6A</code></th><th>Data register write <code>0xFF69</code> / <code>0xFF6B</code></th><th>Data register read</th></tr></thead><tbody>' +
      '<tr><td>Colour mode</td><td>Stored; reads with bit 6 = 1</td><td>Rules C6/2, C6/3</td><td>Rules C6/2, C6/3</td></tr>' +
      '<tr><td>Boot program mapped (in either mode)</td><td>Stored; reads with bit 6 = 1</td><td>Accepted, as in colour mode (Rule C6/5)</td><td>Colour mode: Rules C6/2, C6/3; compatibility flag already cleared: open bus</td></tr>' +
      '<tr><td>Compatibility mode, boot program finished</td><td>Stored; reads with bit 6 = 1</td><td>Ignored; index unchanged</td><td>Open bus</td></tr>' +
    '</tbody></table>' +
    '<div class="gbemu-why"><b>Why.</b> The index is gated on the device, the data on the mode: section 4&rsquo;s ' +
    'point again, on the two registers you are most likely to treat as a pair. Section 9 gives the consequence: the compatibility palette is unreachable to the game.</div>' +

    '<h4 class="gbemu-sub">The boot-program exception, which is measured and not defensive</h4>' +
    '<div class="gbemu-rule" id="gbcr-6-5"><b>Rule C6/5.</b> The palette data registers must <b>also</b> accept writes while the boot ' +
    'program is mapped, even though the machine is about to be in compatibility mode: a data-register write is accepted when colour mode is on <b>or</b> the boot program is mapped (either one, or both).</div>' +
    '<div class="gbemu-why"><b>Why.</b> Gate them on ' +
    'colour mode alone and <b>all twenty-seven colour cells render uniformly white</b>: ' +
    '<code>0x7FFF</code> across all 23,040 pixels, checked on three cells independently. The reason ' +
    'is the boot program&rsquo;s own order of operations, as steps:' +
    '<ol class="gbemu-steps"><li>It writes an all-white palette to blank the screen.</li><li>It clears the colour-mode flag part-way through.</li><li>Only <em>then</em> does it load the real compatibility palette, which the naive gate throws away.</li></ol></div>' +

    '<h4 class="gbemu-sub">Five bits to eight, and where to do it</h4>' +
    '<div class="gbemu-rule" id="gbcr-6-6"><b>Rule C6/6.</b> <b>Do not expand in the core.</b> The core must emit each pixel as the raw 15-bit palette word (its declared frame format is <code>BGR555</code>) and expand it once, at the display, channel by channel as ' +
        '<code>(c &lt;&lt; 3) | (c &gt;&gt; 2)</code> (a 5-bit value c to an 8-bit value). Scoring compares in 5-bit space.</div>' +
    '<div class="gbemu-example"><b>Example.</b> Replicating the top three bits maps 31 to ' +
        '255 exactly (248 | 7); a bare shift maps it to 248 and every white in your output is slightly ' +
        'grey. Further values: 16 to 132, 6 to 49, 12 to 99, 18 to 148, 7 to 57, 0 to 0.</div>' +
    '<div class="gbemu-why"><b>Why.</b> The expansion is specified by the <b>test suite itself</b>, not by an emulator. ' +
        'Scoring in 5-bit space is right because the expansion is a bijection on 5-bit values and ' +
        'converting before comparing only adds a place to be wrong.</div>' +

    '<div class="gbemu-rule" id="gbcr-6-7"><b>Rule C6/7.</b> <b>What our frame buffer holds when nothing is drawing, exactly</b>, is given by the table below, event by event.</div>' +
    '<table class="gbemu-table"><thead><tr><th>Event</th><th>Color (colour mode and compatibility mode)</th><th>Original</th></tr></thead><tbody>' +
      '<tr><td>Power-on, with or without a boot program</td><td>Every element white: <code>0x7FFF</code></td><td>Every element shade index 0</td></tr>' +
      '<tr><td>Display switched <b>off</b></td><td colspan="2">Buffer not touched: no clear, to white or anything else; it keeps the last picture for as long as the display stays off</td></tr>' +
      '<tr><td>Display switched <b>on</b></td><td colspan="2">The first frame writes nothing (the Game Boy tab, section 14), so the old picture stays through that frame too; the next frame draws over it line by line</td></tr>' +
      '<tr><td><code>STOP</code> without a speed switch, with the display on and STAT reporting mode 1</td><td>Buffer blanked to <code>0x0000</code> when the processor stops</td><td>Buffer blanked to shade 0 when the processor stops</td></tr>' +
    '</tbody></table>' +
    '<div class="gbemu-why"><b>Why.</b> Whether a real Color panel shows white while the display ' +
        'is off is not established here; the white fill is our core&rsquo;s meaning of &ldquo;blank&rdquo; on ' +
        'both machines, and nothing more. The <code>STOP</code> blanking: the Game Boy tab, D.9, marks that blanking ' +
        'NOT ESTABLISHED, but required: daid&rsquo;s <code>stop_instr</code> on the Color passes on our core and fails with this blanking switched off, exactly as an independent build that left it out did. Read from our source (the reset routine, <code>frame_discard</code>, and the ' +
        '<code>STOP</code> path).</div>' +
    '<p class="hw-readable"><b>Build advice for the frame buffer (not rules; ways to avoid known defects).</b></p>' +
    '<ul class="gbemu-bullets">' +
      '<li><b>The blank-framebuffer value is a real defect waiting to happen.</b> One zero read ' +
        'through two alphabets: shade index 0 is <em>white</em>, and a 15-bit colour of 0 is ' +
        '<em>black</em>. Clear a colour framebuffer to zero and you get a black screen where ' +
        'hardware gives white, and it will look like the picture processor never started.</li>' +
      '<li><b>Widen the framebuffer before touching the picture processor at all.</b> A byte holding ' +
        'a shade index cannot hold a 15-bit colour. Carrying the original&rsquo;s shades expanded to ' +
        'grey through a 16-bit buffer is bit-equivalent for the monochrome path, and it removes the ' +
        'largest structural obstacle in advance with <em>zero</em> colour emulation.</li>' +
      '<li>When the buffer changes shape, <b>remove the old length export rather than redefining ' +
        'it</b>, so a stale display fails its own check loudly instead of blitting shade indices ' +
        'through a colour expansion quietly.</li>' +
    '</ul>' +

    '<h4 class="gbemu-sub">Colour correction: DECLINED, and the largest thing this page ' +
    'does not do</h4>' +
    '<div class="gbemu-rule" id="gbcr-6-8"><b>Rule C6/8.</b> The core must apply <b>no gamma, no colour ' +
    'correction and no colour-space transform of any kind</b>: it emits the raw 15-bit word out of ' +
    'palette memory into the framebuffer, and its declared output format says so (the frame ' +
    'is <code>BGR555</code>, <em>colour straight from the core</em>). The expansion of Rule C6/6 happens ' +
    'outside it, at the display and in the scorer. <b>If you build a correction, build it as a display-side option outside ' +
    'the core and score with it off.</b></div>' +
    '<div class="gbemu-why"><b>Why.</b> Rule C6/6 is the <em>numeric</em> path from five bits ' +
    'to eight. <b>There is no perceptual one.</b> ' +
    '<b>Why that matters more than it sounds, and why no score can tell ' +
    'you.</b> A Game Boy Color&rsquo;s screen is not an sRGB monitor. A palette word rendered ' +
    'bit-exactly onto one <em>looks wrong</em>: markedly over-saturated, and the shift is ' +
    'largest exactly where games spend their colour. <b>Every reference this project scores against ' +
    'is itself an unmodified expansion, and the comparison is done in 5-bit space</b>, so an implementer ' +
    'who ships bit-correct, visibly over-saturated output scores <b>perfectly</b>, and an implementer who ' +
    'applies a correction scores <b>zero on every colour cell</b>: the exact reverse of how ' +
    'the two look on a real device. <b>That is a property of the instrument, not of the machine</b>, ' +
    'and it is the one place on this tab where the board actively rewards the wrong answer.</div>' +
    '<p class="hw-readable"><b>So it is declined rather than omitted, and the decline has a ' +
    'shape.</b> <b>What we do:</b> nothing: raw <code>BGR555</code>, expanded by ' +
    '<code>(c &lt;&lt; 3) | (c &gt;&gt; 2)</code> at the display. <b>What we do not do:</b> any of ' +
    'the published correction curves, because adopting one would break every scored colour cell we ' +
    'hold and we would have traded a measurable result for an unmeasurable one. <b>The label is ' +
    'NOT ESTABLISHED for the transform and DECLINED for the choice</b>, and the two are different: ' +
    'we are not claiming the raw expansion is what the hardware looks like, we are claiming it is ' +
    'what our instrument can score. <b>What would settle it:</b> a photometric capture of a known ' +
    'palette word on a named Color revision&rsquo;s own panel (measured, not a photograph' +
    '), which would give a transform with a provenance instead of a curve copied from another ' +
    'emulator. Without that capture, a display-side option scored with it off (Rule C6/8) is the only arrangement in which both numbers stay ' +
    'meaningful.</p>' +

    '<h4 class="gbemu-sub">Blocking during drawing: the evidence</h4>' +
    '<p class="gbemu-key"><b>What our core does: it blocks</b>, exactly as Rule C6/3 ' +
    'and its table give it. Read from our source ' +
    '(<code>CGB_PAL_BLOCK</code> 1). What follows is the evidence that bears on it.</p>' +
    '<div class="gbemu-why"><b>Why (the two references).</b> One reference ' +
    'implementation blocks, with a five-state speed-dependent window in which the palettes close ' +
    'three dots <em>before</em> video memory at the start of drawing and stay closed two dots into ' +
    'the horizontal blank at single speed and not at all in double. The other does not block ' +
    'anywhere. Its author&rsquo;s silence reads as not having modelled it rather than as having ' +
    'refuted it, and that is recorded as a reading and not as a fact. No cartridge in either ' +
    'vendored suite can adjudicate, and the one cartridge that tests exactly this ships with ' +
    'the blocking implementation&rsquo;s own suite, so it is not an independent witness to that ' +
    'implementation&rsquo;s behaviour.</div>' +
    '<div class="gbemu-why"><b>Why (the black-pixel candidate).</b> There is live evidence pointing at a further effect, and it is worth stating at full ' +
    'strength precisely because it cannot be cashed. Across four cells, <b>468 pixels</b> where two ' +
    'revision columns disagree: black in one, not in the other, <b>100 % in one direction with zero ' +
    'pixels the other way</b>, median <b>one dot</b> from a palette write against a base rate of 71 ' +
    'to 74, and <b>468 of 468 within one fetch of a write</b>. The named candidate is ' +
    '&ldquo;blocked palette access pushes a black pixel&rdquo;. Present, corroborated, directional' +
    ', and unattributable without live silicon. The block of Rule C6/3 does not rest on it: it rests on the ' +
    'documented behaviour, the reference and the 112 probe cells. Whether a ' +
    'blocked access also pushes a black pixel is still open; our core pushes nothing.</div></section>' +

  /* ------------------------------------------------------------------- 7 */
  '<section class="sect" id="gbce-7"><h3 class="sect-h">7. Priority: the bit that means two things</h3>' +
    '<div class="gbemu-rule" id="gbcr-7-1"><b>Rule C7/1.</b> <b><code>LCDC</code> bit 0 does not mean the same thing in the two ' +
    'modes.</b> On the original, and on a Color in compatibility mode, clearing it <em>blanks</em> the background: every ' +
    'background pixel becomes colour 0. On a Color in colour mode, clearing it does not blank anything: it ' +
    '<b>demotes</b> the background below objects (Rule C7/2). The choice between the two meanings is made on the <b>mode</b>, not on the device.</div>' +
    '<table class="gbemu-table"><thead><tr><th>Machine and mode</th><th><code>LCDC</code> bit 0 = 0</th><th><code>LCDC</code> bit 0 = 1</th></tr></thead><tbody>' +
      '<tr><td>Original</td><td>Every background pixel is colour 0</td><td>Background drawn</td></tr>' +
      '<tr><td>Color, compatibility mode</td><td>Every background pixel is colour 0</td><td>Background drawn</td></tr>' +
      '<tr><td>Color, colour mode</td><td>Background drawn; every opaque object pixel (objects enabled) wins over it</td><td>Background drawn; Rule C7/2 decides</td></tr>' +
    '</tbody></table>' +
    '<div class="gbemu-example"><b>Example.</b> A Color in colour mode with <code>LCDC</code> = <code>0x92</code> (bit 0 clear, bit 1 set): a background pixel of colour 2 under an attribute with bit 7 set still shows wherever no object pixel is opaque, and every opaque object pixel is drawn over it. The same cartridge flag cleared (compatibility mode), same <code>LCDC</code>: that background pixel is colour 0, through <code>BGP</code> (Rule C9/1).</div>' +
    '<div class="gbemu-why"><b>Why.</b> Carry the original&rsquo;s meaning across as one ' +
    'unguarded line and a Color title&rsquo;s background disappears in exactly the frames the bit ' +
    'exists for. <b>A second-order lesson that is worth more than the rule:</b> the device and the ' +
    '<em>mode</em> are different predicates, the references state a mode, and the mealybug corpus is exactly where they ' +
    'come apart: every cartridge in it is an original-Game-Boy cartridge, so a Color runs the whole ' +
    'suite in compatibility mode, where the references blank and a device split does not. ' +
    '<b>No test for the original Game Boy could have caught a device split</b>, and no colour score could ' +
    'either, because every colour score is taken on that same corpus.</div>' +

    '<h4 class="gbemu-sub">The resolution, in full</h4>' +
    '<div class="gbemu-rule" id="gbcr-7-2"><b>Rule C7/2.</b> Pop one pixel from each queue. <b>The object wins if and only if</b> the ' +
    'object pixel is not colour 0, <b>and</b> objects are enabled, <b>and not</b>: ( the ' +
    'background attribute&rsquo;s priority bit <b>or</b> the object&rsquo;s own priority bit is set (either one, or both), ' +
    '<b>and</b> the background pixel is not colour 0, <b>and</b> <code>LCDC</code> bit 0 is set ). The colours here are the raw 2-bit colour indices before any palette, and the background pixel is taken after Rule C7/1&rsquo;s blank.</div>' +
    '<table class="gbemu-table"><thead><tr><th>Object pixel colour index</th><th>Objects enabled</th><th>Background attribute bit 7 OR object attribute bit 7</th><th>Background pixel colour index</th><th><code>LCDC</code> bit 0</th><th>Pixel shown</th></tr></thead><tbody>' +
      '<tr><td>0</td><td>Any</td><td>Any</td><td>Any</td><td>Any</td><td>Background</td></tr>' +
      '<tr><td>1 to 3</td><td>No</td><td>Any</td><td>Any</td><td>Any</td><td>Background</td></tr>' +
      '<tr><td>1 to 3</td><td>Yes</td><td>Neither bit set</td><td>Any</td><td>Any</td><td>Object</td></tr>' +
      '<tr><td>1 to 3</td><td>Yes</td><td>One or both set</td><td>0</td><td>Any</td><td>Object</td></tr>' +
      '<tr><td>1 to 3</td><td>Yes</td><td>One or both set</td><td>1 to 3</td><td>0</td><td>Object</td></tr>' +
      '<tr><td>1 to 3</td><td>Yes</td><td>One or both set</td><td>1 to 3</td><td>1</td><td>Background</td></tr>' +
    '</tbody></table>' +
    '<div class="gbemu-example"><b>Example.</b> Colour mode, objects enabled. Background pixel colour 2 with attribute bit 7 set; object pixel colour 3 with its own bit 7 clear. With <code>LCDC</code> bit 0 set the background is shown (last row): the background bit alone is enough, the object&rsquo;s bit need not also be set. Clear <code>LCDC</code> bit 0 and the object is shown (fifth row). Keep <code>LCDC</code> bit 0 set but make the background pixel colour 0 and the object is shown (fourth row).</div>' +
    '<div class="gbemu-why"><b>Why.</b> Two priority bits, joined by an <b>or</b>: either one is enough to hold ' +
    'the background in front. And note what falls out: with the attribute forced to zero (Rule C5/3) the ' +
    'whole expression reduces to the original&rsquo;s merge rule, textually, which is why section ' +
    '5&rsquo;s discipline is worth the effort.</div>' +

    '<h4 class="gbemu-sub">In colour mode the old palette registers are not consulted at all</h4>' +
    '<div class="gbemu-rule" id="gbcr-7-3"><b>Rule C7/3.</b> In colour mode the index into the colour palette must be the <b>raw two-bit colour ' +
    'index</b>. <code>BGP</code>, <code>OBP0</code> and <code>OBP1</code> take no part.</div>' +
    '<div class="gbemu-example"><b>Example.</b> <code>BGP</code> = <code>0xFC</code> (the value ' +
    'the boot program left). <code>0xFC</code> maps indices 1, 2 and 3 all onto entry 3, ' +
    'so a core that still consults it draws colour indices 1, 2 and 3 of every background palette as that palette&rsquo;s entry 3. The correct core draws index 1 as entry 1, 2 as entry 2 and 3 as entry 3, whatever <code>BGP</code> holds.</div>' +
    '<div class="gbemu-why"><b>Why.</b> This is not ' +
    'academic: two commercial titles hold <code>BGP</code> at <code>0xFC</code> ' +
    'for 400 frames of 400, because real hardware ignores it so the ' +
    'title never bothers to write it. A core that still consults it <b>collapses three quarters of every background palette onto ' +
    'one colour</b> on exactly the titles that most need it. ' +
    'And the instrument for that reads no reference image whatsoever, which ' +
    'makes it the best kind. <b>In colour mode the hardware does not consult those registers, so a ' +
    'correct core&rsquo;s framebuffer must be invariant under perturbing them.</b> Compare the ' +
    'machine against itself. Run the negative control first: on the unmodified core the ' +
    'frame diverges on 5 of 5 cartridges, so the instrument is shown to be able to fail before it is ' +
    'believed when it passes. An invariance cannot be satisfied by fitting a core to somebody ' +
    'else&rsquo;s render.</div></section>' +

  /* ------------------------------------------------------------------- 8 */
  '<section class="sect" id="gbce-8"><h3 class="sect-h">8. Objects</h3>' +
    '<div class="gbemu-rule" id="gbcr-8-1"><b>Rule C8/1.</b> <b>Fetch order does not change.</b> Objects are fetched in ascending X, and among equal X in ascending memory index, on both ' +
        'machines and in both modes. Only the merge changes (Rule C8/2).</div>' +
    '<div class="gbemu-rule" id="gbcr-8-2"><b>Rule C8/2.</b> <b>The latched rule (Rule C8/3) selects the merge.</b> Latched bit 0 clear means the <b>lower memory index ' +
        'wins regardless of X</b>: the Color rule (the index rule). Latched bit 0 set means the original&rsquo;s smaller-X ' +
        'rule. <b>The merge, exactly:</b> an object&rsquo;s pixel replaces the one already in the object queue when the new pixel is opaque and either the queued pixel is transparent or, under the index rule only, the new object&rsquo;s memory index is lower than the queued pixel&rsquo;s. Under the smaller-X rule only the first clause applies: the first opaque arrival keeps the pixel, which, with fetch in ascending X then index (Rule C8/1), is the smaller X.</div>' +
    '<table class="gbemu-table"><thead><tr><th>Pixel already in the object queue</th><th>Arriving object&rsquo;s pixel</th><th>Index rule (latched bit 0 = 0)</th><th>Smaller-X rule (latched bit 0 = 1)</th></tr></thead><tbody>' +
      '<tr><td>Any</td><td>Transparent (colour 0)</td><td>Queued pixel kept</td><td>Queued pixel kept</td></tr>' +
      '<tr><td>Transparent</td><td>Opaque</td><td>Arriving pixel replaces it</td><td>Arriving pixel replaces it</td></tr>' +
      '<tr><td>Opaque</td><td>Opaque, arriving memory index lower</td><td>Arriving pixel replaces it</td><td>Queued pixel kept</td></tr>' +
      '<tr><td>Opaque</td><td>Opaque, arriving memory index higher</td><td>Queued pixel kept</td><td>Queued pixel kept</td></tr>' +
    '</tbody></table>' +
    '<div class="gbemu-example"><b>Example.</b> Object at memory index 5 with X = 40 (screen columns 32 to 39) and object at memory index 2 with X = 44 (columns 36 to 43), both opaque on columns 36 to 39. Fetch order (Rule C8/1): index 5 first (smaller X), then index 2. Index rule: index 2 arrives with the lower index and replaces, so columns 36 to 39 show object 2. Smaller-X rule: object 5 arrived first and keeps them. If both objects had X = 40, index 2 is fetched first and wins under both rules.</div>' +
    '<div class="gbemu-why"><b>Why.</b> Read from our source.</div>' +

    '<div class="gbemu-rule" id="gbcr-8-3"><b>Rule C8/3.</b> <b><code>0xFF6C</code> is boot-locked.</b> A build must keep two values: the register byte, and the latched rule. A write while the boot program is mapped stores the byte and latches its bit 0 as the rule ' +
        'for the session; a write after the hand-over is <em>stored and inert</em> in colour mode: the byte reads ' +
        'back, the rule does not move. ' +
        'In compatibility mode a write after the hand-over is not stored ' +
        'at all: the register keeps the <code>0x01</code> the boot program wrote and reads <code>0xFF</code> ' +
        'whatever is written. A read returns <code>0xFE</code> | bit 0 of the stored byte.</div>' +
    '<table class="gbemu-table"><thead><tr><th>When the write to <code>0xFF6C</code> is made (Color)</th><th>Stored byte</th><th>Latched rule</th><th>Read of <code>0xFF6C</code> afterwards</th></tr></thead><tbody>' +
      '<tr><td>Boot program mapped</td><td>The written byte</td><td>Bit 0 of the written byte</td><td><code>0xFE</code> OR its bit 0</td></tr>' +
      '<tr><td>After the hand-over, colour mode</td><td>The written byte</td><td>Unchanged</td><td><code>0xFE</code> OR its bit 0</td></tr>' +
      '<tr><td>After the hand-over, compatibility mode</td><td>Unchanged: <code>0x01</code> from the boot program</td><td>Unchanged</td><td><code>0xFF</code></td></tr>' +
    '</tbody></table>' +
    '<div class="gbemu-example"><b>Example.</b> Measured on the shipped core: after the real boot program, writing ' +
        '<code>0x00</code> and then <code>0x01</code> reads <code>0xFF</code> both times in compatibility mode; in colour mode the same ' +
        'writes read back <code>0xFE</code> and <code>0xFF</code>, with the rule unchanged. That is what ' +
        '<code>misc/bits/unused_hwio-C</code> needs: it writes <code>0xFF6C</code> on a cartridge with no Color flag and expects <code>0xFF</code>.</div>' +
    '<div class="gbemu-why"><b>Why.</b> <b>Keep two fields, not one:</b> one field is a ' +
        'silent bug, because a title writing <code>0xFF6C</code> mid-game would then change its own ' +
        'object priority, and no hardware does that. The read mask (<code>0xFE</code> | bit 0) is read from our source; appendix A has the register row.</div>' +

    '<div class="gbemu-rule" id="gbcr-8-4"><b>Rule C8/4.</b> The object&rsquo;s palette is <b>three bits</b> of its attribute (bits 2&ndash;0) in colour mode and ' +
        '<b>one bit</b> (bit 4) in compatibility mode, and its tile bank is another attribute bit (bit 3) that is ' +
        'ignored in compatibility mode. The whole byte is in the table below.</div>' +
    '<div class="gbemu-why"><b>Why.</b> Both were discriminated: ' +
        'one title selects object palettes 3, 5 and 6 where another selects 0, 1 and 2, so the field is known to be consumed rather than assumed to be.</div>' +
    '<h4 class="gbemu-sub">The object attribute byte, bit by bit</h4>' +
    '<p class="hw-readable">The background attribute table is in section 5 (Rule C5/1). This is its object ' +
    'counterpart, and it is not the same byte read twice: <b>bit 4 exists only here, bits ' +
    '2&ndash;0 mean something different, and the priority bit is one of two that have to agree.</b> ' +
    'Object attributes live in byte 3 of each 4-byte entry at ' +
    '<code>0xFE00</code>&ndash;<code>0xFE9F</code>; the original Game Boy&rsquo;s page, appendix C, ' +
    'has the other three bytes and they are unchanged.</p>' +
    '<table class="gbemu-table"><thead><tr><th>Attribute bit (byte 3 of the entry; bit 0 = least significant)</th><th>Meaning on the Color</th><th>In compatibility mode</th></tr></thead><tbody>' +
      '<tr><td><code>7</code></td><td>The object is held under background colours 1&ndash;3</td><td>Same, and it is the <em>only</em> priority bit: there is no background attribute</td></tr>' +
      '<tr><td><code>6</code></td><td>Flip vertically</td><td>Same</td></tr>' +
      '<tr><td><code>5</code></td><td>Flip horizontally</td><td>Same</td></tr>' +
      '<tr><td><code>4</code></td><td><b>Ignored</b></td><td><b>The palette: 0 = OBP0, 1 = OBP1.</b> This bit is the compatibility path and nothing else</td></tr>' +
      '<tr><td><code>3</code></td><td>Take this object&rsquo;s tile data from video bank 1</td><td><b>Ignored</b>: bank 0 always</td></tr>' +
      '<tr><td><code>2&ndash;0</code></td><td>Object palette, 0 to 7</td><td><b>Ignored</b></td></tr>' +
    '</tbody></table>' +
    '<div class="gbemu-example"><b>Example.</b> Object attribute <code>0x1B</code> (binary <code>0001 1011</code>). Colour mode: object palette 3 (bits 2&ndash;0), tile data from bank 1 (bit 3), bit 4 ignored. Compatibility mode: palette <code>OBP1</code> (bit 4 = 1), tile data from bank 0, bits 3 and 2&ndash;0 ignored.</div>' +
    '<div class="gbemu-why"><b>Why.</b> <b>The low nibble is where a half-finished port hides, and the shape of ' +
    'the mistake is specific.</b> Carrying bit 4 as a one-bit palette number into a colour renderer ' +
    'produces objects that are palettised, plausible and wrong, and it does it silently, ' +
    'because a one-bit number is a valid three-bit number. <b>An instrument that falls silent after a change is ' +
    'indistinguishable from one that broke</b>, and keeping one arm noisy is what makes the other ' +
    'arm&rsquo;s silence mean anything.</div>' +
    '<p class="hw-readable"><b>Two bits, one decision.</b> Whether an object is drawn over the background is Rule C7/2: on the ' +
    'Color &ldquo;held under&rdquo; is <code>(background attribute bit 7 OR object attribute bit 7) ' +
    'AND the background pixel is not colour 0</code>, with <b><code>LCDC</code> bit 0 clear forcing ' +
    'the object through regardless of both</b>. On the original the first disjunct is absent and <code>LCDC</code> bit 0 does a ' +
    'different job entirely (Rule C7/1); forcing the background attribute to zero outside colour mode (Rule C5/3) reduces ' +
    'the expression textually to the original&rsquo;s.</p>' +
    '<div class="gbemu-why"><b>Why (the trap, named on the record).</b> <b>The two merge rules agree on every scene ' +
    'where no two objects overlap</b>, so a colour path that quietly kept the original&rsquo;s merge ' +
    'would look right almost all the time. Before believing any null result here, force the ' +
    '<em>wrong</em> rule and confirm the picture moves. If the knob does not turn, nothing measured ' +
    'through it means anything.</div>' +
    '<div class="gbemu-why"><b>Why (the honest limit on this section, stated at full strength).</b> ' +
    'That both arms are correct for the mode they serve rests on <em>two source readings and on ' +
    'nothing that runs</em>. An invariance cannot reach it either, because the rule&rsquo;s inputs ' +
    '(X and memory index) are also the object&rsquo;s position, so there is nothing ' +
    'to hold still while it varies. Forcing the latch the other way does move the picture on 2 of 5 ' +
    'cartridges, so the register is demonstrably wired; the rule it selects is unverified. That is ' +
    'not a pass and it is not printed as one. It matters more than it sounds, because <b>every ' +
    'Color test this project owns runs in X priority</b>: index priority is exercised only ' +
    'by real Color titles and by one acid test.</div></section>' +

  /* ------------------------------------------------------------------- 9 */
  '<section class="sect" id="gbce-9"><h3 class="sect-h">9. Compatibility mode</h3>' +
    '<p class="hw-readable">A Color running an original cartridge is not a Game Boy. It is a Color ' +
    'with most of its colour hardware switched off and <em>one</em> piece of it very much on, and ' +
    'that piece is where compatibility-mode bugs live.</p>' +
    '<div class="gbemu-rule" id="gbcr-9-1"><b>Rule C9/1.</b> <b>In compatibility mode the colour index is resolved twice.</b> First through ' +
    '<code>BGP</code> (background), or <code>OBP0</code> or <code>OBP1</code> (an object, chosen by its attribute bit 4), exactly as on the original: a 2-bit colour index to a 2-bit shade. ' +
    'Then <em>that shade</em> is the entry number into a Color palette: background palette 0 for the background, object palette 0 or 1 (the same bit 4) for an object.</div>' +
    '<div class="gbemu-example"><b>Example.</b> Background colour index 2 with <code>BGP</code> = <code>0xE4</code> gives shade 2, so the pixel is background palette 0, entry 2: <code>0x6180</code> (blue) with the table below. With <code>BGP</code> = <code>0x1B</code> the same index gives shade 1, entry 1: <code>0x1BEF</code> (green). The colour index alone never picks the entry.</div>' +
    '<div class="gbemu-why"><b>Why.</b> The original&rsquo;s palette registers ' +
    'are alive and load-bearing on a Color. This is also the mode every test cartridge you own runs ' +
    'in, so it is the path your scores are actually measuring. A core that skips the first resolution renders a legal ' +
        'picture in the wrong four colours and fails nothing it owns until a cartridge animates its ' +
        'palette registers, which is what a third of the reference column does.</div>' +
    '<h4 class="gbemu-sub">Which registers are alive</h4>' +
    '<div class="gbemu-rule" id="gbcr-9-2"><b>Rule C9/2.</b> In compatibility mode:' +
    '<ul class="gbemu-bullets">' +
      '<li><b>Ignored:</b> writes to the video-memory bank (Rule C5/4), the work-RAM bank, the speed register ' +
        'and the block-transfer registers.</li>' +
      '<li><b>Accepted:</b> the palette <em>index</em> registers (Rule C6/4).</li>' +
      '<li><b>Ignored once the boot program has finished:</b> the palette <em>data</em> registers ' +
        '(Rules C6/4, C6/5), which is what makes the compatibility palette unreachable to the game rather than ' +
        'merely unwritten.</li>' +
    '</ul></div>' +
    '<h4 class="gbemu-sub">The compatibility palette comes out of the cartridge header</h4>' +
    '<div class="gbemu-rule" id="gbcr-9-3"><b>Rule C9/3.</b> The boot program assigns three palettes (one background, two ' +
    'object) chosen by an <b>8-bit sum of the sixteen title bytes at ' +
    '<code>0x0134&ndash;0x0143</code></b>, but <b>only if the cartridge declares a Nintendo ' +
    'licensee</b> (old licensee <code>0x01</code>, or new licensee <code>&quot;01&quot;</code>; either one is enough). ' +
    'Otherwise it returns index 0 and the machine gets the default palette (Rule C9/5).</div>' +
    '<div class="gbemu-why"><b>Why.</b> Measured, not taken on trust. Evaluating ' +
    'the table for index 0 and expanding to eight bits gives <b>six colours and no others</b>' +
    ': white, black, and four mid tones; the colour census below returns exactly that set, over the 27 scored cells in one column and the 20 in ' +
    'the other: the denominators the census table below states, and not every reference ' +
    'image in those columns, which is a broader claim than the census supports. ' +
    'The mealybug cartridges are ' +
    'not Nintendo-licensed, which is what the rule predicts. <b>So every pixel in every colour ' +
    'reference is a colour the boot program chose, and a hand-initialised palette table gets ' +
    'all 27 scored references wrong at once.</b> ' +
    'One guard travels with that census and should travel with yours: ' +
    '<b>colour-set equality is blind to placement.</b> The set and the per-pixel counts are two ' +
    'figures and are never collapsed into one, because a core tuned until it reproduces one render ' +
    'stops measuring correctness and still prints a pass.</div>' +
    '<h4 class="gbemu-sub">What the boot program actually writes, and the table this page cannot give you</h4>' +
    '<p class="hw-readable">The rule above picks an <em>index</em>. What that index selects is ' +
    '<b>three palettes of four colours (one background, two object) 24 bytes in ' +
    'total</b>, written into colour palette memory through <code>0xFF69</code> and ' +
    '<code>0xFF6B</code> before the handover and unreachable to the cartridge afterwards (Rule C9/2). Two ' +
    'structural facts follow from that and are worth stating before the gap:</p>' +
    '<ul class="gbemu-bullets">' +
      '<li><b>Only background palette 0 and object palettes 0 and 1 are ever loaded.</b> The other ' +
        '<b>seven</b> background palettes and <b>six</b> object palettes ' +
        'are left at whatever colour memory powers up holding, and nothing in ' +
        'compatibility mode can reach them: the attribute path is off and the object palette ' +
        'number is bit 4, which selects one of two. <b>Check that arithmetic against the count of ' +
        'palettes:</b> there are <b>eight</b> of each kind, as the 64 bytes of Rule C6/1 give, so one ' +
        'loaded leaves seven and two leave six.</li>' +
      '<li><b>The double resolution (Rule C9/1) is what makes the monochrome palette registers load-bearing.</b> ' +
        '<code>BGP</code>, <code>OBP0</code> and <code>OBP1</code> still map a 2-bit index to a ' +
        '2-bit shade exactly as on the original, and <em>that shade</em> is the entry number into ' +
        'the four-colour palette above.</li>' +
    '</ul>' +
    '<p class="gbemu-key"><b>THE TABLE ITSELF IS NOT REPRODUCED HERE, AND THE REASON IS NOT ' +
    'editorial.</b> This core obtains the compatibility palette by <em>running the real boot ' +
    'program</em> and letting it write colour memory; <b>the lookup table</b> lives inside that ' +
    'program and is nowhere in this project&rsquo;s own source. So there is no row <b>of that ' +
    'table</b> that this page can ' +
    'state on its own authority, and inventing one from a secondary source would be the exact ' +
    'failure the rest of this page is written against. <b>Named as a gap rather than filled with a ' +
    'guess.</b></p>' +
    '<div class="gbemu-rule" id="gbcr-9-4"><b>Rule C9/4.</b> <b>What the host supplies for it, said plainly.</b> A build that wants the per-game palettes gets them the way our core does: <b>the host supplies the real Color boot program</b> (2,304 bytes), the core runs it, and the boot program writes the chosen palettes. A build that wants those colours <em>without</em> a boot program (a player, not our no-boot fallback) takes exactly one of these two choices:' +
    '<ol class="gbemu-steps">' +
      '<li>Load the index-0 palette (Rule C9/5) for every cartridge without the Color flag.</li>' +
      '<li>Use a published extract of the table, with the selection rule of Rule C9/3: the 8-bit sum of the title bytes <code>0x0134</code>-<code>0x0143</code>, only for a Nintendo licensee, with the fourth title byte as a tiebreak where two titles share a sum, and the index-0 entry otherwise.</li>' +
    '</ol>Neither choice is part of our core, and no board row scores the difference. <b>Our own no-boot fallback takes neither</b>: it leaves palette memory at <code>0x0000</code> (Rule C2/15).</div>' +
    '<div class="gbemu-why"><b>Why.</b> Without a boot program there are two honest choices, and both are stated so nobody has to guess. The table is firmware data: Nintendo&rsquo;s, inside the Color boot program, not ours. So this page does not print it. Choice 1 is exactly right for every cartridge the boards hold, because none of them is Nintendo-licensed, and it is what both independent builds from this page chose. It is wrong for a Nintendo-licensed title the table recognises (Tetris, for instance, gets other colours on a real Color). Choice 2 is what the site&rsquo;s own player does when a visitor has no Color boot program: it runs a small boot program of its own (no Nintendo code) that writes the colours from a third-party tabulation of the boot program&rsquo;s tables (&ldquo;Analysis of CGB bootstrap ROM Color Tables&rdquo;, Tauwasser, 2010, distributed with this site under its own terms and credited in its licence notices). That extract&rsquo;s default entry is the same twelve colours as the measured table below, which is the cross-check between the two.</div>' +
    '<p class="gbemu-key"><b>The gap stops at the lookup table, though, and an implementer can still ' +
    'reconstruct the three palettes from this page.</b> The <em>lookup table</em> ' +
    'is the boot program&rsquo;s and stays unstated. <b>The twenty-four bytes it writes are not: ' +
    'they are a measurement of this core</b>, taken the way every other figure on this page is ' +
    'taken (run the thing and read it).</p>' +
    '<div class="gbemu-rule" id="gbcr-9-5"><b>Rule C9/5.</b> The index-0 compatibility palette, at the hand-over, is the 24 bytes of the table below: a build without a boot program loads it as it stands (every byte; low byte first, as Rule C6/1).</div>' +
    '<div class="gbemu-why"><b>Why.</b> <b>MEASURED HERE</b>, and the procedure is ' +
    'the citation: compile <code>src/gb.c</code> against a <code>main</code> that sets the device ' +
    'to Color, hands it the real Color boot program and a cartridge with <b>no Color flag</b>, ' +
    'runs 200 frames and prints <code>bgpal</code> and <code>obpal</code>. Values stable from the ' +
    'handover to frame 400 and <b>identical on three different unflagged cartridges</b>, which is ' +
    'the check that this is the index-0 entry and not one cartridge&rsquo;s.</div>' +
    '<p class="hw-readable">(Our source file is named ' +
    'so the measurement can be repeated by anyone who has it; it is not needed to build. The table below ' +
    'is the complete result, every byte, and a build loads it as it stands. The same goes for every ' +
    'source name, constant or probe this page names, such as <code>CGB_NOBOOT_HANDOVER</code>, ' +
    '<code>hdma_chunk</code>, <code>ppu_out_emit</code>, <code>obj_stall_snap</code> or ' +
    '<code>test/tabprobe</code>: each marks where the behaviour lives in our tree, and the behaviour ' +
    'itself is stated in words and numbers beside it.)</p>' +
    '<table class="gbemu-table"><thead><tr><th>Palette</th><th>Entry</th><th>Bytes, low then high</th><th>Palette word</th><th>5-bit R, G, B</th><th>Colour</th></tr></thead><tbody>' +
      '<tr><td rowspan="4"><b>Background 0</b></td><td>0</td><td><code>FF 7F</code></td><td><code>0x7FFF</code></td><td><code>31, 31, 31</code></td><td>White</td></tr>' +
      '<tr><td>1</td><td><code>EF 1B</code></td><td><code>0x1BEF</code></td><td><code>15, 31, 6</code></td><td>Green</td></tr>' +
      '<tr><td>2</td><td><code>80 61</code></td><td><code>0x6180</code></td><td><code>0, 12, 24</code></td><td>Blue</td></tr>' +
      '<tr><td>3</td><td><code>00 00</code></td><td><code>0x0000</code></td><td><code>0, 0, 0</code></td><td>Black</td></tr>' +
      '<tr><td rowspan="4"><b>Object 0</b></td><td>0</td><td><code>FF 7F</code></td><td><code>0x7FFF</code></td><td><code>31, 31, 31</code></td><td>White</td></tr>' +
      '<tr><td>1</td><td><code>1F 42</code></td><td><code>0x421F</code></td><td><code>31, 16, 16</code></td><td>Pink</td></tr>' +
      '<tr><td>2</td><td><code>F2 1C</code></td><td><code>0x1CF2</code></td><td><code>18, 7, 7</code></td><td>Dark red</td></tr>' +
      '<tr><td>3</td><td><code>00 00</code></td><td><code>0x0000</code></td><td><code>0, 0, 0</code></td><td>Black</td></tr>' +
      '<tr><td rowspan="4"><b>Object 1</b></td><td>0</td><td><code>FF 7F</code></td><td><code>0x7FFF</code></td><td><code>31, 31, 31</code></td><td>White</td></tr>' +
      '<tr><td>1</td><td><code>1F 42</code></td><td><code>0x421F</code></td><td><code>31, 16, 16</code></td><td>Pink</td></tr>' +
      '<tr><td>2</td><td><code>F2 1C</code></td><td><code>0x1CF2</code></td><td><code>18, 7, 7</code></td><td>Dark red</td></tr>' +
      '<tr><td>3</td><td><code>00 00</code></td><td><code>0x0000</code></td><td><code>0, 0, 0</code></td><td>Black</td></tr>' +
    '</tbody></table>' +
    '<p class="hw-readable"><b>Three things fall out of that table that the census could not say, ' +
    'and one of them is a build rule.</b> <b>(1) The two object palettes are byte-identical</b>' +
    ': the object palette bit selects one of two <em>identical</em> palettes in compatibility ' +
    'mode, so a core that wires it to the wrong one is invisible here and will still be wrong the ' +
    'moment a colour-flagged title runs. <b>(2) Entry 3 is black and entry 0 is white in all ' +
    'three</b>, which is the ordering the monochrome shade index feeds into: shade 0 is the ' +
    'lightest. <b>(3) The six census colours are exactly these six</b>, and the dark red that the ' +
    'census found in <b>ten pixels of one cell</b> is object entry 2 of both palettes, ' +
    'which is why it is emitted so rarely and why it is <em>held</em> rather than absent. The ' +
    'census and this table were taken by different instruments and agree colour for colour; that ' +
    'agreement is the reason to believe either.</p>' +
    '<div class="gbemu-rule" id="gbcr-9-6"><b>Rule C9/6.</b> <b>Do not build on the other hundred and four bytes.</b> Nothing in compatibility mode can ' +
    'reach them (Rule C9/2), so no row on this board would move if they held anything else. What our core holds there is stated below as our ' +
    'core&rsquo;s state and not the hardware&rsquo;s.</div>' +
    '<p class="hw-readable">At the handover the remaining seven ' +
    'background palettes read <code>0x7FFF</code> throughout (the boot program&rsquo;s own ' +
    'all-white blanking pass, not the lookup table) and the remaining six object palettes ' +
    'read <code>0x0000</code>. This project ' +
    'holds no witness for what a Color leaves there.</p>' +
    '<p class="hw-readable">What <em>can</em> be stated, because it was measured here, is the entry ' +
    'the index-0 case produces: the default, and the one every test cartridge this project ' +
    'owns receives, because none of them is Nintendo-licensed. A complete colour census of both ' +
    'colour reference columns returns <b>six distinct colours and no others</b>, across 27 cells in ' +
    'one column and 20 in the other, and they are the same six. Inverting the usual 5-to-8 bit ' +
    'expansion of Rule C6/6 (<code>c8 = (c5 &lt;&lt; 3) | (c5 &gt;&gt; 2)</code>) every one of the ' +
    'six lands <b>exactly</b> on a 5-bit value with no rounding, which is itself the check that the ' +
    'census is reading real palette entries and not a resampled image:</p>' +
    '<table class="gbemu-table"><thead><tr><th>Colour</th><th>8-bit</th><th>5-bit R, G, B</th><th>Palette word</th><th>Cells carrying it</th></tr></thead><tbody>' +
      '<tr><td>White</td><td><code>255, 255, 255</code></td><td><code>31, 31, 31</code></td><td><code>0x7FFF</code></td><td>27 of 27 and 20 of 20</td></tr>' +
      '<tr><td>Black</td><td><code>0, 0, 0</code></td><td><code>0, 0, 0</code></td><td><code>0x0000</code></td><td>27 of 27 and 20 of 20</td></tr>' +
      '<tr><td>Green</td><td><code>123, 255, 49</code></td><td><code>15, 31, 6</code></td><td><code>0x1BEF</code></td><td>16 of 27 and 9 of 20</td></tr>' +
      '<tr><td>Pink</td><td><code>255, 132, 132</code></td><td><code>31, 16, 16</code></td><td><code>0x421F</code></td><td>11 of 27 and 4 of 20</td></tr>' +
      '<tr><td>Blue</td><td><code>0, 99, 198</code></td><td><code>0, 12, 24</code></td><td><code>0x6180</code></td><td>7 of 27 and 3 of 20</td></tr>' +
      '<tr><td>Dark red</td><td><code>148, 57, 57</code></td><td><code>18, 7, 7</code></td><td><code>0x1CF2</code></td><td><b>1 of 27 and 1 of 20</b></td></tr>' +
    '</tbody></table>' +
    '<div class="gbemu-why"><b>Why. MEASURED, and the denominator on the last row is the point.</b> ' +
    'That sixth colour is <b>ten pixels in a single cell</b> (' +
    '<code>m3_lcdc_obj_size_change</code>) on both columns. Ten pixels is the entire ' +
    'evidential basis for one sixth of the palette, and a core that got it wrong would lose one ' +
    'cell and look otherwise perfect. Print the denominator or the figure is a claim about ' +
    'nothing.</div>' +
    '<p class="gbemu-key"><b>What this does not tell you, stated at full strength:</b> the census ' +
    'gives the <em>set</em> of twelve slots&rsquo; values, not which slot holds which. Three ' +
    'palettes of four is twelve entries and only six distinct values, so the mapping is not ' +
    'recoverable from the set. <b>That is a limit of the census, not of this page</b>: the ' +
    'assignment is measured and tabulated above (Rule C9/5). ' +
    '<b>If you need the assignment, take it the way this core does</b>' +
    ': run the real boot program and read the 64 bytes behind <code>0xFF69</code> ' +
    '<b>and the 64 behind <code>0xFF6B</code></b> at the handover, or read them off a machine. ' +
    '<b>Both stores, not one:</b> the assignment spans <em>one background palette and both object ' +
    'palettes</em>, and section 6 says plainly that those are two separate 64-byte stores behind ' +
    'two separate index registers. <b>Twenty-four of those 128 bytes are the answer and the other ' +
    'hundred and four are not written from the lookup table</b>, which is the seven background and six object palettes the ' +
    'paragraph above already counted (the boot program&rsquo;s blanking pass leaves the seven background palettes at <code>0x7FFF</code>, as the paragraph above measures, and the six object palettes read <code>0x0000</code>; section 2 lists the whole hand-over) That procedure is reproducible, costs nothing, and is honest; a ' +
    'hand-initialised palette table is neither, and it gets all 27 scored references wrong at ' +
    'once.</p>' +
  '</section>' +

  /* ------------------------------------------------------------------ 10 */
    '<section class="sect" id="gbce-10"><h3 class="sect-h">10. Where the picture processor departs</h3>' +
    '<p class="hw-readable">Consolidated, because these are the rows a port forgets. Each is stated with what pins it. Dots in this section are numbered on the Game Boy tab&rsquo;s scale (the head of its appendix E: the line boundary is four dots before the scan, mode 3 is entered on dot 84). Every table names its scale in its header: the <b>event scale</b> (a thing happens while the picture processor processes that dot, and a read sees it from the next dot) or the <b>first-seen dot</b> (the access-scale dot from which a read sees the change, one more than the event dot).</p>' +
    '<div class="gbemu-rule" id="gbcr-10-1"><b>Rule C10/1.</b> A Color build must not implement any of these six picture behaviours of the original. In our core each one runs on the original only, behind a device test:<ul class="gbemu-bullets"><li>the palette OR transient (<code>BGP_OR_CGB</code> = 0);</li><li>the column-0 live reads at the merge (fence row G17);</li><li>the notice-dot hand-back (<code>WIN_PRIME_OBJ_DOT_CGB</code> = 0);</li><li>the object-selection gate on LCDC bit 1 (fence row G32);</li><li>the sprite-memory corruption bug (<code>oam_bug_live</code>);</li><li>the <code>STAT</code> <code>$78</code> transient.</li></ul></div>' +
    '<div class="gbemu-why"><b>Why.</b> MECHANISM, read from our source. <b>The sprite-memory corruption bug does not exist on a Color, and that is measured rather than assumed.</b> The positive control is the load-bearing half: the same cartridge corrupts <b>136</b> times on an original Game Boy and <b>0</b> times on a Color, and the same counter returns 0 over all 252 drawing-mode probes and all 33 cartridges. A null without a working control is indistinguishable from a dead instrument, and this one is not dead. (The whole bug, and what real hardware said about it, is section 5 of the original Game Boy&rsquo;s page.)</div>' +
    '<div class="gbemu-rule" id="gbcr-10-2"><b>Rule C10/2.</b> On the Color, each behaviour in this table must be built as its right-hand cell states. The rule each row points to is the full statement.</div>' +
    '<table class="gbemu-table"><thead><tr><th>Behaviour</th><th>On the Color</th><th>Full statement</th></tr></thead><tbody>' +
    '<tr><td>Objects per line</td><td><b>Unchanged at ten.</b> One site, no device split, nothing to do</td><td>(this row)</td></tr>' +
    '<tr><td>Fetcher period</td><td><b>Unchanged.</b> The attribute read is free (section 1)</td><td>(this row)</td></tr>' +
    '<tr><td>Object enable and mode-3 length</td><td><b>Different.</b> An object is fetched <em>even with objects disabled</em>, so it still costs drawing dots</td><td><a href="#gbcr-10-26">Rule C10/26</a>, the LCDC bit 1 object-selection row</td></tr>' +
    '<tr><td>Vertical scroll written mid-fetch</td><td><b>A revision split, not a mode split.</b> The original and revision C mix the two bitplanes; revision D and the Advance cache the scroll-derived row at the map fetch and cannot mix. Our core takes the revision-C behaviour</td><td><a href="#gbcr-10-26">Rule C10/26</a>, the SCY consumer row</td></tr>' +
    '<tr><td><code>LCDC</code> write phase</td><td><b>To reproduce our renders, build the original&rsquo;s two-stage train on the Color too</b>: lead 2, owed budget 5, for writes that land in mode 3 with the display on. In double speed the train has no lead dots and owes 3 dots: do not carry the original&rsquo;s constants across</td><td>Rules <a href="#gbcr-10-3">C10/3</a>, <a href="#gbcr-10-4">C10/4</a>, <a href="#gbcr-10-9">C10/9</a>, <a href="#gbcr-10-10">C10/10</a></td></tr>' +
    '<tr><td>Palette write phase</td><td>The original&rsquo;s OR transient does not happen on a Color at all, including when the Color is pretending to be one. <b>Do not implement it here</b></td><td><a href="#gbcr-10-1">Rule C10/1</a>; <a href="#gbcr-10-26">Rule C10/26</a>, the BGP row</td></tr>' +
    '<tr><td>Window</td><td>On the hardware the Color has a window-trigger glitch the original does not, and the original&rsquo;s two-dot <code>WX</code> write lead has no Color counterpart: <b>do not inherit the lead; implement the glitch</b> if you build toward the hardware. Our core does neither: it runs the original&rsquo;s <code>WX</code> lead through an unresolved row and does not ship the glitch, and that is what reproduces our renders</td><td><a href="#gbcr-10-5">Rule C10/5</a>; <a href="#gbcr-10-26">Rule C10/26</a>, the WX row</td></tr>' +
    '<tr><td><code>STAT</code> write conflict</td><td>The Color is <b>not free of one: it has two, one per speed</b>, holding different old bits. <b>Replace, do not disable.</b> This core ships both</td><td><a href="#gbcr-10-6">Rule C10/6</a></td></tr>' +
    '<tr><td>The register settling dot</td><td>At Color <b>single</b> speed there is no settling dot for the fetcher&rsquo;s registers in either reference implementation. It survives for <code>STAT</code> at both speeds, and for <code>LCDC</code> in double speed only</td><td>(this row)</td></tr>' +
    '<tr><td>Write-conflict entries for the Color&rsquo;s own registers</td><td><b>There are none.</b> The bank registers, the palette registers, the block-transfer registers and the priority register are plain end-of-cycle writes in every reference table. Do not invent a phase for them</td><td><a href="#gbcr-10-26">Rule C10/26</a>, the row for the Color&rsquo;s own registers</td></tr>' +
    '<tr><td><code>0xFEA0&ndash;0xFEFF</code></td><td><b>Revision-dependent</b>, not merely mode-dependent: different revisions mirror, mask or synthesise. <b>Do not put a single constant here</b> if you build toward the hardware; it is wrong on most of the family. <b>What a read returns in our core: <code>0xFF</code> on both machines</b>, and on a Color that return is a <em>declared</em> wrong answer</td><td>(this row)</td></tr>' +
    '</tbody></table>' +
    '<div class="gbemu-why"><b>Why, row by row.</b> <b>Object enable:</b> measured as a pure displacement: one cell&rsquo;s rows 128&ndash;143 are the original&rsquo;s render moved right by exactly 5 px on revision C and 6 px on revision D, same rows, zero residual after the shift (one object fetch). It buys zero pixels and lands because it removes a device split that should not be there. <b>Vertical scroll:</b> this is the largest revision difference on the whole suite: <b>6,217 pixels of 23,040</b> on one cell. <b>LCDC:</b> <b>the real Color does not run the train at single speed: there the write is atomic</b>, with no intermediate state, as the reference implementation this page reads records it. Our core still runs the train because the rows that would give the Color its own write phase are unresolved, so they return the original&rsquo;s value, and the reference images we score against are another emulator&rsquo;s renders, which our core matches with the train in place. An independent build with the atomic write read <code>m3_lcdc_bg_en_change</code> at 452 px, and 0 px once it built the train. <b>In double speed an intermediate returns, and it is held for 2 CPU cycles, which is one dot.</b> In a two-dot budget the original&rsquo;s pending term is a two-machine-cycle debt. Which bits the intermediate holds: the original&rsquo;s membership is stated in <a href="#gbcr-10-3">Rule C10/3</a>, and the Color&rsquo;s is not known here. <b>Palette:</b> read directly off the references: 128 transient spikes in the original&rsquo;s column, <b>zero</b> in the Color&rsquo;s. <b>Window:</b> the glitch is stated in <a href="#gbcr-10-5">Rule C10/5</a> in three sentences. The lead not to carry is the original&rsquo;s <code>WX</code> lead of <b>+2 dots</b> (appendix E.1 on the Game Boy tab). <b>The Color&rsquo;s own <code>WX</code> lead is NOT ESTABLISHED here</b>: nothing this project owns measures it, and every scored colour cell runs in compatibility mode where <code>WX</code> takes the original&rsquo;s path, so no row can see it. <b>What would settle it:</b> a colour-flagged cartridge writing <code>WX</code> at a known dot inside mode 3 and photographing the first column that carries the new value. <b>STAT:</b> doing nothing here is equally wrong and much quieter. Which bits each conflict holds is CONVERGENCE, not measurement; <a href="#gbcr-10-6">Rule C10/6</a> gives them with what would settle them. <b><code>0xFEA0&ndash;0xFEFF</code>:</b> the site carries a fence that records every Color read of this range as an unresolved row rather than an implemented one. <b>Nothing on the board covers this range at all</b>, on either machine.</div>' +
    '<h4 class="gbemu-sub">The prohibitions in that table, with their replacements</h4>' +
    '<div class="gbemu-why"><p class="gbemu-key"><b>Six rows above tell you not to carry something across, and a seventh prohibition is added in a bullet below: seven in all.</b> Six rows of the table carry a prohibition (each says the words <em>do not</em>, so the count is reproducible by reading the table rather than by trusting this sentence) and the seventh, the two-stage <code>LCDC</code> conflict&rsquo;s restriction to mode 3, appears only in the <code>LCDC</code> bullet below. <b>A prohibition with no replacement is worse than silence</b>: it tells an implementer they are about to be wrong and not how to be right, and the cost lands entirely on the colour picture, where <b>the board cannot see it either way</b> (every scored cell on the colour board runs in compatibility mode). So an implementer who gets all of these wrong has a visibly wrong colour picture and <b>zero moved rows</b> to tell them. Everything below is what this project actually holds, with the parts it does not hold marked as such.</p>' +
    '<p class="gbemu-key"><b>Enumerated, so the next reader can check the count rather than trust it</b>: <b>(1)</b> to <b>(6)</b> are rows of the table above and <b>(7)</b> is the bullet below: <b>(1)</b> do not carry the original&rsquo;s <code>LCDC</code> write constants across; <b>(2)</b> do not inherit the window&rsquo;s write lead; <b>(3)</b> replace the <code>STAT</code> write conflict rather than disabling it; <b>(4)</b> do not invent a write phase for the Color&rsquo;s own registers; <b>(5)</b> do not implement the original&rsquo;s palette OR transient, which does not happen here; <b>(6)</b> do not put a single constant at <code>0xFEA0&ndash;0xFEFF</code>; and <b>(7)</b> do not inherit our restriction of the two-stage <code>LCDC</code> conflict to mode 3. <b>Four and five carry their replacement in the row itself</b> (plain end-of-cycle writes; zero transients, read off 128 against 0 in the reference columns). <b>One, two and three are answered in the bullets below</b>, one of them (the first) by a named gap rather than a value, which is an answer. <b>Six is answered in its own row above. Seven is answered here: we hold nothing that would tell you what to re-derive it against.</b> No cartridge on the colour board moves on it, the restriction is a fit to one original-machine cartridge, and <b>what would settle it is a colour-flagged cartridge writing <code>LCDC</code> outside mode 3 at a known dot</b>, which nobody has written. <b>A count of prohibitions is itself a figure with a dependent</b>: if you add a row to the table above, this count moves with it.</p></div>' +
    '<ul class="gbemu-bullets">' +
    '<li><b>The <code>LCDC</code> intermediate (answers 1, and holds 7).</b> Rules <a href="#gbcr-10-3">C10/3</a> and <a href="#gbcr-10-4">C10/4</a> give the train our core runs and its membership; the Color&rsquo;s own membership is NOT ESTABLISHED. <b>And one more thing not to carry across:</b> restricting the two-stage conflict to mode 3 is <em>ours</em> and is a fit to one original-machine cartridge, not a mechanism (it must be re-derived for the Color, never inherited). Our core carries it on the Color as an adopted guard value (<code>LCDC_M3ONLY_CGB</code> = 1, <a href="#gbcr-10-3">Rule C10/3</a>).</li>' +
    '<li><b>The window-trigger glitch (answers 2).</b> <a href="#gbcr-10-5">Rule C10/5</a>.</li>' +
    '<li><b>The two <code>STAT</code> write conflicts (answers 3).</b> <a href="#gbcr-10-6">Rule C10/6</a>.</li>' +
    '<li><b><code>LYC</code>&rsquo;s phase.</b> <a href="#gbcr-10-7">Rule C10/7</a>.</li>' +
    '</ul>' +
    '<div class="gbemu-rule" id="gbcr-10-3"><b>Rule C10/3.</b> <b>The LCDC write at single speed.</b> For an LCDC write that lands in mode 3 with the display on, our core runs the original&rsquo;s two-stage train on the Color at single speed: lead 2, owed budget 5 (the Game Boy tab&rsquo;s E.1.3 and E.9.1). Its dots are given in <a href="#gbcr-10-9">Rule C10/9</a>. On the conflict dot the register holds the intermediate <code>old | (new &amp; 1)</code> (with LCDC bit 0 as the 1), with one change: when the written value has bit 1 (object enable) clear, the intermediate has bit 1 clear too, wherever on the line the write lands. Mode 3 here is the internal drawing mode at the start of the write&rsquo;s machine cycle (the Game Boy tab, E.9.1). An LCDC write that lands outside mode 3, or with the display off, takes no train: every consumer sees the whole new value from N + 4 (<a href="#gbcr-10-26">Rule C10/26</a>, the outside-mode-3 row).</div>' +
    '<div class="gbemu-example"><b>Example.</b> Three single-speed writes in mode 3, each from LCDC = <code>$E3</code> or <code>$E2</code>. (a) <code>$E2</code> to <code>$E3</code> (a set of bit 0): the intermediate is <code>$E2 | ($E3 &amp; 1)</code> = <code>$E3</code>, so the set of bit 0 is visible on the conflict dot. (b) <code>$E3</code> to <code>$E2</code> (a clear of bit 0): the intermediate is <code>$E3 | ($E2 &amp; 1)</code> = <code>$E3</code>, so bit 0 still reads 1 on the conflict dot and the clear arrives on C, a dot late. (c) <code>$E3</code> to <code>$E1</code> (a clear of bit 1): <code>$E3 | 1</code> = <code>$E3</code>, and bit 1 is then cleared, so the intermediate is <code>$E1</code>: the cleared object enable reaches the outstanding-work test on C &minus; 1 and the merge on C. A write that <em>sets</em> bit 1 reaches them on C and C + 1.</div>' +
    '<div class="gbemu-why"><b>Why.</b> <b>Every bit holds its old value except that a <em>set</em> of bit 0 is visible immediately</b>, so clearing any bit, bit 0 included, and setting any bit but bit 0, is a dot late. <b>A <em>clear</em> of bit 0 is held for the dot exactly like every other bit</b>: an OR can only ever turn a bit on, so <code>old | (new &amp; 1)</code> cannot pass a clear through early, whatever the shorthand &ldquo;bit 0 is immediate&rdquo; suggests. The object-enable change is the original&rsquo;s documented carve-out (the original&rsquo;s E.1.3 carries it: a write that <em>clears</em> object-enable takes effect immediately, not a dot late, when it lands at the start of a line or during an object fetch). As our core ships it, that condition is dropped; the conditional form is refuted (the original&rsquo;s E.1.3, &ldquo;The object-enable exception, as our core ships it&rdquo;). Build the unconditional form. Without that carve-out the intermediate keeps objects enabled for one dot and a mode-0 timing cartridge fails, so it is not a detail. <b>That is the whole membership, and it is the original&rsquo;s</b>: a claim to be stating <em>the</em> membership has to state all of it or say which part it is leaving out. <b>On the hardware, at Color single speed there is no intermediate at all.</b> In double speed one exists and is held for <b>2 CPU cycles, which is one dot</b>. <b>Which bits the Color&rsquo;s intermediate holds is NOT ESTABLISHED here</b>: what is recorded is that it exists and how long it lasts, read off one reference implementation that distinguishes the original, Color single speed and Color double speed, and no reading on this disk supports a statement about its membership in either direction. Its two Color arms are not transcribed: the site is left explicitly unresolved rather than given the original&rsquo;s value as a Color arm, <em>because a guard whose arms agree removes the question instead of answering it</em>. <b>At run time, though, an unresolved site returns the original&rsquo;s value</b> (and records the breach), so on the core this site ships a Color <em>does</em> run the original&rsquo;s two-stage train for <code>LCDC</code>, lead 2 and owed budget 5, in mode 3. That is a declared placeholder, not a claim about the hardware, and the tile-data select rules (Rules <a href="#gbcr-10-8">C10/8</a> to <a href="#gbcr-10-24">C10/24</a>) hang on exactly that train. The restriction to mode 3 is an adopted guard value, not derived for the Color (the bullet above). MECHANISM, read from our source.</div>' +
    '<div class="gbemu-rule" id="gbcr-10-4"><b>Rule C10/4.</b> <b>The LCDC write in double speed.</b> For an LCDC write that lands in mode 3 with the display on in double speed, our core runs the same train with no lead dots: the conflict dot is N, the commit dot C is N + 1, where N is the first dot of the write&rsquo;s two-dot machine cycle. The write then owes 3 dots: the original&rsquo;s budget of 5, less the 2 dots a two-dot machine cycle lacks (less any lead the cycle could not withhold). The next machine cycle&rsquo;s access lands exactly where it would without the write.</div>' +
    '<div class="gbemu-example"><b>Example.</b> A double-speed write cycle covers dots 106 and 107. The conflict dot is 106 and C is 107, there are no lead dots, and three dots are owed, so the next cycle&rsquo;s access lands after dot 109, exactly where it would without the write. Owing five here instead lands the access after dot 111 and leaves the picture two dots ahead.</div>' +
    '<div class="gbemu-why"><b>Why.</b> E.5&rsquo;s conservation rule on the Game Boy tab says a machine cycle must tick <code>2B</code> dots across its two halves. Three owed dots is the construct the palette writes already use, so the picture and the processor stay level. Measured on a probe of our own: the drift is 0.000 dots per write in double speed and 0.000 at single speed. The lead and conflict-dot positions inside the cycle are as <a href="#gbcr-10-26">Rule C10/26</a>&rsquo;s LCDC row gives them. No cartridge we hold writes LCDC during mode 3 in double speed, so nothing scored moves, and no cell measures the double-speed train.</div>' +
    '<div class="gbemu-rule" id="gbcr-10-5"><b>Rule C10/5.</b> <b>The window-trigger glitch is not shipped.</b> Our core carries the glitch below behind a switch that is off (<code>WIN_CGB_GLITCH</code> = 0). At that setting the per-step flag it would set is never written, so it changes nothing. To reproduce our renders, do not build it.</div>' +
    '<div class="gbemu-why"><b>The glitch, in three sentences, which is the whole of it</b> (for a build aimed at the hardware). <b>(1)</b> On a line whose window is enabled and armed, the Color holds a condition the original does not: it holds on the dot at which the fetch&rsquo;s position equals <code>WX</code> (offset by one while the window&rsquo;s own first fetch is still outstanding) and, for a <code>WX</code> of zero, throughout the line&rsquo;s pre-visible columns instead, or at the last of them when the fine scroll is non-zero. <b>(2)</b> A fetch step whose read dot falls under that condition <b>does not read video memory</b>: the tile-number step keeps the number it already had, the low data step takes the <em>high</em> byte of the previous row, and the high data step then takes that same byte back from the low. <b>(3)</b> The fetch keeps its length: nothing is added or removed, only the bus access is dropped. <b>LABEL: CONVERGENCE</b> (SOURCE-READ / CONVERGENCE for the shape, NOT ESTABLISHED for any effect). It is the shape of one reference implementation&rsquo;s condition and the set of reads it suppresses; no expression, constant or control structure was transcribed, and nothing measures it here. The table row above (&ldquo;implement the glitch&rdquo;) is advice for the hardware, not a description of what our core does.</div>' +
    '<div class="gbemu-rule" id="gbcr-10-6"><b>Rule C10/6.</b> <b>The two STAT write conflicts.</b> On the Color a STAT write has no lead, and for one dot <code>STAT</code> holds an intermediate of old and new bits, then the written bits. The dots are on the event scale, counted from N, the first dot of the write&rsquo;s machine cycle (the Game Boy tab&rsquo;s E.1.1):' +
    '<table class="gbemu-table"><thead><tr><th>Speed</th><th>Intermediate held on (event scale, counted from N)</th><th>Bits still old in the intermediate</th><th>Bits already new in the intermediate</th><th>Written bits from (event scale, counted from N)</th></tr></thead><tbody>' +
    '<tr><td>single speed</td><td>N + 4</td><td>bit 6 (the coincidence select)</td><td>bits 5&ndash;3</td><td>N + 5</td></tr>' +
    '<tr><td>double speed</td><td>N + 2</td><td>bit 3 (the horizontal-blank select)</td><td>bits 6&ndash;4</td><td>N + 3</td></tr>' +
    '</tbody></table>' +
    'The original&rsquo;s all-selects moment (<code>$78</code> in <code>STAT</code> for one dot) must not be built on the Color, at either speed.</div>' +
    '<div class="gbemu-example"><b>Example.</b> At single speed, STAT&rsquo;s selects hold <code>$40</code> (coincidence select only) and the processor writes <code>$08</code>. On N + 4 the selects read <code>$48</code>: bit 6 still old (1), bits 5 to 3 new (0, 0, 1). From N + 5 they read <code>$08</code>. In double speed, from <code>$08</code> writing <code>$40</code>: on N + 2 the selects read <code>$48</code> (bit 3 still old, bits 6 to 4 new), and from N + 3 <code>$40</code>.</div>' +
    '<div class="gbemu-why"><b>Why.</b> <b>This core ships both, and the bits are CONVERGENCE, not measurement</b> (SOURCE-READ / CONVERGENCE). One reference implementation distinguishes the original, Color single speed and Color double speed, and <b>holds a different old bit in each of the two Color cases</b>; the table is read off its source. That reference marks its own value unverified, and <b>why each speed holds the bit it holds is NOT ESTABLISHED</b>. What <em>is</em> established, by behaviour, is that the original&rsquo;s all-selects moment is absent on the Color: carried across, it leaves a stale status-interrupt request after a <code>STAT&nbsp;=&nbsp;$00</code> write in vertical blank, which fires the moment the game enables interrupts and derails five licensed titles across three games; the Color&rsquo;s conflicts in its place restore all five. <b>Do not reach for the original&rsquo;s conflict to fill the gap.</b> The original <em>does</em> ship one, and it is the wrong thing for a Color: appendix E.1 on the Game Boy tab gives <code>STAT</code> a lead of <b>0</b> plus a one-dot transient on the original, in which a write first puts <code>$78</code> in <code>STAT</code> (every interrupt source selected, as if <code>$FF</code> had been written) and only then the written bits. <code>0x78</code> is also <code>STAT</code>&rsquo;s write mask (the bits 6&ndash;3 a write keeps), which is why the moment has that value: the writable bits of <code>$FF</code>. The table row&rsquo;s advice stands (the Color&rsquo;s two conflicts are real and replace-not-disable is right), and the original&rsquo;s moment is the one thing not to carry across. Discharged, three arms (G11). <b>What would settle the held bits:</b> nothing we own. <b>No test cartridge in this project sees the bits move</b> (the five titles above separate &ldquo;the original&rsquo;s moment&rdquo; from &ldquo;not that&rdquo;, and nothing more), so the route to measurement is a cartridge written to sample <code>STAT</code> across a write at both speeds, which nobody has.</div>' +
    '<div class="gbemu-rule" id="gbcr-10-7"><b>Rule C10/7.</b> <b>LYC&rsquo;s phase.</b> Our core gives an <code>LYC</code> write the original&rsquo;s lead of &minus;1 at both Color speeds: the coincidence comparator first reads the new value on N + 5 at single speed and on N + 3 in double speed (event scale, from N, the first dot of the write&rsquo;s machine cycle; <a href="#gbcr-10-26">Rule C10/26</a>).</div>' +
    '<div class="gbemu-why"><b>Why.</b> E.1 on the Game Boy tab ships <code>LYC</code> at a lead of &minus;1 on an analogy to the interrupt-flag register, calls the analogy unpinned, and says the sharing is wrong in principle <em>because <code>LYC</code>&rsquo;s phase is speed-dependent on the Color</em>. What that means: on the Color the coincidence comparator takes <b>the processor-side phase at single speed and the old value in double speed</b>, so one constant cannot serve both and the original&rsquo;s &minus;1 is the original&rsquo;s. Our core still uses the one value at both speeds, because the row is unresolved (G10) and returns the original&rsquo;s value. <b>LABEL: NOT ESTABLISHED on either machine.</b> The split is read off the same source that states it; nothing this project owns distinguishes <code>LYC</code> from the interrupt-flag register on the original either, which is why the two share one constant there and why that sharing is recorded as a defect rather than a design.</div>' +
    '<p class="hw-readable">The colour board&rsquo;s last closed cell depends on the Color&rsquo;s tile-data select glitches, described next.</p>' +
    '<h4 class="gbemu-sub">The tile-data select change glitches</h4>' +
    '<p class="hw-readable">A write that changes <code>LCDC</code> bit 4 (the tile-data select) during drawing does more on a Color than move the base address. On a few dots around the write, a background or window tile-data read does not deliver what video memory holds at its address. It delivers a substitute instead: the tile number, or a byte left over from an earlier read. This subsection is everything our core does about that, with the label on each piece. Nothing in the rest of this page describes it, and a core built from the rest of this page renders the four tile-select cells wrong on the colour board.</p>' +
    '<div class="gbemu-rule" id="gbcr-10-8"><b>Rule C10/8.</b> <b>Where it applies.</b> Rules <a href="#gbcr-10-8">C10/8</a> to <a href="#gbcr-10-24">C10/24</a> apply to the Color device only, in compatibility mode and in colour mode alike: every one of them is gated on the device, not on the mode. They never apply to the original Game Boy. They touch exactly two fetcher steps: the tile-data low read and the tile-data high read, of both the background fetch and the window fetch. The tile-number read is never substituted, and object fetches are never substituted (they only feed the stashes of <a href="#gbcr-10-20">Rule C10/20</a>).</div>' +
    '<div class="gbemu-why"><b>Why.</b> The original&rsquo;s board does not pass through any of it, by construction. Every scored cell that exercises it runs in compatibility mode, so nothing here has been seen in colour mode proper.</div>' +
    '<p class="hw-readable"><b>What it hangs on, and the caveat that comes first.</b> Every trigger below is a dot of the display-control write train that the Game Boy tab decodes in appendix E.9: two lead dots, the conflict dot, and the commit dot. On the Color our core runs that train for LCDC exactly as <a href="#gbcr-10-3">Rule C10/3</a> states (the original&rsquo;s lead of 2 and owed budget of 5, only for writes that land in mode 3 with the display on), and to reproduce our renders you must run it too. A write that lands outside mode 3 takes no train, so none of these rules can fire for it. The departures table (<a href="#gbcr-10-2">Rule C10/2</a>) gives both halves: the train our core runs, which is what this subsection needs, and the atomic write the Color makes at single speed, which is the hardware.</p>' +
    '<div class="gbemu-rule" id="gbcr-10-9"><b>Rule C10/9.</b> <b>The four dots of the train.</b> <code>C</code> is the commit dot of E.9: the first dot on which a nominal consumer (tag 8) reads the new value. At single speed an LCDC write that takes the train (<a href="#gbcr-10-3">Rule C10/3</a>) has these four dots, and the register holds these values on them:' +
    '<table class="gbemu-table"><thead><tr><th>Dot</th><th>Position (event scale, in dots counted from <code>C</code>)</th><th>How our core recognises it</th><th>Register holds</th></tr></thead><tbody>' +
    '<tr><td>first lead dot</td><td><code>C - 3</code></td><td>the early-visibility countdown (<code>lcdc_pre</code>) reads 2</td><td>the pre-write value</td></tr>' +
    '<tr><td>last lead dot</td><td><code>C - 2</code></td><td>the early-visibility countdown reads 1</td><td>the pre-write value, except bits 5 and 6, which our core has already written new (<a href="#gbcr-10-27">Rule C10/27</a>)</td></tr>' +
    '<tr><td>conflict dot</td><td><code>C - 1</code></td><td>the conflict flag (<code>lcdc_conf</code>) is raised; the countdown has just reached 0</td><td>the two-stage intermediate of <a href="#gbcr-10-3">Rule C10/3</a>, which carries the OLD bit 4</td></tr>' +
    '<tr><td>commit dot</td><td><code>C</code></td><td>the late countdown (<code>lcdc_late</code>), armed to 2 when the conflict dot ends, reads 1</td><td>the new value</td></tr>' +
    '</tbody></table>' +
    'Our core decrements each of the three counters at the head of each dot, before any consumer on that dot reads it. In double speed the owed budget entering the write is 2, the lead is therefore empty, and only the conflict dot and the commit dot exist (<a href="#gbcr-10-4">Rule C10/4</a>).</div>' +
    '<div class="gbemu-why"><b>Why.</b> The counter order is the trap E.9 names: a counter armed to 2 is seen as 1 on the first dot. The internal names are given only so a reader of the source can find them. No cell measures the double-speed case.</div>' +
    '<div class="gbemu-rule" id="gbcr-10-10"><b>Rule C10/10.</b> <b>Where <code>C</code> sits against the write&rsquo;s own machine cycle.</b> <b><code>C</code> is the last of the four dots that belong to the write&rsquo;s own machine cycle: the dot after which a read in that same machine cycle would sample.</b> The two lead dots and the conflict dot are the cycle&rsquo;s first three dots. At single speed a Color machine cycle covers dots 4k + 2 to 4k + 5 (<a href="#gbcr-10-47">Rule C10/47</a>), so on our Color <code>C</code> is always a dot of the form 4k + 1; on our original it is of the form 4k. What a build must match is the absolute dot of each train event and the dot after which the next machine cycle&rsquo;s access lands; which machine cycle processes which owed dot is our bookkeeping, not an observable.</div>' +
    '<div class="gbemu-example"><b>Example 1 (bookkeeping).</b> A single-speed write cycle covers dots 98 to 101. The lead dots are 98 and 99, the conflict dot is 100 and C is 101. Our write&rsquo;s cycle processes only 98 to 100; the five owed dots, 101 to 105, are processed by the next machine cycle before its access, which lands after 105, exactly where it would without the write. A build that processes 98 to 101 inside the write&rsquo;s own cycle and 102 to 105 in the next one produces the same picture and the same access dots; nothing a program can read separates the two. When the write sets the tile-data select bit, the background set rule&rsquo;s dot (<a href="#gbcr-10-19">Rule C10/19</a>) is spent on C inside the write&rsquo;s own cycle and four dots are owed instead of five; the sum is the same.</div>' +
    '<div class="gbemu-example"><b>Example 2 (measured).</b> <code>m3_lcdc_tile_sel_win_change</code> line 20: the write that sets bit 4 has its lead dots on 106 and 107, its conflict dot on 108 and <code>C</code> on 109 on the Color; on the original the same write has them on 105, 106, 107 and 108. Bits 5 and 6 enter the register on the last lead dot (107 on the Color, 106 on the original), as <a href="#gbcr-10-27">Rule C10/27</a> says.</div>' +
    '<div class="gbemu-why"><b>Why.</b> Built from the counters literally, every LCDC consumer lands two dots late; this rule gives the position in absolute dots. On our Color at single speed every processor access sees the picture state after a line dot of the form 4k&nbsp;+&nbsp;1 on E&rsquo;s scale, which is why <code>C</code> is always of that form. The double-speed case is <a href="#gbcr-10-4">Rule C10/4</a>. The Game Boy tab&rsquo;s E.9.1 gives the original&rsquo;s train dot by dot and, for every LCDC consumer, the dot it first sees the new value on each machine and speed. <b>INSTRUMENT-MEASURED</b> on the shipped core with a per-dot probe and a colour-flagged probe cartridge of our own; compatibility mode gave the same dots as colour mode, and no scored cell runs the double-speed case.</div>' +
    '<h4 class="gbemu-sub">Which base each data read forms its address on</h4>' +
    '<div class="gbemu-rule" id="gbcr-10-11"><b>Rule C10/11.</b> Before any substitution, each tile-data read forms its address with bit 4 at its own settling, on the scale of E.1.3 and E.9. On the Color these are the settlings (the original&rsquo;s rows in E.1.3 are not the Color&rsquo;s):' +
    '<table class="gbemu-table"><thead><tr><th>Read</th><th>Tag on the Color</th><th>Dots on which it sees the new bit 4 (event scale, counted from <code>C</code>)</th><th>Label</th></tr></thead><tbody>' +
    '<tr><td>background, low and high</td><td>8</td><td><code>C</code> onward (nominal)</td><td>MECHANISM, as E.1.3 states for the background data path: read live at both data steps</td></tr>' +
    '<tr><td>window, low</td><td>10</td><td><code>C - 2</code> onward, for either direction</td><td>FITTED, to the stored revision-C render; recorded as pure gain, no cell worse on either board</td></tr>' +
    '<tr><td>window, high</td><td>12</td><td>for a write that CLEARS bit 4: <code>C - 2</code> onward. For a write that sets it: <code>C</code> onward</td><td>FITTED, to the stored revision-C render. Tag 12 is ours and is not in E.9: it is tag 10 opened only in the clearing direction</td></tr>' +
    '</tbody></table></div>' +
    '<div class="gbemu-why"><b>Why.</b> One of these, tag 12, is a member that E.9 does not list.</div>' +
    '<p class="hw-readable">Two further rules then act on the window&rsquo;s high read only. They choose the base, they do not substitute a byte, and they apply in the order of <a href="#gbcr-10-14">Rule C10/14</a>.</p>' +
    '<div class="gbemu-rule" id="gbcr-10-12"><b>Rule C10/12.</b> <b>The conflict-dot override.</b> A window high read whose read dot is the conflict dot takes the INCOMING bit 4 when, and only when, an object fetch has already ended on this line and the read dot minus the dot on which the most recent such object fetch ended is 8 or more.</div>' +
    '<div class="gbemu-example"><b>Example.</b> On a line where the most recent object fetch ended on dot 100, a window high read on the conflict dot 108 (age 8) takes the incoming bit 4; the same read on conflict dot 107 (age 7) takes the bit as tag 12 gives it. On a line with no object fetch ended yet, the override never acts.</div>' +
    '<div class="gbemu-why"><b>Why.</b> Without that condition the rule is refuted: the bare conflict-dot rule is shared by seven bands, and the reference takes the incoming value in one of them and the outgoing value in five. A census of sixteen quantities at all 104 conflict-dot high reads found fourteen identical across the split; only the object quantities varied, which is where the condition comes from. The value 8 is FITTED and carried flagged: the age 7 never occurs at a conflict-dot read in the corpus (the firing ages are 6, 8, 11, 16, 19, 27, 35, 43, 59 and 67 over 1,600 evaluations), so 7 and 8 cannot be told apart here. That is a hole in the sample, not in the quantity. A core whose objects sit differently must re-derive it. The age is read from our source (<code>HI_CONF_AGE</code>: the read dot minus the object fetch&rsquo;s end dot, compared as 8 or more).</div>' +
    '<div class="gbemu-rule" id="gbcr-10-13"><b>Rule C10/13.</b> <b>The stalled-high latch.</b> A window fetch whose high read runs on schedule takes bit 4 at its own settling. A window high read that runs <b>late</b>, meaning its read dot minus its own tile&rsquo;s low-read dot is more than 2, keeps the base its LOW read used, but only in one direction: when the low read used the <code>$9000</code> (signed) base and the high read would now use <code>$8000</code>. The latch takes effect on a line only if the same late-high condition also arose on the previous line; on the first line of a run the condition is noted and the latch does not act. It never applies to background fetches.</div>' +
    '<div class="gbemu-why"><b>Why.</b> A high read runs late when an object stall has pushed it. The 2 is DERIVED, not chosen: the low-to-high spacing is 2 dots on 2,808 of 2,880 window high reads, and 3 to 6 occur nowhere. The direction and the first-line exemption are FITTED, to the stored revision-C render, with no derivation recorded. Applying the latch to background fetches as well is REFUTED: it costs <code>m3_lcdc_tile_sel_change</code> 8 px to 180.</div>' +
    '<p class="hw-readable">One existing mechanism also reaches this select, and it is on the Game Boy tab already: after an object stall, a fetch step may take its address inputs from the snapshot taken on the dot it would have executed on (E.3.3). That snapshot records the window&rsquo;s tile-data select at the low read&rsquo;s tag (10) for both planes.</p>' +
    '<div class="gbemu-rule" id="gbcr-10-14"><b>Rule C10/14.</b> <b>The order of the three, on one data read, as the shipped core forms the address:</b>' +
    '<ol class="gbemu-steps">' +
    '<li>Take the select: from the stalled-fetch recording (E.3.3) if this step is one the recording covers, otherwise from the live register at the read&rsquo;s own tag (<a href="#gbcr-10-11">Rule C10/11</a>).</li>' +
    '<li>Window high read only: the conflict-dot override (<a href="#gbcr-10-12">Rule C10/12</a>) may replace it.</li>' +
    '<li>The stalled-high latch (<a href="#gbcr-10-13">Rule C10/13</a>) acts on that result: a low read stores the select it used, recorded or live, with its dot; a high read more than 2 dots later whose select is the unsigned base while the stored one is the signed base takes the stored one, subject to the first-line exemption.</li>' +
    '</ol>' +
    'So the latch does act on a select that came from the recording. A read&rsquo;s dot (&ldquo;its dot&rdquo;) is the dot on which the read executes, the second dot of its two-dot step.</div>' +
    '<div class="gbemu-why"><b>Why.</b> The latch&rsquo;s price depends on this order. And &ldquo;the start of the dot&rdquo; in the Game Boy tab&rsquo;s E.3.3 means the register as every consumer on that dot reads it: a processor write first seen on dot d is included, because the processor&rsquo;s writes land between dots and nothing inside a dot changes SCX or SCY.</div>' +
    '<h4 class="gbemu-sub">The four substitution rules</h4>' +
    '<div class="gbemu-rule" id="gbcr-10-15"><b>Rule C10/15.</b> A tile-data read is substituted when its read dot (the second dot of the two-dot step, the dot that executes it) is one of the dots this table names for a rule, and the write is in that rule&rsquo;s direction. A write <em>sets</em> bit 4 when the incoming value has bit 4 set and the &ldquo;before&rdquo; value (<a href="#gbcr-10-16">Rule C10/16</a>) has it clear; it <em>clears</em> bit 4 when the incoming value has it clear and the &ldquo;before&rdquo; value has it set. Every rule applies to the low read and the high read alike; the plane matters only for which half of a stash is taken.' +
    '<table class="gbemu-table"><thead><tr><th>Rule</th><th>Layer</th><th>Write</th><th>Fires on a read whose read dot is (event scale, dots of the train, <a href="#gbcr-10-9">Rule C10/9</a>)</th><th>The read delivers</th><th>Label</th></tr></thead><tbody>' +
    '<tr><td>Background set</td><td>background</td><td>sets bit 4</td><td>the commit dot <code>C</code></td><td>the background set substitute (<a href="#gbcr-10-21">Rule C10/21</a>). Video memory is not read at all</td><td>shape: SOURCE-READ / CONVERGENCE. Dot: FITTED</td></tr>' +
    '<tr><td>Window set</td><td>window</td><td>sets bit 4</td><td>the last lead dot or the conflict dot</td><td>the window set substitute (<a href="#gbcr-10-22">Rule C10/22</a>), else the byte actually read</td><td>shape: MECHANISM from one written account. Dots and source order: FITTED</td></tr>' +
    '<tr><td>Window clear</td><td>window</td><td>clears bit 4</td><td>the last lead dot or the conflict dot</td><td>the tile number, if its top bit is clear; otherwise the byte actually read</td><td>shape: SOURCE-READ / CONVERGENCE. Dots: FITTED</td></tr>' +
    '<tr><td>Background clear</td><td>background</td><td>clears bit 4</td><td>the commit dot <code>C</code>, unless an object fetch ended on this line fewer than 5 dots before the read dot (<a href="#gbcr-10-18">Rule C10/18</a>)</td><td>the tile number, if its top bit is clear; otherwise the byte actually read</td><td>shape: SOURCE-READ / CONVERGENCE. Dot and the 5: FITTED</td></tr>' +
    '</tbody></table></div>' +
    '<div class="gbemu-rule" id="gbcr-10-16"><b>Rule C10/16.</b> <b>The &ldquo;before&rdquo; value in the direction test.</b> On the two lead dots it is the register as it stands, which is still the pre-write value. On every other dot it is a stored copy of the pre-write value of the most recent display-control write sequence; our core updates that copy when the conflict dot ends, and sets it to zero at reset. So on the conflict dot itself the comparison is made against the PREVIOUS write&rsquo;s pre-write value, not this one&rsquo;s.</div>' +
    '<div class="gbemu-example"><b>Example.</b> A train of LCDC writes alternates set and clear of bit 4. On a set write&rsquo;s conflict dot the stored copy is the previous (clear) write&rsquo;s pre-write value, which has bit 4 set, so the incoming set bit 4 does not count as a set against it, and no rule fires there. The same happens on every clear write&rsquo;s conflict dot. So in such a train the conflict dot never qualifies, and the window rules fire on the last lead dot only.</div>' +
    '<div class="gbemu-why"><b>Why.</b> That is what our core does, and it has a visible consequence (the example). It is not a rule anyone chose and it is flagged, not defended.</div>' +
    '<div class="gbemu-rule" id="gbcr-10-17"><b>Rule C10/17.</b> <b>The tile number stands in.</b> For the two clear rules the delivered byte is the tile number from this fetch&rsquo;s map read, used as data, and only while that number&rsquo;s top bit is clear. With the top bit set the read is not disturbed.</div>' +
    '<div class="gbemu-why"><b>Why.</b> Both reference sources agree on the stand-in and on its top-bit qualification. One reference implementation goes further and, on the signed base, substitutes a byte saved from the previous glitched read; our core carries that variant only behind a switch that is off, and it is not what ships.</div>' +
    '<div class="gbemu-rule" id="gbcr-10-18"><b>Rule C10/18.</b> <b>The recency suppression.</b> The background clear rule does not fire when an object fetch has ended on the same line and the read dot minus the end dot of the most recent such fetch is 0 to 4. When the read is one whose registers were recorded by E.3.3&rsquo;s stall recording, both apply, in this order: the recording decides the <em>base</em> the read forms its address on (the recorded LCDC); then this suppression and the substitution rules are decided on the read&rsquo;s own dot from the live write train (where the LCDC write stands, the old and incoming bit 4, and the dots since the object fetch ended); then the rule.</div>' +
    '<div class="gbemu-why"><b>Why.</b> FITTED, to the stored revision-C render, and load-bearing: without it <code>m3_lcdc_tile_sel_change</code> reads 124 px instead of 8. It is a threshold read off this corpus&rsquo;s object spacing and must be re-derived on a different one. Read from our source (the rules test the live train; the recorded value is used only for the address; <code>BG_TSEL_RST_RECENCY</code> compares the read dot minus the end dot as less than 5).</div>' +
    '<div class="gbemu-rule" id="gbcr-10-19"><b>Rule C10/19.</b> <b>Costs no dot.</b> None of these rules adds or removes a dot. The background set rule&rsquo;s dot is one of the write&rsquo;s own owed dots, spent inside the write with the condition raised and then taken out of the owed budget.</div>' +
    '<div class="gbemu-why"><b>Why.</b> MECHANISM for the budget: the write&rsquo;s length is unchanged.</div>' +
    '<h4 class="gbemu-sub">The three stashes, and which substitute each rule takes</h4>' +
    '<div class="gbemu-rule" id="gbcr-10-20"><b>Rule C10/20.</b> The set rules deliver a byte from an earlier read. Our core keeps three stashes for that. None is ever cleared except by a machine reset: they persist across lines, across frames and across the display being switched off.' +
    '<table class="gbemu-table"><thead><tr><th>Stash</th><th>What writes it</th><th>Label</th></tr></thead><tbody>' +
    '<tr><td><b>Last unsigned byte</b></td><td>Every object data read (objects always use the <code>$8000</code> base; the high byte is written last, so it is what remains), and every background or window data read whose address was formed on the <code>$8000</code> base. It holds the raw byte as read from memory, before any flip. One exception, and it is ours: a tile&rsquo;s HIGH read does not write the stash if an object fetch ended after that tile&rsquo;s LOW read. A byte substituted by the background set rule on a low read writes nothing.</td><td>SOURCE-READ / CONVERGENCE (one source-read implementation: &ldquo;the last tile data read in unsigned addressing, object fetches included&rdquo;). The exception: MECHANISM by argument, load-bearing by ablation</td></tr>' +
    '<tr><td><b>Last object byte</b></td><td>Every object data read, and nothing else: the high byte of the most recently fetched object</td><td>MECHANISM from one written account (&ldquo;bitplane 1 of the most recently drawn sprite&rdquo;)</td></tr>' +
    '<tr><td><b>Tile stash</b> (two bytes, one per plane)</td><td>Taken at a tile&rsquo;s high read, and only when two things hold: a set write has landed earlier on this line and has not yet been answered by a stash, and the select this layer&rsquo;s low read uses (tag 8 background, tag 10 window) reads clear on that dot. It then holds the two bytes of this tile&rsquo;s current row (Y flip applied) as they would be addressed on the <code>$8000</code> base, from the tile&rsquo;s own video bank. Taken at most once per set write. In practice that is the first tile fetched after the bit has been cleared again</td><td>shape: MECHANISM from one written account (&ldquo;the most recently drawn tile as when the select was last reset&rdquo;). The once-per-write hold, the <code>$8000</code> re-read and the per-plane halves: FITTED, and they land as one group</td></tr>' +
    '</tbody></table></div>' +
    '<div class="gbemu-why"><b>Why the exception exists.</b> Our fetcher lets an object fetch land between a tile&rsquo;s low and high reads. On hardware the object fetch waits for the background fetcher to finish its tile (the 0 to 5 dot wait inside the documented object penalty), so the tile&rsquo;s high read comes before the object&rsquo;s reads. Without the exception, the tile&rsquo;s high byte would overwrite the object&rsquo;s byte and the next line&rsquo;s substitute would be wrong: <code>m3_lcdc_tile_sel_change</code> goes from 0 to 116 px, every line from 129 down. The reason hardware hands back a stale byte at all, rather than a fresh read, is NOT ESTABLISHED: the source-read implementation states it and does not explain it.</div>' +
    '<div class="gbemu-rule" id="gbcr-10-21"><b>Rule C10/21.</b> <b>The background set substitute</b> is the first of these that applies:' +
    '<ol class="gbemu-steps">' +
    '<li>If this is the second or a later set write of this line (<a href="#gbcr-10-23">Rule C10/23</a>) and the tile stash has ever been filled: the tile stash, the half matching the plane being read.</li>' +
    '<li>Otherwise, if anything has ever been read on the <code>$8000</code> base: the last unsigned byte.</li>' +
    '<li>Otherwise: the high byte the fetcher last delivered at the moment the previous line&rsquo;s pixel counter reached 159.</li>' +
    '</ol></div>' +
    '<div class="gbemu-why"><b>Why.</b> The third fallback is effectively reachable only between a reset and the first unsigned read, which on any real picture is a few dots. It is carried from the written account and no cell exercises it.</div>' +
    '<div class="gbemu-rule" id="gbcr-10-22"><b>Rule C10/22.</b> <b>The window set substitute</b> is the first of these that applies:' +
    '<ol class="gbemu-steps">' +
    '<li>If this is the second or a later set write of this line (<a href="#gbcr-10-23">Rule C10/23</a>) and the tile stash has ever been filled: the tile stash, matching half.</li>' +
    '<li>Otherwise, if any object has ever been fetched: the last object byte. Not the last unsigned byte.</li>' +
    '<li>Otherwise, if the tile stash has ever been filled: the tile stash.</li>' +
    '<li>Otherwise: the byte actually read. No substitution.</li>' +
    '</ol></div>' +
    '<div class="gbemu-why"><b>Why.</b> Feeding the window the same stash as the background costs <code>m3_lcdc_tile_sel_win_change</code> 0 to 54 px and <code>m3_lcdc_tile_sel_win_change2</code> 0 to 23 px and gains nothing, because the window&rsquo;s own chain was tuned against the object stash. This scope is a measured boundary, FITTED, not a mechanism. The source-read implementation uses one stash for both layers.</div>' +
    '<div class="gbemu-rule" id="gbcr-10-23"><b>Rule C10/23.</b> <b>&ldquo;The second set write of this line&rdquo;.</b> Our core counts set writes per line, from 0 at the start of mode 3. A set write here is a Color LCDC write whose written value has bit 4 set while the register&rsquo;s stored value just before the write had it clear (judged on those two values, the write&rsquo;s own; a rewrite of a set bit 4, or a clear, does not count). The count goes up at the end of the write&rsquo;s conflict dot, the instant the final value is stored; the same instant marks &ldquo;a set write has landed&rdquo; for the tile stash (<a href="#gbcr-10-20">Rule C10/20</a>). The test is made on the read dot:' +
    '<table class="gbemu-table"><thead><tr><th>Rule that asks</th><th>Its read dot (event scale)</th><th>Has the current write been counted yet?</th><th>Test for &ldquo;an earlier set write already landed on this line&rdquo;</th></tr></thead><tbody>' +
    '<tr><td>window set (step 1 of <a href="#gbcr-10-22">Rule C10/22</a>)</td><td>the last lead dot or the conflict dot</td><td>no</td><td>count above 0 (<code>TSEL_SET_ORDER_N_WIN = 0</code>)</td></tr>' +
    '<tr><td>background set (step 1 of <a href="#gbcr-10-21">Rule C10/21</a>)</td><td>the commit dot <code>C</code></td><td>yes</td><td>count above 1 (<code>TSEL_SET_ORDER_N = 1</code>)</td></tr>' +
    '</tbody></table>' +
    'Both tests mean the same thing: an earlier set write already landed on this line. Do not share one constant between them.</div>' +
    '<div class="gbemu-example"><b>Example.</b> The first set write of a line: on its last lead dot the count is 0, so a window read there does not take the tile stash; on its commit dot the count is 1, so a background read there does not take it either. On the second set write of the line, the count is 1 on its lead dots (above 0: the window takes the stash) and 2 on its commit dot (above 1: the background takes it).</div>' +
    '<div class="gbemu-why"><b>Why.</b> &ldquo;The second set write of this line&rdquo; is one ordinal written as two thresholds, and sharing them is the trap. Read from our source (the LCDC write path). In the source the window&rsquo;s own constant was split out after a registered prediction failed, so the split is POST HOC. Use one constant for both and move it to 0, and <code>m3_lcdc_tile_sel_change</code>, a background cell, goes from 8 px to 744. The ordinal itself is FITTED: it is a property of each cell&rsquo;s fetch phase, and a core with different window geometry must re-derive it.</div>' +
    '<h4 class="gbemu-sub">Order inside one data read</h4>' +
    '<div class="gbemu-rule" id="gbcr-10-24"><b>Rule C10/24.</b> A tile-data read runs these steps in this order:' +
    '<table class="gbemu-table"><thead><tr><th>Step (in order)</th><th>Low read</th><th>High read</th></tr></thead><tbody>' +
    '<tr><td>1</td><td>If the background set rule fires: deliver its substitute, read nothing, write no stash, done</td><td>If the background set rule fires: deliver its substitute and do not read memory (continue at step 3)</td></tr>' +
    '<tr><td>2</td><td>Read memory at the formed address</td><td>Read memory at the formed address</td></tr>' +
    '<tr><td>3</td><td>If the address was on <code>$8000</code>: write the byte READ to the last unsigned stash</td><td>Write the delivered byte to the last unsigned stash if the most recent address formed was on <code>$8000</code> and no object fetch ended since this tile&rsquo;s low read. Normally that address is this high read&rsquo;s own. After step 1 no address was formed, so it is the low read&rsquo;s, and the byte written is the substitute (see the note below)</td></tr>' +
    '<tr><td>4</td><td>(nothing)</td><td>If the tile stash conditions hold: refill the tile stash</td></tr>' +
    '<tr><td>5</td><td>If a window set rule fires: replace the delivered byte with its substitute; otherwise, if a window or background clear rule fires: replace it with the tile number (top bit clear) or keep it</td><td>The same</td></tr>' +
    '</tbody></table></div>' +
    '<div class="gbemu-why"><b>Why.</b> Stated because the stash writes and the substitutions interleave, and building them in another order changes what the next substitution sees. Two consequences of that order. The last unsigned stash keeps the byte memory actually returned, even when step 5 then delivers something else. And on a high read hit by the background set rule, step 3 writes the substitute itself into the stash, judged by the low read&rsquo;s base, although the stash is described everywhere else as holding only bytes read from memory. Usually the substitute is that same stash, so nothing changes; from the second set write of a line it is the tile stash, and then the tile stash&rsquo;s byte is copied into the last unsigned stash. That is what the shipped core does, and no cell is known to depend on it either way.</div>' +
    '<h4 class="gbemu-sub">Every constant, with its value</h4>' +
    '<p class="hw-readable">Reference for a reader of our source: each constant behind Rules <a href="#gbcr-10-8">C10/8</a> to <a href="#gbcr-10-24">C10/24</a>, with the value that ships.</p>' +
    '<table class="gbemu-table"><thead><tr><th>Constant</th><th>Value</th><th>What it is, in words</th><th>Label</th></tr></thead><tbody>' +
    '<tr><td><code>LCDC_LEAD</code>, <code>LCDC_PEND</code></td><td>2, 5</td><td>the write train&rsquo;s lead dots and owed budget, the original&rsquo;s (Game Boy tab, E.1.3 and E.9), run on the Color through unresolved fence rows</td><td>the original&rsquo;s labels; on the Color, a declared placeholder</td></tr>' +
    '<tr><td><code>LCDC_M3ONLY_CGB</code></td><td>1</td><td>the train runs only for writes in mode 3</td><td>adopted guard value, not derived for the Color</td></tr>' +
    '<tr><td><code>LCDC_W_BGDATA_CGB</code></td><td>0</td><td>0 means the background takes the original&rsquo;s tag, 8</td><td>MECHANISM (nominal)</td></tr>' +
    '<tr><td><code>LCDC_W_WINDATA_CGB</code></td><td>10</td><td>window low read: new bit 4 from <code>C - 2</code></td><td>FITTED</td></tr>' +
    '<tr><td><code>LCDC_W_WINDATA_CGB_HI</code></td><td>12</td><td>window high read: new bit 4 from <code>C - 2</code> for a clearing write only</td><td>FITTED</td></tr>' +
    '<tr><td><code>TSEL_SET_GLITCH</code></td><td>1</td><td>the background set rule and the three stashes exist</td><td>switch</td></tr>' +
    '<tr><td><code>TSEL_SET_SCOPE</code></td><td>4</td><td>the commit-dot set rule applies to background fetches only</td><td>FITTED</td></tr>' +
    '<tr><td><code>TSEL_SET_LASTU</code></td><td>1</td><td>the background set rule takes the last unsigned byte, not the last object byte</td><td>SOURCE-READ / CONVERGENCE</td></tr>' +
    '<tr><td><code>TSEL_SET_CHAIN</code></td><td>1</td><td>after the ordinal test, the background rule tries only the last unsigned byte before the fallback</td><td>FITTED</td></tr>' +
    '<tr><td><code>TSEL_SET_ORDER</code>, <code>TSEL_SET_ORDER_N</code></td><td>1, 1</td><td>the background ordinal: tile stash from the second set write of the line</td><td>FITTED</td></tr>' +
    '<tr><td><code>WIN_TSEL_ORDER_WIN</code>, <code>TSEL_SET_ORDER_N_WIN</code></td><td>1, 0</td><td>the window has its own threshold, 0, meaning the same ordinal</td><td>FITTED, scope POST HOC</td></tr>' +
    '<tr><td><code>TSEL_SET_SRC</code>, <code>TSEL_SET_PX</code></td><td>2, 159</td><td>the fallback is the HIGH byte held when the pixel counter reaches 159</td><td>from the written account; unexercised</td></tr>' +
    '<tr><td><code>WIN_TSEL_SET_REG</code>, <code>WIN_TSEL_RST_REG</code></td><td>11, 11</td><td>the window rules fire on the last lead dot or the conflict dot</td><td>FITTED</td></tr>' +
    '<tr><td><code>WIN_TSEL_SET_SRC</code></td><td>2</td><td>the window set source order of <a href="#gbcr-10-22">Rule C10/22</a></td><td>FITTED</td></tr>' +
    '<tr><td><code>BG_TSEL_RST_REG</code></td><td>5</td><td>the background clear rule fires on the commit dot</td><td>FITTED</td></tr>' +
    '<tr><td><code>BG_TSEL_RST_RECENCY</code></td><td>5</td><td>no background clear within 5 dots of an object fetch&rsquo;s end</td><td>FITTED</td></tr>' +
    '<tr><td><code>TSEL_TILE_HOLD</code>, <code>TSEL_TILE_BASE</code>, <code>TSEL_TILE_PLANE</code></td><td>1, 1, 1</td><td>the tile stash: once per set write, re-read on <code>$8000</code>, one byte per plane</td><td>FITTED, one group</td></tr>' +
    '<tr><td><code>HI_CONF_NEXT</code>, <code>HI_CONF_AGE</code></td><td>1, 8</td><td>the conflict-dot override, window only, object at least 8 dots ago</td><td>FITTED, carried flagged</td></tr>' +
    '<tr><td><code>HI_STALL_LATCH</code>, <code>HI_STALL_GAP</code></td><td>1, 2</td><td>the stalled-high latch, window only; late means more than 2 dots</td><td>scope FITTED; gap DERIVED</td></tr>' +
    '<tr><td><code>HI_STALL_DIR</code>, <code>HI_STALL_FIRSTFIRE</code>, <code>HI_STALL_ROW0</code></td><td>1, 1, 0</td><td>signed-to-unsigned only; not on the first line of a run; no tile-row restriction</td><td>FITTED</td></tr>' +
    '<tr><td><code>BG_TSEL_SET_REG</code></td><td>0</td><td>off: the background set rule has no lead-dot or conflict-dot form</td><td>switch, off</td></tr>' +
    '<tr><td>the four <code>_PL</code> constants, <code>BG_TSEL_RST_FX</code></td><td>0</td><td>no plane or column restriction on any rule</td><td>switches, off</td></tr>' +
    '<tr><td><code>TILE_SEL_GLITCH</code>, <code>TSEL_T1_CGB</code>, <code>TILE_SEL_LATCH_CGB</code></td><td>0, 0, 0</td><td>off: the reference implementation&rsquo;s one-dot clear glitch with its saved byte; a per-step latch of bit 4; a latched select. None ships</td><td>switches, off</td></tr>' +
    '</tbody></table>' +
    '<h4 class="gbemu-sub">Check yourself against these</h4>' +
    '<p class="hw-readable">All of these are INSTRUMENT-MEASURED on our core, against the stored revision-C render, in compatibility mode. Only the first three were taken on the core this site ships. The other four were taken on earlier cores of ours, on which <code>m3_lcdc_tile_sel_change</code> read 8 px, and have not been re-taken on the shipped core; the third column says which.</p>' +
    '<table class="gbemu-table"><thead><tr><th>Change from what ships</th><th>What moves</th><th>Measured on</th></tr></thead><tbody>' +
    '<tr><td>Background set rule takes the last object byte instead of the last unsigned byte</td><td><code>m3_lcdc_tile_sel_change</code> 0 to 8 px, all on line 128, x 16 to 23 (ours colour 2, reference colour 3); board 27 of 27 to 26 of 27. Line 127&rsquo;s unsigned background low read leaves <code>$FF</code>, and line 128&rsquo;s set write takes it</td><td>the shipped core</td></tr>' +
    '<tr><td>Remove the interrupted-tile exception</td><td>that cell 0 to 116 px, line 129 onward</td><td>the shipped core</td></tr>' +
    '<tr><td>Feed the window set rule the last unsigned byte too</td><td><code>m3_lcdc_tile_sel_win_change</code> 0 to 54 px, <code>m3_lcdc_tile_sel_win_change2</code> 0 to 23 px</td><td>the shipped core</td></tr>' +
    '<tr><td>Recency suppression off</td><td><code>m3_lcdc_tile_sel_change</code> 124 px instead of 8; colour board 770 instead of 654</td><td>an earlier core, without the window rules of this section; not re-taken</td></tr>' +
    '<tr><td>One shared ordinal constant, moved to 0</td><td><code>m3_lcdc_tile_sel_change</code> 8 to 744 px</td><td>an earlier core; not re-taken</td></tr>' +
    '<tr><td>Stalled-high latch on every fetch, not window only</td><td><code>m3_lcdc_tile_sel_change</code> 8 to 180 px</td><td>an earlier core; not re-taken</td></tr>' +
    '<tr><td>The ordinal rule without the tile stash&rsquo;s hold and re-read</td><td>a 108 px regression; only all three together improve</td><td>an earlier core, in a development tree; not re-taken</td></tr>' +
    '</tbody></table>' +
    '<p class="hw-readable">And one hardware witness, of existence only. Photographs of <code>m3_lcdc_tile_sel_change</code> on a revision-C and a revision-D Color both show a single dark row where line 128 falls. They cannot resolve colour 3 against a dark colour 2 at the pixel, so they corroborate the shape and do not fix the value.</p>' +
    '<h4 class="gbemu-sub">What is not known</h4>' +
    '<ul class="gbemu-bullets">' +
    '<li>Why the hardware hands back a stale byte, or the tile number, instead of reading memory. NOT ESTABLISHED. Every shape here is taken from one written account or one source-read implementation; nothing on this disk observes the mechanism.</li>' +
    '<li>Whether any of it holds in colour mode. Every cell that exercises it runs in compatibility mode.</li>' +
    '<li>Whether the Color even has the lead dots and the conflict dot these rules hang on. On the hardware, single speed has no intermediate (<a href="#gbcr-10-3">Rule C10/3</a>). Our core runs the original&rsquo;s train there anyway, so every dot in this subsection is a dot of a write phase the hardware may not have. What would settle it: a colour-flagged cartridge writing bit 4 at a known dot inside mode 3, one direction at a time.</li>' +
    '<li>Double speed. The lead disappears in our core and no cell exercises it.</li>' +
    '<li>The values 5 (recency), 8 (object age, indistinguishable from 7 here), and the ordinal thresholds. Each was read off this corpus&rsquo;s object spacing or fetch phase. Re-derive them on a different corpus; do not carry them.</li>' +
    '<li>Revision D. The figures above are against revision C only. Section 15 records that the tile-select glitch is a singleton at revision D, and nothing here has been measured against that column.</li>' +
    '<li>The two <code>cgb-acid-hell</code> survivors (section 17 and the Game Boy tab) are one bit of a background high byte that equals the tile number, on a read just after bit 4 was cleared. That is the shape of the background clear rule. Whether that rule fails to fire there, and why, has not been traced. Do not assume this subsection explains them.</li>' +
    '</ul>' +
    '<h4 class="gbemu-sub">The Color&rsquo;s write leads, consumer dots and interrupt dots, as our core runs them</h4>' +
    '<p class="hw-readable">The Game Boy tab&rsquo;s appendix E says which dot, for the original. This subsection is the same thing for the Color, and it describes <b>our core</b>, not the hardware. Where the hardware differs from what our core does, or nobody knows, the label says so. An implementer copying this reproduces our renders; a reader quoting it as silicon behaviour is quoting us.</p>' +
    '<p class="hw-readable">Four conventions, all borrowed so that nothing here needs a new scale. Dots are counted on the Game Boy tab&rsquo;s scale (the head of appendix E: the line boundary is four dots before the scan, mode 3 is entered on dot 84). A register&rsquo;s <b>lead</b> is E.1&rsquo;s: lead L means the register takes the value L dots before the end of the write&rsquo;s machine cycle, and a negative lead means after it. <b>B</b> is the machine cycle&rsquo;s dot budget, 4 at single speed and 2 in double speed (E.5; the dots-per-cycle row, G13, is discharged). <b>C</b> is the display-control commit dot of E.9, and the lead dots C&nbsp;-&nbsp;3 and C&nbsp;-&nbsp;2 and the conflict dot C&nbsp;-&nbsp;1 are E.9&rsquo;s too.</p>' +
    '<p class="hw-readable">And three words for how a value reaches the Color, because they are not the same kind of answer:</p>' +
    '<ul class="gbemu-bullets">' +
    '<li><b>Discharged.</b> The site has its own Color arm (two arms for original and Color, or three for original, Color single speed and Color double speed) and records no breach.</li>' +
    '<li><b>Unresolved.</b> The site is a fence row that has no Color arm yet. At run time it <em>returns the original&rsquo;s value</em> on a Color and records a breach. So on a Color our core runs the original&rsquo;s behaviour there. That is a declared placeholder, not a claim about the hardware.</li>' +
    '<li><b>Carried.</b> Code with no device test of any kind. The original&rsquo;s behaviour runs on both machines and no fence row records it. These are the easiest to miss, because nothing in the fence report names them.</li>' +
    '</ul>' +
    '<p class="gbemu-key">Read this first: nothing in our window machine, our interrupt sources or our line counter tests the colour-mode flag. Where this subsection says &ldquo;the Color&rdquo;, it means both compatibility mode and colour mode. And every scored colour cell runs in compatibility mode at single speed, so no double-speed write lead below has ever been scored by anyone (the one double-speed access row, the video-memory close, is scored by the AGE tests).</p>' +
    '<p class="hw-readable">What these settings score, so the table is not read as untested: the colour board (27 compatibility-mode cells against the stored revision-C renders) reads 0&nbsp;px, 27 of 27, with the fence reporting unresolved rows reached on every cell. A green cell is not a closed cell; section 17 says why.</p>' +
    '<h4 class="gbemu-sub">The Color column for appendix E.1</h4>' +
    '<p class="hw-readable"><b>The G numbers</b> in this section (G1, G2, G17, G32 and the rest) are our source&rsquo;s names for its list of places where the Color might differ from the original (&ldquo;fence rows&rdquo;): each is a pointer into our source, like a constant&rsquo;s name. Nothing a build needs depends on the list: every cell that cites one also states the value our core uses and whether the Color&rsquo;s own value is established, unresolved (the original&rsquo;s value returned) or discharged (a Color value adopted).</p>' +
    '<div class="gbemu-rule" id="gbcr-10-25"><b>Rule C10/25.</b> <b>No extra machine cycle on the Color.</b> The original lands its seven drawing registers (LCDC, SCY, SCX, BGP, OBP0, OBP1, WX) one whole machine cycle, four dots, after their lead puts them when the screen is on (the Game Boy tab, E.1, &ldquo;One machine cycle more for the drawing registers&rdquo;). The Color has no counterpart, at either speed and in either mode: every Color lead in <a href="#gbcr-10-26">Rule C10/26</a>&rsquo;s table, and every absolute dot in <a href="#gbcr-10-28">Rule C10/28</a>&rsquo;s table, is applied exactly as printed, with nothing added.</div>' +
    '<div class="gbemu-why"><b>Why.</b> That rule is the original&rsquo;s alone, the counterpart of its running processor&rsquo;s two-dot look, which the Color does not make either. INSTRUMENT-MEASURED: the Color column of the Game Boy tab&rsquo;s E.1.1, measured on the shipped core, is unchanged by that rule. Read from our source (the lag is applied only when the device is the original, <code>DMG_WRITE_LAG</code>).</div>' +
    '<div class="gbemu-rule" id="gbcr-10-26"><b>Rule C10/26.</b> On the Color our core applies to each register write and each consumer the lead, hold or tag in the two Color columns of this table. One row per register and one row per consumer, in E.1&rsquo;s order and then E.1.3&rsquo;s. The consumers read on the same fetcher dots as on the original (section 1: the fetcher period is unchanged and the attribute read is free), so where a row says nothing about the read dot, it is E.1&rsquo;s. A lead is in E.1&rsquo;s convention (dots before the end of the write&rsquo;s machine cycle; negative means after it); a tag is E.9&rsquo;s settling name; a dot named relative to <code>C</code> is on the event scale. <a href="#gbcr-10-28">Rule C10/28</a> turns the leads into absolute dots.</div>' +
    '<table class="gbemu-table">' +
    '<thead>' +
    '<tr><th>Register, consumer</th><th>The original (as E.1 and E.1.3 state it; leads in dots before the cycle&rsquo;s end)</th><th>Color, single speed (same units)</th><th>Color, double speed (same units)</th><th>How the Color value is reached</th><th>Label on the Color value</th></tr>' +
    '</thead>' +
    '<tbody>' +
    '<tr><td><b>SCY</b> <code>$FF42</code>, the write</td><td>lead +1</td><td>lead 0</td><td>lead 0 (the same constant; the row has two arms, not three)</td><td>discharged (G7, <code>SCY_EARLY_CGB</code>)</td><td>the SUM of this lead and the power-on line length is MECHANISM (one published document gives Color SCY writes as landing two dots later than the original&rsquo;s; one dot is here, the other is the one-dot-shorter power-on line, <a href="#gbcr-10-46">Rule C10/46</a>). The SPLIT between the two is FITTED-TO-STORED-RENDER. Double speed: NOT ESTABLISHED, never scored</td></tr>' +
    '<tr><td>SCY, its consumer (the row within the tile)</td><td>recomputed at each of the two data reads, not cached at the map read</td><td>the same: live at each data read</td><td>the same</td><td>discharged (G16, <code>ROW_LATCH_CGB</code> = 0)</td><td>UNDECIDED-ADOPTED-GUARD-VALUE. Our source records that one reference implementation re-derives the row live at revision C and below and caches it at the map read from revision D on; 0 is the revision-C behaviour</td></tr>' +
    '<tr><td><b>SCX</b> <code>$FF43</code>, the write</td><td>lead +1</td><td>lead +1</td><td>lead +1, one dot before the end of the two-dot cycle</td><td>discharged, three arms (G8, <code>SCX_WRITE_LEAD_CGB</code>, <code>SCX_WRITE_LEAD_CGB2</code>)</td><td>single speed: UNDECIDED-ADOPTED-GUARD-VALUE. Double speed: UNDECIDED and unreachable on our corpus (swept to -1, byte-identical, because compatibility mode is single speed)</td></tr>' +
    '<tr><td>SCX, background map read (step 0, the tile column)</td><td>reads the register live</td><td>reads the PRE-write SCX on the first dot after the write lands and the new value from the second. With the +1 lead that delivers the new value to this one consumer exactly where a lead-0 write would</td><td>the same, against the two-dot cycle</td><td>a plain device test, no fence row (<code>SCX_MAP_HOLD_CGB</code> = 2: a counter armed to two at the write and decremented at the head of each dot, so by E.5&rsquo;s counter rule it holds for one dot)</td><td>FITTED-TO-STORED-RENDER. Source comment: closes <code>m3_scx_high_5_bits</code> from 30 to 0&nbsp;px and <code>m3_scx_high_5_bits_change2</code> from 34 to 0 with <code>m3_scx_low_3_bits</code> and <code>m3_window_timing_wx_0</code> held at 0, which no single write lead can do</td></tr>' +
    '<tr><td>SCX, the fine-scroll discard</td><td>latched from the live SCX on line dot 89</td><td>the same dot, the same live read, no hold</td><td>the same</td><td>carried</td><td>as the SCX lead</td></tr>' +
    '<tr><td><b>WX</b> <code>$FF4B</code>, the write</td><td>lead +2</td><td>lead +2</td><td>lead +2, which at a two-dot budget is a whole machine cycle early</td><td>unresolved (G9): the original&rsquo;s value returned</td><td>NOT ESTABLISHED. Our source&rsquo;s own note on this row says the Color has no displaced WX write at all and must not inherit the lead; at run time it does inherit it</td></tr>' +
    '<tr><td>WX, the window comparator</td><td>reads a held WX: the pre-write value for two dots after a write (E.8), and only when that pre-write value is 7 or more</td><td>the same</td><td>the same, counted in dots</td><td>carried (<code>WX_W_WINCMP</code> = 9, <code>WX_HOLD_DOTS</code> = 2, <code>WX_HOLD_W7</code> = 1)</td><td>NOT ESTABLISHED on the Color; the original&rsquo;s label is FITTED</td></tr>' +
    '<tr><td><b>WY</b> <code>$FF4A</code></td><td>lead 0; arming tested every dot, together with window-enable</td><td>the same</td><td>the same</td><td>carried</td><td>NOT ESTABLISHED on the Color; FITTED on the original</td></tr>' +
    '<tr><td><b>BGP</b> <code>$FF47</code></td><td>+2, two-stage: <code>old OR new</code> two dots before the cycle ends, the value one dot later</td><td>single stage, no OR. Constant 3, and at this site that puts the new value in the register two dots before the cycle ends: the dot on which the original&rsquo;s OR stage lands. Nothing is visible before it</td><td>not observable: double speed exists only in colour mode, where this register is not consulted (section 7)</td><td>discharged (G6, <code>BGP_LEAD_CGB</code> = 3, <code>BGP_OR_CGB</code> = 0)</td><td>the lead: MECHANISM (the source&rsquo;s equation D = OR + lead + pipeline, kept at 3, predicted before it was measured). No OR: read off the stored references, 128 one-pixel spikes in the original&rsquo;s column and 0 in revision C&rsquo;s, which the Game Boy tab (E.1.2) classes as SOURCE-READ / CONVERGENCE, not as silicon</td></tr>' +
    '<tr><td><b>OBP0, OBP1</b> <code>$FF48/9</code></td><td><b>lead 2</b> in E.1&rsquo;s convention, single stage (our source&rsquo;s constant for it is 3; see the note in the next cell)</td><td><b>lead 2</b>, single stage, the same as the original (source constant 3). Build from the lead, or better from the absolute dots (E.1.1: N + 2 at single speed, N + 1 in double), never from the source constant. Exactly as for BGP above, at this site the constant puts the new value in the register two dots before the write&rsquo;s cycle ends: first seen on the third dot of the cycle, which is lead 2, not 3. Read as a lead of 3, it puts both palette changes one pixel early.</td><td>not observable, for the same reason; in our core the new value is first seen on the second and last dot of the two-dot cycle</td><td>discharged (G6, <code>OBP_LEAD_CGB</code> = 3, <code>OBP_OR_CGB</code> = 0)</td><td>FITTED-TO-STORED-RENDER: swept on the colour board, no better value found. The dots: INSTRUMENT-MEASURED</td></tr>' +
    '<tr><td>The Color&rsquo;s own registers (palette data <code>$FF69</code>, <code>$FF6B</code> and their index registers, the bank registers, the block-transfer registers, the priority register)</td><td>do not exist</td><td>lead 0, a plain end-of-cycle write</td><td>lead 0</td><td>no lead site at all (the default)</td><td>SOURCE-READ / CONVERGENCE, as <a href="#gbcr-10-2">Rule C10/2</a>&rsquo;s table states</td></tr>' +
    '<tr><td><b>LCDC</b> <code>$FF40</code>, the write</td><td>lead +2, two-stage, owed budget 5, only for writes landing in mode 3 with the display on (E.1.3)</td><td>the original&rsquo;s train exactly: two lead dots, the conflict dot holding <code>old OR (new &amp; bit 0)</code>, then the commit (<a href="#gbcr-10-3">Rule C10/3</a>). On the hardware the write is atomic here; our core does not do that</td><td>the same train with no lead dots: the two-dot budget leaves nothing to withhold, so only the conflict dot and the commit exist; 3 dots are owed (<a href="#gbcr-10-4">Rule C10/4</a>)</td><td>unresolved (G2 for the two-stage shape, G3 for the budget, G5 for the object-enable exception); the mode-3-only restriction is discharged to the original&rsquo;s value (G4, <code>LCDC_M3ONLY_CGB</code> = 1)</td><td>the train: NOT ESTABLISHED (original&rsquo;s values returned). The mode-3 restriction: UNDECIDED-ADOPTED-GUARD-VALUE</td></tr>' +
    '<tr><td>LCDC bits 5 and 6, early in the register</td><td>not stated in E.1.3 or E.9 (<a href="#gbcr-10-27">Rule C10/27</a>)</td><td>both bits are already in the register on the last lead dot, C&nbsp;-&nbsp;2</td><td>no lead dot exists, so not early</td><td>carried (<code>WLEAD_BITS</code> = bits 5 and 6, <code>WLEAD_DOTS</code> = 1)</td><td>NOT ESTABLISHED on the Color; on the original it was shipped on the evidence of one cartridge</td></tr>' +
    '<tr><td>LCDC bit 0, at the merge</td><td>tag 7</td><td>tag 7. What the bit means on a Color is section 7</td><td>tag 7</td><td>unresolved for the width (G1 returns the original&rsquo;s tag); the merge expression itself is discharged (G17)</td><td>NOT ESTABLISHED</td></tr>' +
    '<tr><td>LCDC bit 1, object selection</td><td>tag 61</td><td>no write timing at all: the object is selected and fetched whether bit 1 is set or not, so it still costs drawing dots</td><td>the same</td><td>discharged (G32)</td><td>SOURCE-READ / CONVERGENCE: predicted by one source-read implementation and confirmed as a pure displacement of the original&rsquo;s render on the stored references (5&nbsp;px on revision C, 6 on D, zero residual)</td></tr>' +
    '<tr><td>LCDC bit 1, the outstanding-work test</td><td>tag 8</td><td>tag 8</td><td>tag 8</td><td>unresolved (G1)</td><td>NOT ESTABLISHED</td></tr>' +
    '<tr><td>LCDC bit 1, at the merge</td><td>tag 7 plus a permanent one-dot shadow (E.1.3). Our core also reads the bit live, without the shadow, at column 0; E.1.3 does not say so</td><td>tag 7 plus the same one-dot shadow at every column, column 0 included: the column-0 live read is the original&rsquo;s arm only. The dot is counted at the screen write, the dot after the pixel&rsquo;s pop, where our core takes the merge decision (MECHANISM, read from our source, <code>ppu_out_emit</code>)</td><td>the same</td><td>discharged (G17) for the column-0 exception; the width unresolved (G1)</td><td>NOT ESTABLISHED</td></tr>' +
    '<tr><td>LCDC bit 2, the object fetch&rsquo;s low plane</td><td>tag 9; one address for both planes, formed on the fetch&rsquo;s last dot</td><td>tag 8, and the low plane is read on its own dot, forming its own address there: the stall&rsquo;s fourth dot, counting the notice dot as the first, while the high plane is read on the stall&rsquo;s last dot. That is two dots apart in a six-dot stall and further apart in a clipped object&rsquo;s longer one (OAM X&nbsp;0 at SCX&nbsp;0: noticed on 90, low plane on 93, high plane on 100). The step of the stall each read is made on is read from our source, and the dot of each step measured on our core.</td><td>the same, in dots</td><td>discharged (G35: <code>OBJ_DESYNC_CGB</code> = 1, <code>LCDC_W_OBJ_FETCH_CGB</code> = 8)</td><td>the sign of the effect: MECHANISM (derived from the cartridge&rsquo;s artwork before the arm was built). The device split: read off the stored references, which our source calls a direct reference observation and the Game Boy tab&rsquo;s convention would call SOURCE-READ / CONVERGENCE</td></tr>' +
    '<tr><td>LCDC bit 2, the object fetch&rsquo;s high plane</td><td>tag 10 if the fetch waited for the fetcher, otherwise 8</td><td>tag 8, on the fetch&rsquo;s last dot: no second formation point of the original&rsquo;s kind</td><td>the same</td><td>discharged (G35, <code>OBJ_HI_W_CGB</code> = 0)</td><td>FITTED-TO-STORED-RENDER. Source comment: forcing the original&rsquo;s rule on the colour board costs <code>m3_lcdc_obj_size_change</code> 0 to 15&nbsp;px and a pass</td></tr>' +
    '<tr><td>LCDC bit 2, the sprite-memory scan</td><td>tag 9, inert on our corpus</td><td>tag 9</td><td>tag 9</td><td>unresolved (G1)</td><td>NOT ESTABLISHED</td></tr>' +
    '<tr><td>LCDC bit 3, the background map read</td><td>tag 8: new from C</td><td>tag 9: the pre-write value on C itself, new from C&nbsp;+&nbsp;1</td><td>the same: new from C&nbsp;+&nbsp;1</td><td>a Color width supplied at this one call site; the row it sits under (G1) stays unresolved for every other consumer</td><td>SOURCE-READ / CONVERGENCE for the direction (one source-read implementation agrees); the member was named by a width isolation against the stored revision-C render. Source comment: <code>m3_lcdc_bg_map_change</code> 192 to 0&nbsp;px and <code>_change2</code> 109 to 0, every other cell byte-identical</td></tr>' +
    '<tr><td>LCDC bit 4, the background data reads</td><td>tag 8</td><td>tag 8, plus the Color&rsquo;s tile-data select glitches (Rules <a href="#gbcr-10-8">C10/8</a> to <a href="#gbcr-10-24">C10/24</a>)</td><td>tag 8; no cell exercises the glitches here</td><td>discharged (<code>LCDC_W_BGDATA_CGB</code> = 0, which means &ldquo;take the original&rsquo;s tag&rdquo;)</td><td>MECHANISM (nominal), as <a href="#gbcr-10-11">Rule C10/11</a> states</td></tr>' +
    '<tr><td>LCDC bit 4, the window data reads</td><td>tag 7</td><td>low read tag 10; high read tag 12 (<a href="#gbcr-10-11">Rule C10/11</a>)</td><td>the same tags</td><td>discharged (<code>LCDC_W_WINDATA_CGB</code> = 10, <code>LCDC_W_WINDATA_CGB_HI</code> = 12)</td><td>FITTED-TO-STORED-RENDER</td></tr>' +
    '<tr><td>LCDC bit 5, the window comparator and the window stop test</td><td>tag 8 plus a clear-only early release</td><td>the same; and the bit is in the register from C&nbsp;-&nbsp;2 (bits 5 and 6 row above)</td><td>tag 8 plus the release; no lead dot</td><td>unresolved (G1)</td><td>NOT ESTABLISHED</td></tr>' +
    '<tr><td>LCDC bit 6, the window map read</td><td>tag 8</td><td>the pre-write value for the first two dots of the write train (C&nbsp;-&nbsp;3 and C&nbsp;-&nbsp;2), new from the conflict dot C&nbsp;-&nbsp;1 on (the early bit-6 write puts it in the intermediate)</td><td>the pre-write value on the conflict dot and on C, new from C&nbsp;+&nbsp;1</td><td>a Color width supplied at the call site (<code>LCDC_W_WINMAP_CGB</code> = 92: a hold of two dots counted from the start of the write train)</td><td>FITTED-TO-STORED-RENDER. Source comment: <code>m3_lcdc_win_map_change</code> 60 to 0&nbsp;px and <code>_change2</code> 70 to 0, no cell on either board worse</td></tr>' +
    '<tr><td>LCDC written outside mode 3, or with the display off</td><td>a plain write, lead 0</td><td>a plain write, lead 0. No hold is armed, so the bit-3 and bit-6 rules above do not apply. Every consumer sees the new value from N + 4 (N + 2 in double speed), with no lead dot and no conflict dot; object-enable at the merge still keeps its permanent one-dot shadow. Mode 3 here is the internal drawing mode at the start of the write&rsquo;s cycle (the Game Boy tab, E.9.1). MECHANISM, read from our source (<code>ppu_pay</code>, <code>LCDC_M3ONLY_CGB</code>)</td><td>the same</td><td>as the LCDC write row</td><td>as the LCDC write row</td></tr>' +
    '<tr><td><b>STAT</b> <code>$FF41</code></td><td>lead 0, plus the one-dot <code>$78</code> transient</td><td>lead 0, plus a one-dot intermediate: bit 6 still old, bits 5 to 3 new</td><td>lead 0, plus a one-dot intermediate: bit 3 still old, bits 6 to 4 new</td><td>discharged, three arms (G11)</td><td>SOURCE-READ / CONVERGENCE (<a href="#gbcr-10-6">Rule C10/6</a> has the whole row)</td></tr>' +
    '<tr><td><b>LYC</b> <code>$FF45</code></td><td>lead -1</td><td>lead -1</td><td>lead -1: one dot after the two-dot cycle ends</td><td>unresolved (G10): the original&rsquo;s value returned</td><td>NOT ESTABLISHED. On the hardware the Color&rsquo;s LYC phase is speed-dependent (<a href="#gbcr-10-7">Rule C10/7</a>); our core uses one value at both speeds</td></tr>' +
    '<tr><td><b>IF</b> <code>$FF0F</code></td><td>lead -1</td><td>lead -1</td><td>lead -1</td><td>unresolved (G10)</td><td>NOT ESTABLISHED</td></tr>' +
    '<tr><td>The output stage (a colour index between the queue and the screen)</td><td>no pipeline beyond the structural one dot (E.1.2, E.5.1)</td><td>the same</td><td>the same</td><td>unresolved (G22); see NOTES on how this site is wired</td><td>NOT ESTABLISHED. Our source states the original&rsquo;s argument for zero rested on the OR stage, which the Color does not have, so the question reopens on the Color and has not been re-measured</td></tr>' +
    '<tr><td>Video-memory reads closing ahead of mode 3</td><td>6 dots early (E.1.5)</td><td>0: closed when drawing starts</td><td>closed exactly while STAT reports mode 3</td><td>discharged (<code>CGB_VRAM_CLOSE</code>, <code>CGB_ACC_DS</code>; section 5; <a href="#gbcr-10-44">Rule C10/44</a>)</td><td>Single speed: FITTED (the AGE table allows that dot or two dots later). Double speed: MECHANISM (it follows STAT)</td></tr>' +
    '</tbody>' +
    '</table>' +
    '<p class="hw-readable">Two things the table cannot carry in a cell: the display-control write in double speed is balanced in our core (<a href="#gbcr-10-4">Rule C10/4</a>), and bits 5 and 6 of LCDC are early (<a href="#gbcr-10-27">Rule C10/27</a>).</p>' +
    '<div class="gbemu-rule" id="gbcr-10-27"><b>Rule C10/27.</b> <b>Bits 5 and 6 of LCDC are early on both machines.</b> At single speed, for an LCDC write that takes the train, our core writes the window-enable and window-map bits (5 and 6) into the register one dot ahead of the rest, on the last lead dot, C&nbsp;-&nbsp;2, on the original and the Color alike. So E.9&rsquo;s &ldquo;tag 8 sees the new value from C&rdquo; is true of every bit except these two in our core. On the Color, the window map&rsquo;s two-dot hold (the bit-6 row of <a href="#gbcr-10-26">Rule C10/26</a>) takes the bit-6 half of that back for one dot.</div>' +
    '<div class="gbemu-why"><b>Why.</b> E.1.3 and E.9 do not mention this. Carried (<code>WLEAD_BITS</code>, <code>WLEAD_DOTS</code>); NOT ESTABLISHED on the Color.</div>' +
    '<div class="gbemu-rule" id="gbcr-10-28"><b>Rule C10/28.</b> <b>The Color column in absolute dots.</b> What our core does, as dots, with no lead convention to decode. N is the first dot of the write&rsquo;s machine cycle: at single speed N is 4k + 2 (<a href="#gbcr-10-47">Rule C10/47</a>); in double speed N is even and the cycle covers N and N + 1. Each cell is the first dot on which that consumer reads the new value, on the event scale (the consumer reads it while the picture processor processes that dot).' +
    '<table class="gbemu-table"><thead><tr><th>Register, consumer</th><th>Color, single speed (event scale, counted from N = 4k + 2)</th><th>Color, double speed (event scale, counted from N, N even)</th></tr></thead><tbody>' +
    '<tr><td><b>SCY</b>, every fetcher read of it</td><td>N + 4</td><td>N + 2</td></tr>' +
    '<tr><td><b>SCX</b>, the register (and the fine-scroll discard on dot 89)</td><td>N + 3</td><td>N + 1</td></tr>' +
    '<tr><td><b>SCX</b>, the background map read</td><td>N + 4 (the one-dot hold in <a href="#gbcr-10-26">Rule C10/26</a>). A stalled fetch&rsquo;s recording (the Game Boy tab, E.3.3) takes SCX without this hold, as the register stood at the start of the would-be read&rsquo;s dot, so it follows the register&rsquo;s row; MECHANISM, read from our source (<code>obj_stall_snap</code>), and no cell we hold is known to separate the two</td><td>N + 2</td></tr>' +
    '<tr><td><b>WX</b>, the register</td><td>N + 2</td><td>N</td></tr>' +
    '<tr><td><b>WX</b>, the takeover comparator</td><td>N + 3 when the pre-write WX is 7 or more, otherwise N + 2</td><td>N + 1 when the pre-write WX is 7 or more, otherwise N</td></tr>' +
    '<tr><td><b>WY</b>, the register and the per-frame arming test</td><td>N + 4</td><td>N + 2</td></tr>' +
    '<tr><td><b>BGP</b>, at the output stage</td><td>N + 2, no OR dot</td><td>N + 1 (not consulted in colour mode)</td></tr>' +
    '<tr><td><b>OBP0, OBP1</b>, at the output stage</td><td>N + 2</td><td>N + 1</td></tr>' +
    '<tr><td><b>LCDC</b></td><td>lead dots N and N + 1, conflict dot N + 2, C = N + 3; per consumer in the Game Boy tab&rsquo;s E.9.1</td><td>conflict dot N, C = N + 1; per consumer in E.9.1</td></tr>' +
    '<tr><td><b>STAT</b></td><td>the intermediate (bit 6 old, bits 5 to 3 new) on N + 4, the written bits from N + 5</td><td>the intermediate (bit 3 old, bits 6 to 4 new) on N + 2, the written bits from N + 3</td></tr>' +
    '<tr><td><b>LYC</b>, the coincidence comparator</td><td>N + 5</td><td>N + 3</td></tr>' +
    '<tr><td><b>IF</b>, against requests the picture unit raises</td><td>the write lands after N + 4: a request raised on N + 4 or earlier is overwritten, one on N + 5 or later survives</td><td>lands after N + 2; a request on N + 3 or later survives</td></tr>' +
    '</tbody></table>' +
    'An IF write against timer and serial requests follows the machine cycle: an IF write lands after its own cycle&rsquo;s four timer ticks, so a timer or serial request raised in the write&rsquo;s machine cycle is overwritten and one raised in any later machine cycle survives.</div>' +
    '<div class="gbemu-example"><b>Example.</b> At single speed a write cycle covers line dots 98 to 101, so N = 98. An SCX write is first read as the register on dot 101 and by the background map read on dot 102; a WX write written over a WX of 7 or more reaches the takeover comparator on dot 101; an LCDC write that takes the train has its lead dots on 98 and 99, its conflict dot on 100 and C on 101.</div>' +
    '<div class="gbemu-why"><b>Why.</b> The Game Boy tab&rsquo;s E.1.1 has the same table with the original&rsquo;s column beside these two. The IF note is MECHANISM, read from our source (the <code>0xFF0F</code> write runs after <code>tick4</code>).</div>' +
    '<p class="hw-readable">Pixels, as on the original: on an object-free line at SCX = 0 the background fetcher&rsquo;s map reads execute on dots 91, 99, 107 and so on, with the data reads two and four dots after each; the pixel for column x leaves the queue on dot 97 + x and reaches the screen on dot 98 + x (all event scale). Labels: every dot is <b>INSTRUMENT-MEASURED</b> on the shipped core with our own probe cartridge, in compatibility mode and in colour mode (identical) and in double speed; the label on whether the Color hardware agrees stays as the table of <a href="#gbcr-10-26">Rule C10/26</a> gives it, row by row, and nothing scored runs in double speed.</p>' +
    '<h4 class="gbemu-sub">The window on the Color</h4>' +
    '<div class="gbemu-rule" id="gbcr-10-29"><b>Rule C10/29.</b> Our window machine has exactly five Color departures: the window map&rsquo;s two-dot hold (the LCDC bit-6 row of <a href="#gbcr-10-26">Rule C10/26</a>), the window tile-data tags 10 and 12 (<a href="#gbcr-10-11">Rule C10/11</a>), the tile-data select glitches (Rules <a href="#gbcr-10-8">C10/8</a> to <a href="#gbcr-10-24">C10/24</a>), the kept notice-dot increment (<a href="#gbcr-10-32">Rule C10/32</a>), and <b>the frame-flag arm of the insertion without a takeover, which the Color never takes</b>: on a Color, in either mode, that one-pixel insertion is armed only by window enable having read set earlier on the same line (the Game Boy tab, Rules E.8.3/1 and E.8.3/2; its Rule 11/14 is the original&rsquo;s alone). Everything else (the counter, the seven priming increments, the comparator, the WX hold, the takeover, the restart fetch, the insertion&rsquo;s first arm) is carried: the same code on both machines, with no device test and no mode test. So on a Color, in compatibility mode <em>and</em> in colour mode, our core takes the original&rsquo;s window path apart from these five departures, with the original&rsquo;s WX lead returned through an unresolved row.</div>' +
    '<div class="gbemu-example"><b>Example (the frame flag).</b> <code>cgb-acid2</code> takes the window over at WX&nbsp;95 on lines 112 to 128, then clears LCDC bit 5 on line 129 and leaves WX at 95 with SCX&nbsp;0, so <code>(WX &amp; 7) == 7 - (SCX &amp; 7)</code> holds on every later line. On the original the frame flag would insert a colour-0 pixel at column 88 of each such line. On a Color nothing is inserted: the credit line on lines 133 to 139 is drawn unshifted. A build that keeps the original&rsquo;s frame-flag arm on the Color draws every pixel of those lines from column 88 one column to the right and fails the cartridge. Read from our source (<code>WIN_DIS_INSERT</code> applies on the original only); with only this arm removed, an independent build matches our picture word for word.</div>' +
    '<div class="gbemu-why"><b>Why.</b> That configuration scores <code>m3_window_timing_wx_0</code> and the other window cells at 0&nbsp;px against the stored revision-C renders (the 27 of 27 above).</div>' +
    '<div class="gbemu-rule" id="gbcr-10-30"><b>Rule C10/30.</b> <b>WX below 7.</b> Exactly E.8 and section 11 of the Game Boy tab, on both machines, apart from the frame-flag arm of the insertion without a takeover (the Game Boy tab, Rules E.8.3/2 and 11/14), which is the original&rsquo;s only (<a href="#gbcr-10-29">Rule C10/29</a>). The position counter starts at 0 and takes its seven priming increments beginning six dots after mode-3 entry (line dots 90 to 96 at SCX&nbsp;=&nbsp;0 with no object); values 0 to 6 of that counter are the positions -7 to -1, so WX&nbsp;0 to 6 match during the priming, on the dot the position passes WX&nbsp;-&nbsp;7. Four details, all carried:' +
    '<ol class="gbemu-steps">' +
    '<li><b>Dropped columns.</b> The <code>7 - WX</code> columns that fall off the left are dropped one per dot, and a dropped column&rsquo;s dot outputs no pixel (<code>WIN_DROP_DOTS</code> = 1).</li>' +
    '<li><b>The drop count.</b> If the takeover happens while the line&rsquo;s own priming fetch is still running, the number of columns to drop is fixed later, from WX as it stands when the fetch pushes, not at the decision (<code>WIN_DROP_LATE</code> = 1).</li>' +
    '<li><b>The priming bump.</b> The one-dot correction E.8 calls the priming bump is applied only on a line where a WX write landed during the priming fetch (<code>WIN_POS_TRIG</code> = 4). E.8 states it without that condition.</li>' +
    '<li><b>WX = 0.</b> With WX&nbsp;=&nbsp;0 and no fine scroll, a takeover during the priming fetch starts the first window fetch one dot into its first step.</li>' +
    '</ol>' +
    'On a line with no WX write during the priming fetch the comparator is open from dot 84 and subtracts nothing, so WX&nbsp;=&nbsp;0 takes over on dot 84 and WX 1 to 7 on dot 89&nbsp;+&nbsp;WX; on a line with one, it is closed until dot 90 and WX 0 to 7 take over on 90&nbsp;+&nbsp;WX (event scale, line dots).</div>' +
    '<div class="gbemu-example"><b>Example.</b> No WX write during the priming fetch, SCX = 0, no object: WX = 0 takes over on dot 84, WX = 3 on dot 92, WX = 7 on dot 96. On a line whose WX was written during the priming fetch, WX = 3 takes over on dot 93.</div>' +
    '<div class="gbemu-why"><b>Why.</b> Details 2 and 4 are the two halves of one rule that the Game Boy tab states in full (its appendix E.8.1, with a measured table of every WX): a takeover while the priming fetch is outstanding restarts that fetch, which then latches SCX&nbsp;&amp;&nbsp;7 <b>and the latch applies to the window&rsquo;s first pixels</b>, so screen column 0 shows window pixel (7&nbsp;&minus;&nbsp;WX)&nbsp;+&nbsp;(SCX&nbsp;&amp;&nbsp;7); a takeover after it voids the discard. It is what <code>m3_window_timing_wx_0</code> turns on (990&nbsp;px without it, 0&nbsp;px with it, on an independent build). The comparator dots are measured on our Color with a synthetic cartridge: the same dots as the original&rsquo;s, every WX from 0 to 9 and SCX&nbsp;&amp;&nbsp;7 at 0, 1, 3 and 7.</div>' +
    '<div class="gbemu-rule" id="gbcr-10-31"><b>Rule C10/31.</b> <b>The restart fetch&rsquo;s cost.</b> The same as the original: the restart fetch takes the early push at the high-data step, so a takeover that lands after the line&rsquo;s first pop costs 6 dots, not 8. Such a takeover is one at WX 8 and above, or at any WX on a line whose WX was written during the priming fetch. An earlier takeover costs between 7 dots more and 2 dots fewer than the same line without a window (the Game Boy tab, E.8.1). A takeover while the line&rsquo;s own priming fetch is still outstanding takes no switch dot and no second shortened fetch (<code>WIN_PRIME_LX0</code> = 3), on both machines.</div>' +
    '<div class="gbemu-why"><b>Why.</b> Section 7 of the Game Boy tab, MECHANISM and INSTRUMENT-MEASURED on the original. Carried, no device test. On the Color this is NOT ESTABLISHED: it is the original&rsquo;s measurement, run unchanged. Measured on our Color with a synthetic cartridge and identical to the original at every WX and fine scroll tried. So a Color build that finds the window costing 8 there has a defect elsewhere: on our core the restart fetch takes the early push on both machines.</div>' +
    '<div class="gbemu-rule" id="gbcr-10-32"><b>Rule C10/32.</b> <b>The seven priming increments during an object stall.</b> They are seven dots of a process, not seven fixed dots of the line: the &ldquo;dots 90 to 96&rdquo; of E.8 hold only at SCX&nbsp;=&nbsp;0 with no object in the way. On both machines our counter does not increment on any dot on which an object fetch is in progress. A clipped object (OAM X 0 to 7) is one fetch in our core, running from its <code>begin</code> to its <code>end</code> (E.3.1), so the increments pause for the whole clipped stall and resume after it; the seven still all happen. The counter does increment on the wait dots before a fetch (the switch that would halt it there, <code>WIN_PX_HALT_OBJ</code>, ships off) and on the dot the object is noticed, because the priming step runs earlier in the dot than the object test. On the Color the notice dot&rsquo;s increment is always kept (<code>WIN_PRIME_OBJ_DOT_CGB</code> = 0, a plain device test); the original hands it back when the fetcher is on the first dot of a step (<code>WIN_PRIME_OBJ_DOT</code> = 5).</div>' +
    '<div class="gbemu-why"><b>Why.</b> That is the one place the machines differ. Label for the Color arm: FITTED-TO-STORED-RENDER. Carrying the original&rsquo;s hand-back to the Color costs <code>m3_lcdc_tile_sel_win_change</code> 128&nbsp;px (the list under the window cells).</div>' +
    '<div class="gbemu-rule" id="gbcr-10-33"><b>Rule C10/33.</b> <b>A clipped object&rsquo;s stall and the window.</b> The clipped stall&rsquo;s first dot is <b>90&nbsp;+&nbsp;X</b> (plus SCX&nbsp;&amp;&nbsp;7 for OAM X 1 to 7), not 89&nbsp;+&nbsp;X (the last dot before the stall, the Game Boy tab&rsquo;s E.3.1), and the stall runs to <b>max(100, first dot&nbsp;+&nbsp;5)</b>, inclusive; the Game Boy tab carries the dot-by-dot table. On both machines, an object at OAM X 1 to 7 with X + (SCX&nbsp;&amp;&nbsp;7) of 8 or more first waits as the same object eight pixels to the right would (the Game Boy tab, E.3.1); at SCX&nbsp;=&nbsp;0 nothing changes. With WX&nbsp;=&nbsp;7, one clipped object and SCX&nbsp;=&nbsp;0, <b>the Color takes over on dot 106&nbsp;&minus;&nbsp;X</b> for OAM X 0 to 5 (106, 105, 104, 103, 102, 101) and the original on 107, 105, 105, 103, 103, 101; for OAM X 6 and 7 both take over on dot 96, before the object is noticed (event scale, line dots).</div>' +
    '<div class="gbemu-why"><b>Why.</b> Measured on both machines. The difference is exactly the notice dot&rsquo;s increment the original hands back on even X. These are the activation dots <code>m3_lcdc_win_map_change</code> and <code>m3_lcdc_tile_sel_win_change</code> exercise, one object per line at OAM X&nbsp;=&nbsp;LY&nbsp;/&nbsp;8.</div>' +
    '<div class="gbemu-rule" id="gbcr-10-34"><b>Rule C10/34.</b> <b>The window-trigger glitch</b> is not shipped (<a href="#gbcr-10-5">Rule C10/5</a>). The Game Boy tab&rsquo;s E.8.3 (the insertion without a takeover, and the one-dot postponed match) runs on the Color in our core too, with one device test: the insertion&rsquo;s frame-flag arm (the Game Boy tab, Rule E.8.3/2) is the original&rsquo;s only (<a href="#gbcr-10-29">Rule C10/29</a>; <code>WIN_DIS_INSERT</code>). The insertion&rsquo;s first arm and the one-dot postponed match have no device test (<code>WIN_INSERT_ZERO</code> = 2, <code>WIN_LATE_ENABLE</code> = 1).</div>' +
    '<div class="gbemu-why"><b>Why.</b> The glitch&rsquo;s label stays SOURCE-READ / CONVERGENCE for the shape and NOT ESTABLISHED for any effect. E.8.3 switched off moves no cell on the colour board (E.8.3 gives the figures).</div>' +
    '<h4 class="gbemu-sub">The window cells, line by line</h4>' +
    '<p class="gbemu-key">Five window cells are the hardest on the colour board: <code>m3_lcdc_tile_sel_win_change</code>, <code>m3_lcdc_tile_sel_win_change2</code>, <code>m3_lcdc_win_map_change</code>, <code>m3_lcdc_win_map_change2</code> and <code>m3_wx_4_change_sprites</code> (an independent build that reached the other 22 cells at 0&nbsp;px read 910, 965, 182, 140 and 10&nbsp;px on them). This subsection gives, for one line of each, every dot our core uses, so you can find the first dot on which yours differs, and what each rule involved is worth on the colour board when it is switched off. All dots INSTRUMENT-MEASURED on the shipped core, on the frame shown at the cartridge&rsquo;s breakpoint, after the Color boot program, on E&rsquo;s scale.</p>' +
    '<table class="gbemu-table"><thead><tr><th>Cell, line</th><th>Our core on that line, dot by dot (event scale, line dots)</th></tr>' +
    '</thead><tbody>' +
    '<tr><td><code>m3_lcdc_tile_sel_win_change</code>, line 20 (one object, OAM X&nbsp;=&nbsp;2; WX&nbsp;=&nbsp;7)</td><td>Priming increments on 90 and 91; the first real fetch&rsquo;s map read on 91; the object noticed on 92 (that dot&rsquo;s increment kept, the Color&rsquo;s rule), stall 92 to 100; increments resume 101 to 104; takeover on 104. Restart fetch: window map read 106, low plane 108, high plane 110 (the early push). The write that sets bit 4: lead dots 106 and 107, conflict dot 108, <code>C</code> 109, so the low read on 108 already forms its address on <code>$8000</code> (window low, tag 10: new from <code>C&nbsp;&minus;&nbsp;2</code>) and so does the high read on 110. The write that clears it: lead 114 and 115, conflict 116, <code>C</code> 117; the second window tile&rsquo;s low read on 114 is still on <code>$8000</code> and its high read, on the conflict dot 116, is on <code>$9000</code> (window high, tag 12, a clearing write: new from <code>C&nbsp;&minus;&nbsp;2</code>). The first window tile delivers <code>$FF</code> on both planes on this line in our core</td></tr>' +
    '<tr><td><code>m3_lcdc_win_map_change</code>, line 24 (one object, OAM X&nbsp;=&nbsp;3; WX&nbsp;=&nbsp;7)</td><td>Object noticed 93, stall 93 to 100; priming increments 90 to 93, then 101, 102 and 103; takeover 103. Window map reads on 105 (the restart fetch), 111, 119, 127 and every 8 dots after; first window pixel 109. The write that sets bit 6: lead dots 106 and 107 (bit 6 is in the register from 107), conflict 108, <code>C</code> 109; the clearing write: lead 114 and 115, conflict 116, <code>C</code> 117. With the Color&rsquo;s window-map rule (old on <code>C&nbsp;&minus;&nbsp;3</code> and <code>C&nbsp;&minus;&nbsp;2</code>, new from the conflict dot) exactly one window tile, the one read on 111, comes from the alternate map</td></tr>' +
    '<tr><td><code>m3_lcdc_win_map_change2</code>, line 24 (OAM X&nbsp;=&nbsp;1 and a second object at screen column 5; WX&nbsp;=&nbsp;7)</td><td>Clipped stall 91 to 100; takeover 105; window map reads 107 and 113. The second object is noticed on 116, with the window&rsquo;s second fetch frozen on the first dot of its high-plane step (its low read was on 115), so it waits no dots: stall 116 to 121; the fetcher resumes on 122, reads the high plane on 123 and pushes on 125; window map reads then fall on 127, 135, 143 and 151. The set write: lead 134 and 135, conflict 136, <code>C</code> 137; the clear write: lead 142 and 143, conflict 144, <code>C</code> 145. So the read on 135 still takes the base map, the read on 143 takes the alternate map (it reads the clearing write&rsquo;s pre-write value), and 151 the base map again. A map read on 137, two dots after ours, is exactly one tile early on this rule: if yours lands there, look first at how many dots your build spends around the mid-window object (ours: no wait, six stall dots, resume at the frozen sub-dot)</td></tr>' +
    '<tr><td><code>m3_lcdc_tile_sel_win_change2</code>, line 24 (the same two objects)</td><td>Takeover 105; window data reads (low, high) on 109 and 111, then 115 and 123 (the high read pushed 8 dots late by the stall 116 to 121, from a low read on <code>$9000</code>), then 129 and 131, 137 and 139, 145 and 147, 153 and 155, and so on every 8 dots. The bit-4 writes come in pairs 8 dots apart with <code>C</code> on 129, 137, 153, 161, 177 and 185; the low reads on those <code>C</code> dots take the new select</td></tr>' +
    '<tr><td><code>m3_wx_4_change_sprites</code>, line 12</td><td>Takeover on 93 (WX&nbsp;4, no WX write during the priming); the handler then writes WX&nbsp;=&nbsp;12 and on dot 107, at output position 5, the active-window match inserts one colour-0 pixel (the Game Boy tab, E.8.2). The cell inserts on every eighth line from 12 to 92. A build without that insertion is wrong on this cell and on no other scored Color cell, because every other cell that exercises it is among the four the colour board cannot score</td></tr>' +
    '</tbody></table>' +
    '<p class="gbemu-key"><b>What each rule is worth on the colour board, switched off one at a time on the shipped core.</b></p>' +
    '<ul class="gbemu-bullets">' +
    '<li>The stalled-high latch (<a href="#gbcr-10-13">Rule C10/13</a>): the original&rsquo;s board unchanged at 24 of 24; the Color&rsquo;s board 27 of 27 to 26 of 27 (<code>m3_lcdc_tile_sel_win_change</code> 364&nbsp;px). It first acts on line 64 of <code>m3_lcdc_tile_sel_win_change</code>, the first line on which the condition held on the line before too.</li>' +
    '<li>The conflict-dot override (<a href="#gbcr-10-12">Rule C10/12</a>): the original&rsquo;s board unchanged at 24 of 24; the Color&rsquo;s board 27 of 27 to 25 of 27 (<code>m3_lcdc_tile_sel_win_change2</code> 90&nbsp;px, <code>m3_lcdc_tile_sel_win_change</code> 50&nbsp;px).</li>' +
    '<li>The original&rsquo;s notice-dot hand-back carried to the Color: the original&rsquo;s board unchanged at 24 of 24; the Color&rsquo;s board 27 of 27 to 26 of 27 (<code>m3_lcdc_tile_sel_win_change</code> 128&nbsp;px).</li>' +
    '<li>The window map at the original&rsquo;s tag 8 instead of the Color&rsquo;s hold: the original&rsquo;s board unchanged at 24 of 24; the Color&rsquo;s board 27 of 27 to 25 of 27 (<code>m3_lcdc_win_map_change2</code> 70&nbsp;px, <code>m3_lcdc_win_map_change</code> 60&nbsp;px).</li>' +
    '<li>The active-window insertion (E.8.2) off: the original&rsquo;s board 24 of 24 to 21 of 24 (<code>m3_wx_5_change</code> 638&nbsp;px, <code>m3_wx_4_change</code> 229&nbsp;px, <code>m3_wx_4_change_sprites</code> 10&nbsp;px); the Color&rsquo;s board 27 of 27 to 26 of 27 (<code>m3_wx_4_change_sprites</code> 10&nbsp;px).</li>' +
    '<li>Priming increments running through object stalls: the original&rsquo;s board 24 of 24 to 22 of 24 (<code>m3_lcdc_tile_sel_win_change</code> 606&nbsp;px, <code>m3_lcdc_win_map_change</code> 246&nbsp;px); the Color&rsquo;s board 27 of 27 to 23 of 27 (<code>m3_lcdc_tile_sel_win_change2</code> 657&nbsp;px, <code>m3_lcdc_tile_sel_win_change</code> 542&nbsp;px, <code>m3_lcdc_win_map_change2</code> 210&nbsp;px, <code>m3_lcdc_win_map_change</code> 64&nbsp;px).</li>' +
    '<li>The stalled-fetch recording (E.3.3) off: the original&rsquo;s board 24 of 24 to 22 of 24 (<code>m3_scy_change</code> 502&nbsp;px, <code>m3_lcdc_tile_sel_change</code> 496&nbsp;px); the Color&rsquo;s board 27 of 27 to 25 of 27 (<code>m3_scy_change</code> 208&nbsp;px, <code>m3_lcdc_tile_sel_change</code> 124&nbsp;px).</li>' +
    '</ul>' +
    '<h4 class="gbemu-sub">The Color&rsquo;s own CPU-visible timing</h4>' +
    '<div class="gbemu-rule" id="gbcr-10-35"><b>Rule C10/35.</b> <b>On the Color every time the processor can see has its own value, per speed</b>: when LY changes, when STAT&rsquo;s mode bits change, when each status and vertical-blank request rises, when a halted processor wakes, when a running one takes the interrupt, and how long the speed switch takes. Rules <a href="#gbcr-10-36">C10/36</a> to <a href="#gbcr-10-44">C10/44</a> give them. They apply to the Color device in compatibility mode and in colour mode alike.</div>' +
    '<div class="gbemu-why"><b>Why.</b> They are set against the reference&rsquo;s outputs at both speeds (the measurement paragraph after <a href="#gbcr-10-44">Rule C10/44</a>). The access windows (<a href="#gbcr-10-44">Rule C10/44</a>): at single speed video and sprite memory reopen when STAT reports mode 0, and in double speed they open and close exactly when STAT&rsquo;s mode bits change (section 5 has them in words; the Game Boy tab&rsquo;s section 14 has the Colour&rsquo;s single-speed windows dot by dot). Off arm in our source: <code>CT_ON</code>&nbsp;0 gives back the original&rsquo;s timing on the Color (the original&rsquo;s values, the Game Boy tab, section 14).</div>' +
    '<p class="gbemu-key"><b>Two scales below, and each table names its own.</b> The LY table and the coincidence table are on the <b>access scale</b>: the dot given is the first access dot that reads the new value (an access on dot D sees dots 0 to D &minus; 1 done, the Game Boy tab, section 14). The STAT report table and the request table are on the <b>event scale</b>: an event on dot k is seen by a read made after dot k, so it is first seen by an access on dot k + 1. That is one scale with the rest of section 10 and with the Game Boy tab&rsquo;s appendix E (the line boundary four dots before the scan, mode 3 entered and drawing begun on dot 84). For example STAT&rsquo;s mode 2 is reported on dot 2 and first read by an access on dot 3 (INSTRUMENT-MEASURED, <code>test/tabprobe</code>, both speeds). So the row &ldquo;STAT reports mode 3, dot 82&rdquo; does mean that at single speed STAT reports mode 3 two dots before drawing begins (first seen by an access on dot 83, while video memory still reads until dot 84 is done); the Game Boy tab&rsquo;s Colour access table measures exactly that.</p>' +
    '<div class="gbemu-rule" id="gbcr-10-36"><b>Rule C10/36.</b> <b>LY as the processor reads it on the Color.</b>' +
    '<table class="gbemu-table"><thead><tr><th>Line</th><th>Single speed: first access dot that reads the new value (access scale, line dots)</th><th>Double speed: the same scale</th><th>Label</th></tr></thead><tbody>' +
    '<tr><td>Lines 1 to 143 and 145 to 152: LY becomes the new line</td><td>dot 1</td><td>dot 3</td><td>FITTED</td></tr>' +
    '<tr><td>Line 144</td><td>dot 0</td><td>dot 3</td><td>FITTED</td></tr>' +
    '<tr><td>Line 153: 153, then 0</td><td>153 from dot 0, 0 from dot 4</td><td>153 from dot 3, the same dot as every other line; 0 from dot 9</td><td>Single speed: FITTED. Double speed: the 153 is MECHANISM (the dot every line changes on), the 0 is FITTED (the hardware table allows dot 9 or 10)</td></tr>' +
    '<tr><td>Line 0, after line 153</td><td colspan="2">stays 0 for the whole line: it already reads 0 from dot 4 of line 153 (dot 9 in double speed), and the wrap into line 0 does not change it again. The next change is line 1&rsquo;s, on dot 1 (dot 3 in double speed), as the first row says</td><td>INSTRUMENT-MEASURED (the probe <code>test/tabprobe</code>, both speeds)</td></tr>' +
    '</tbody></table>' +
    'Only the register LY reads this way; the coincidence comparator is sequenced separately (<a href="#gbcr-10-40">Rule C10/40</a>).</div>' +
    '<div class="gbemu-example"><b>Example.</b> At single speed, an access on dot 0 of line 144 is made after line 143&rsquo;s last dot (455) is processed and before line 144&rsquo;s dot 0 is: it reads 144. An access on dot 0 of line 100 reads 99 and one on dot 1 reads 100. On line 153 at single speed, accesses on dots 0 to 3 read 153 and from dot 4 read 0; in double speed, an access on dot 2 still reads 152, dots 3 to 8 read 153, and from dot 9 read 0.</div>' +
    '<div class="gbemu-why"><b>Why.</b> The three LY rows are on the access scale, one dot later than the event scale would give them; the probe measured them that way. The two double-speed line-153 values overrule the reference&rsquo;s values: the AGE test <code>ly</code>, verified by its author on CPU CGB B and C, reads 152 on dot 2, 153 on dots 4 to 8 and 0 on dot 10, and our Color passes it. The original reads 153 on access dots 0 and 1 and 0 from access dot 2 (<code>LY153_VIS_DOT</code> = 2; the Game Boy tab, section 14). One reference implementation applies the early zero up to revision C only. Read from our source (<code>CT_LY</code>, <code>CT_LY144</code>, <code>CT_LY153</code>, <code>CT_LY153Z</code>: the value is applied when the line&rsquo;s dot counter reaches it, so a read at that counter value sees it).</div>' +
    '<div class="gbemu-rule" id="gbcr-10-37"><b>Rule C10/37.</b> <b>STAT&rsquo;s mode bits on the Color.</b>' +
    '<table class="gbemu-table"><thead><tr><th>STAT reports</th><th>Single speed (event scale, line dots)</th><th>Double speed (event scale, line dots)</th><th>Label</th></tr></thead><tbody>' +
    '<tr><td>mode 2 (lines 0 to 143)</td><td>dot 2</td><td>dot 4</td><td>FITTED</td></tr>' +
    '<tr><td>mode 3</td><td>dot 82</td><td>dot 84</td><td>FITTED</td></tr>' +
    '<tr><td>mode 0</td><td>2 dots before the line&rsquo;s last pixel (also on a line with objects). Exactly: on the dot on which pixels still to leave (160 minus the pixels sent to the screen) is 2 or less; on a line on which an object fetch has started (from the first object&rsquo;s notice, including while that fetch runs), pixels still to leave <em>plus the object dots still owed</em> must be 2 or less, where the object dots still owed are those of the Game Boy tab&rsquo;s E.6 (the dots left of the object fetch in progress, and no lead at all while another selected object still lies ahead on the line)</td><td>1 dot after the last pixel</td><td>FITTED</td></tr>' +
    '<tr><td>mode 1 (line 144)</td><td>dot 3</td><td>dot 5</td><td>FITTED</td></tr>' +
    '</tbody></table>' +
    '<b>Before the first report of a line</b> (access scale, from the line&rsquo;s dot 0): on line 0 after vertical blank, STAT reads <b>mode 0</b> on access dots 0 to 2 at single speed (the Color&rsquo;s form of the Game Boy tab&rsquo;s Rule 14/9 frame-edge rule, which on the original covers access dots 0 to 4), but <b>mode 1</b> on access dots 0 to 4 in double speed: in double speed vertical blank&rsquo;s mode 1 carries on until the mode-2 report, and no frame-edge mode 0 is reported. This is the reported mode only; the status requests on that line are those of <a href="#gbcr-10-38">Rule C10/38</a>. On line 144 STAT reads mode 0 before the mode-1 report: access dots 0 to 3 at single speed, 0 to 5 in double speed. INSTRUMENT-MEASURED (<code>test/tabprobe</code>), read from our source. ' +
    '<b>Example.</b> In double speed, a STAT read on access dot 4 of line 0 returns mode 1 and one on dot 5 returns mode 2; at single speed a read on access dot 2 of line 0 returns mode 0 and one on dot 3 returns mode 2. A build that applies Rule 14/9 in double speed reads mode 0 on dots 0 to 4 and fails AGE <code>stat-mode-ds</code>. ' +
    'The double-speed power-on line differs: there STAT reports mode 3 three dots after drawing starts (drawing starts on dot 84, so an access made with the dot counter at 87 or more reads 3; on 84 to 86 it reads 0), and mode 0 one dot later than the <em>single-speed</em> power-on line reports it: there two dots after its last pixel, here three; video-memory and sprite-memory reads follow the same report, and the writes do not (<a href="#gbcr-5-7">Rule C5/7</a> step 4).</div>' +
    '<div class="gbemu-example"><b>Example.</b> On an object-free line at SCX = 0 the last pixel (column 159) leaves the queue on dot 256. At single speed STAT reports mode 0 on dot 254, and an access on dot 255 is the first to read it.</div>' +
    '<div class="gbemu-why"><b>Why.</b> The double-speed power-on line&rsquo;s dot counts are the hardware tables&rsquo; (all 7 wrong readings of AGE <code>stat-mode-ds</code> were on this line), FITTED; why this line differs is not known.</div>' +
    '<div class="gbemu-rule" id="gbcr-10-38"><b>Rule C10/38.</b> <b>Status and vertical-blank requests on the Color.</b>' +
    '<table class="gbemu-table"><thead><tr><th>Request or source</th><th>Single speed (event scale, line dots)</th><th>Double speed (event scale, line dots)</th><th>Label</th></tr></thead><tbody>' +
    '<tr><td>Mode-0 status request</td><td>1 dot before the last pixel; 2 on a line with objects (counted as in <a href="#gbcr-10-37">Rule C10/37</a>&rsquo;s mode-0 row)</td><td>1 dot after the last pixel</td><td>FITTED; in double speed the request itself rises on that dot, not on the last pixel (MECHANISM)</td></tr>' +
    '<tr><td>Mode-2 status source, and when it falls</td><td>rises on dot 1 (line 0: dot 2); falls on dot 4 on every line, so the source is high for three dots (line 0: two)</td><td>rises on dot 3 (line 0: dot 4); falls on dot 4 on every line, so it is high for one dot on lines 1 to 143, and on line 0 it rises and falls within dot 4: the request is still written into IF on that dot (first seen by an access on dot 5), but the status line is never seen high there</td><td>FITTED for the rise; the fall is INSTRUMENT-MEASURED (the probe <code>test/tabprobe</code>, mode-2 select alone, both speeds), not separately fitted</td></tr>' +
    '<tr><td>Vertical-blank request, mode-1 report and mode-1 source, line 144</td><td>dot 3</td><td>dot 5</td><td>FITTED</td></tr>' +
    '<tr><td>The line-144 one-shot status request (<a href="#gbcr-10-39">Rule C10/39</a>)</td><td>line 143, dot 454</td><td>line 143, dot 451</td><td>see <a href="#gbcr-10-39">Rule C10/39</a></td></tr>' +
    '<tr><td>Horizontal-blank transfer, each block</td><td>as section 11</td><td>requested 3 dots after the last pixel; one byte slot (one machine cycle) is spent before the first byte</td><td>MECHANISM, read in the reference</td></tr>' +
    '</tbody></table></div>' +
    '<div class="gbemu-example"><b>Example.</b> Object-free line, SCX = 0, single speed: the last pixel leaves on dot 256, so the mode-0 request rises on dot 255 and is first seen by an access on dot 256; in double speed both the report and the request come on dot 257. On line 5 at single speed, the mode-2 source is high on dots 1, 2 and 3.</div>' +
    '<div class="gbemu-rule" id="gbcr-10-39"><b>Rule C10/39.</b> <b>The line-144 one-shot status request (mode-2 select).</b> On the Color it is written straight into IF on line 143, and not raised again at the wrap into line 144:' +
    '<table class="gbemu-table"><thead><tr><th>Speed</th><th>Written into IF as this dot of line 143 ends (event scale)</th><th>First seen by an access on (first-seen dot, line 143)</th><th>The vertical-blank request (line 144): event dot, first-seen dot</th></tr></thead><tbody>' +
    '<tr><td>single speed</td><td>454</td><td>455</td><td>3, 4</td></tr>' +
    '<tr><td>double speed</td><td>451</td><td>452</td><td>5, 6</td></tr>' +
    '</tbody></table>' +
    'It is written only when the mode-2 select is set and the status line is low on that dot. It never drives the status line, so it can neither hold the line high nor block a later edge. On the original it comes at line 144, dot 0, together with the vertical-blank request.</div>' +
    '<div class="gbemu-example"><b>Example.</b> At single speed the machine cycles around the boundary cover line 143 dots 450 to 453, then line 143 dots 454 and 455 with line 144 dots 0 and 1, then line 144 dots 2 to 5. A read sees the effect of its cycle&rsquo;s last dot. A read in the cycle covering 454 to line 144 dot 1 finds the one-shot request in IF and not the vertical-blank request; a read in the next cycle finds both. So the one-shot leads by exactly one machine cycle. In double speed the one-shot is first seen on line 143 dot 452 and the vertical-blank request on line 144 dot 6, ten dots (five double-speed machine cycles) apart.</div>' +
    '<div class="gbemu-why"><b>Why.</b> The ORDER is measured on hardware by the cartridge&rsquo;s author (<code>vblank_stat_intr-C</code>: passes on Color, fails on the original), and that cartridge passes on our core; the exact dot within the cycle is NOT ESTABLISHED. At single speed the dot is counted from the vertical-blank request (<code>STAT_M2_144_FROM_VB</code>); the double-speed dot is a fixed 4 dots before the line ends (<code>STAT_M2_144_LEAD_CGB</code> = 4), which is what our core does, with no hardware table behind it. Discharged (Color only). Read from our source; the cycle arithmetic of the example follows from <a href="#gbcr-10-47">Rule C10/47</a>.</div>' +
    '<div class="gbemu-rule" id="gbcr-10-40"><b>Rule C10/40.</b> <b>The coincidence (LY = LYC) comparator on the Color.</b>' +
    '<table class="gbemu-table"><thead><tr><th>Line</th><th>Single speed (access scale: the access dots that see each state)</th><th>Double speed (access scale)</th></tr></thead><tbody>' +
    '<tr><td>Blind dots after the wrap</td><td>3 dots (line 153: 5; before line 153 compares with 0: 3)</td><td>5 dots (7; 5). <b>In double speed the blind window holds the old flag instead of clearing it</b></td></tr>' +
    '<tr><td>An ordinary line</td><td>blind on 0 to 2 (flag 0, except a live match, below); compares the new line from 3</td><td>holds the previous line&rsquo;s flag on 0 to 4; compares the new line from 5</td></tr>' +
    '<tr><td>Line 153</td><td>blind 0 to 4, compares 153 on 5 to 7, blind again 8 to 10 (flag 0), compares 0 from 11. So a match on 153 is first seen on dot 5 and a match on 0 on dot 11, six dots apart</td><td>holds on 0 to 6, compares 153 from 7, holds that result on 8 to 12, compares 0 from 13. So a match on 153 is first seen on dot 7 and is still seen through dot 12; a match on 0 is first seen on dot 13</td></tr>' +
    '</tbody></table>' +
    '<b>A blind dot never drops a live match</b> (the Game Boy tab&rsquo;s Rule 14/12, which holds on the Color too): on a blind dot the flag is 1 when it was 1 on the dot before and the compared value still equals LYC; otherwise it is 0. The only boundary where that applies at single speed is the wrap from line 153 into line 0 with LYC = 0 (the compared value is 0 on both sides), so LYC = 0 makes one rising edge per frame, on line 153, and none on line 0. In double speed the blind dots hold the flag anyway.</div>' +
    '<div class="gbemu-example"><b>Example.</b> LYC = 0, coincidence select set, the processor running with interrupts enabled. The flag rises on access dot 11 of line 153 and the processor takes that request. On line 0 the flag stays 1 through dots 0 to 2, so no second request is made. A build that clears the flag on those dots raises a second request on line 0 and takes it about 20 dots in; on daid <code>ppu_scanline_bgp</code> (Color) that re-enters the handler and moves every palette write of the frame 12 dots earlier against the line (12 pixels to the left). Read from our source (<code>LYC_CARRY</code>); with this rule added, an independent build matched our picture word for word.</div>' +
    '<div class="gbemu-why"><b>Why.</b> FITTED; the hold is MECHANISM (the reference clears it only on revision C or earlier at single speed). One reference implementation has no start-of-line blind window in double speed or from revision D on. The full sequences are INSTRUMENT-MEASURED (the probe <code>test/tabprobe</code>, compare values 153, 0 and 5, coincidence select set), on the access scale of the Game Boy tab, section 14.</div>' +
    '<div class="gbemu-rule" id="gbcr-10-41"><b>Rule C10/41.</b> <b>Taking an interrupt on the Color.</b> A halted processor samples the request at the boundary, then runs one more machine cycle, then leaves HALT. A running processor takes the interrupt on the request as it stands at the instruction boundary, every source, with no hold. The Color has no dispatch hold: neither the original&rsquo;s coincidence hold nor its line-0 hold is used.</div>' +
    '<div class="gbemu-example"><b>Example.</b> Measured at single speed, halted processor, IME clear: line 0&rsquo;s mode-2 request is raised on dot 2 on the Color and the processor leaves HALT at the sample after dot 5. On the original it is raised on dot 3 and the processor leaves HALT at the sample after dot 8.</div>' +
    '<div class="gbemu-why"><b>Why.</b> The halted rule is MECHANISM, read in the reference (its Color halt loop); the running rule is MECHANISM. On the original a rising edge on line 0 (any source, the power-on line included) or a rising edge that carries the coincidence source arms a counter on dot D (3 dots on line 0, 1 for a coincidence edge), and a dispatch test sees the request only when the picture has processed dot D + 3 (or D + 1) or later; the Game Boy tab, section 14, has the rule. On the original the same held view is what every sample of the request reads: the test at the boundary, the halted wake, the halt-bug arming test and the dispatch&rsquo;s re-sample after the high-byte push (the Game Boy tab, D.10.1).</div>' +
    '<div class="gbemu-rule" id="gbcr-10-42"><b>Rule C10/42.</b> <b>The power-on line on the Color.</b> The interrupt-logic mode is none from the enable write until mode 3 begins (dot 84), so no source is high there, and switching the screen on with the mode-0 select set requests nothing. The mode-0 source rises when that line&rsquo;s drawing ends (dot 255 at SCX 0) and a selected one requests a status interrupt there. There is no mode-2 source on that line, and its scan examines slots 0 to 37 only (the Game Boy tab, section 14).</div>' +
    '<div class="gbemu-why"><b>Why.</b> MECHANISM. On the original the interrupt-logic mode is 0 from the enable write until mode 3 begins, so a selected mode-0 source is high from the write itself and requests a status interrupt there, unless the line was already high when the screen went off (it freezes while the screen is off). Neither machine has a mode-2 source on that line.</div>' +
    '<div class="gbemu-rule" id="gbcr-10-43"><b>Rule C10/43.</b> <b>The speed switch on the Color.</b> The stall is 4 machine cycles shorter than the original&rsquo;s timing gives it: 32,766 machine cycles from the end of the <code>STOP</code> to the wake instead of 32,770 (section 3 has the dots each way). A switch made with the screen on (and not on the power-on line) moves the picture unit 2 dots, onto the new speed&rsquo;s phase, at the moment the speed flips: going into double speed the picture runs 2 extra dots at once; coming out of it, nothing is rewound: the picture instead skips the next 2 dots the processor would have paid it, so it waits 2 dots while the processor runs on. The divider comes out of its reset at the end of the switch&rsquo;s last machine cycle, not at its start, so that cycle&rsquo;s four clocks are not counted.</div>' +
    '<div class="gbemu-why"><b>Why.</b> FITTED; the divider restart is MECHANISM (AGE <code>spsw-div</code>).</div>' +
    '<div class="gbemu-rule" id="gbcr-10-44"><b>Rule C10/44.</b> <b>Video and sprite memory as the processor sees them on the Color.</b> At single speed: video memory closes when drawing starts, not six dots before it; both reopen when STAT reports mode 0; a sprite-memory write is refused from the first dot of the line, with no write window where the scan ends; on the power-on line video memory still reads for the first 6 dots of drawing. In double speed: video memory is closed exactly while STAT reports mode 3, and sprite memory while it reports mode 2 or 3, each opening on the dot STAT changes; a sprite-memory write meets the closing edges one dot sooner than a read. On the double-speed power-on line the reads follow <a href="#gbcr-10-37">Rule C10/37</a>&rsquo;s power-on report and the writes do not: <a href="#gbcr-5-7">Rule C5/7</a> step 4 and the double-speed table&rsquo;s power-on rows give the dots.</div>' +
    '<div class="gbemu-why"><b>Why.</b> Single speed: FITTED as a set. Double speed: following STAT is MECHANISM (the single-speed rule, at the other speed); the write&rsquo;s one dot is FITTED (the table samples even dots only, so 1 and 2 both fit). AGE <code>vram-read</code>, <code>oam-read</code> and <code>oam-write</code>, verified on CPU CGB B, C and E.</div>' +
    '<p class="hw-readable"><b>Why, and how it was measured.</b> Magical Drop rewrites one colour 46 times per line from a coincidence interrupt and a STAT poll in double speed; its writes meet the palette&rsquo;s busy window (section 6) on the right dots only when every edge above is right. Measured with 257 probe cartridges of our own (a register read k machine cycles after a wake from every source, both speeds, after a switch with the screen on, and 204 object layouts) and by aligning every register access of Magical Drop, Demotronic and Shantae with the reference&rsquo;s. Results: all cells agree but five (below); Demotronic and Shantae make the same accesses on the same dots as the reference for 1,500 frames. <b>Not settled:</b> two objects 3 pixels apart at some fine positions (X&nbsp;=&nbsp;65 or 67 and +3 in double speed, 66 and +3 at single speed) end mode 3 one dot later than the reference; our object timing waits a dot that the reference does not. The double-speed power-on line&rsquo;s length that goes with these values is <a href="#gbcr-10-46">Rule C10/46</a>.</p>' +
    '<h4 class="gbemu-sub">Interrupt sources and LY on the Color</h4>' +
    '<div class="gbemu-rule" id="gbcr-10-45"><b>Rule C10/45.</b> <b>The status sources, in absolute dots.</b> One interrupt-logic mode drives the three mode sources, so at most one of them is high at a time, and a change from one selected source to another on the same dot makes no edge. The coincidence source is ORed beside it. At single speed, on an object-free line at SCX 0, our Color&rsquo;s sources are high on these dots (event scale, line dots):' +
    '<table class="gbemu-table"><thead><tr><th>Source</th><th>The Color, single speed (event scale)</th><th>The original, for comparison (event scale)</th></tr></thead><tbody>' +
    '<tr><td>Mode-2 source, lines 1 to 143</td><td>high on dots 1, 2 and 3 (raised on dot 1, low from dot 4)</td><td>dots 2 and 3</td></tr>' +
    '<tr><td>Mode-2 source, line 0</td><td>dots 2 and 3</td><td>dot 3 only</td></tr>' +
    '<tr><td>Mode-2 source, the power-on line</td><td>none</td><td>none</td></tr>' +
    '<tr><td>Mode-0 source</td><td>rises on dot 255, one dot before the last pixel leaves (STAT reports mode 0 a dot earlier, on 254). It stays high to the end of the line and across the line boundary. On lines 0 to 142 it falls where the interrupt-logic mode becomes 2: dot 1 of the next line. From line 143 it holds into line 144 and falls where the mode-1 source takes over: line 144 dot 3</td><td>rises on dot 256, three dots after STAT reports mode 0 on 253 (the Game Boy tab, E.6); falls on dot 2 of the next line; from line 143, on line 144 dot 6</td></tr>' +
    '<tr><td>Mode-1 source</td><td>line 144 dot 3 to line 0 dot 1, falling on line 0 dot 2 where the mode-2 source rises</td><td>line 144 dot 6 to line 0 dot 2, falling on dot 3</td></tr>' +
    '</tbody></table>' +
    'Line 144&rsquo;s one-shot is a separate request (<a href="#gbcr-10-39">Rule C10/39</a>).</div>' +
    '<div class="gbemu-example"><b>Example.</b> Both the mode-0 and the mode-2 select are set. On line 5 the mode-0 source rises on dot 255 and requests a status interrupt. On dot 1 of line 6 the interrupt-logic mode becomes 2: the mode-0 source falls and the mode-2 source rises on the same dot, so the status line stays high and line 6 makes no mode-2 request.</div>' +
    '<div class="gbemu-why"><b>Why.</b> Measured with a synthetic cartridge of our own and the per-dot probe in our source tree (<code>test/tabprobe</code>), no objects, SCX 0, the Color in compatibility mode, on the shipped core. D is the dot whose processing raises a request, so a request raised on dot D is first seen by a read made on dot D + 1. Making the mode-2 source a one-dot pulse (low from dot 3) or holding it through the scan (to dot 83) moves no Mooneye row on either machine and no mealybug pixel (MEASURED): the width is unobservable on everything we hold. <b>Dropping the mode-0 source at the line boundary instead fails <code>acceptance/ppu/stat_irq_blocking</code> on both machines and nothing else</b> (MEASURED): that is the held window the Game Boy tab&rsquo;s section 14 means.</div>' +
    '<div class="gbemu-why"><b>The mode-0 value on our Color, 2.</b> The single-speed lead of 2 on a line with objects (<a href="#gbcr-10-37">Rule C10/37</a>, <a href="#gbcr-10-38">Rule C10/38</a>) is one dot less than the original&rsquo;s 3. The cause is the phase, not the objects: our Color&rsquo;s processor sees the line one dot later than the original&rsquo;s (every access after a line dot of the form 4k&nbsp;+&nbsp;1 rather than 4k, the consequence of the 450-dot power-on line), and the lead has to equal the distance from the object-free report back to the first dot of the processor&rsquo;s sample window that holds it (the Game Boy tab, E.6, defines the owed dots and states that rule). With the original&rsquo;s 3 our Color fails <code>intr_2_mode0_timing_sprites</code> at testcase #0A (ten objects at OAM X&nbsp;=&nbsp;1), with and without the boot program. The lead moves the report only: the reported mode, the interrupt-logic mode and the status line; no pixel, fetcher dot, stall or horizontal-blank transfer. FITTED on both machines (E.6): the one-dot difference is the measured phase, the 3 it is applied to is fitted.</div>' +
    '<h4 class="gbemu-sub">The processor-to-dot phase on the Color</h4>' +
    '<div class="gbemu-rule" id="gbcr-10-46"><b>Rule C10/46.</b> Our core has no Color phase constant. On a booted run, which is the only sanctioned start (section 2), the phase is set by the length of the line on which the display is switched on, every time it is switched on, exactly as E.2 says for the original. That length is split by device and speed (G33, three arms):' +
    '<ul class="gbemu-bullets">' +
    '<li>original: 451 dots, pinned by two monochrome cartridges;</li>' +
    '<li>Color, single speed: <b>450</b> (<code>LCD_ON_LEN_CGB</code>), FITTED-TO-STORED-RENDER;</li>' +
    '<li>Color, double speed (the display switched on while in double speed): 448 (<code>LCD_ON_LEN_CGB2</code>), FITTED with the timing block of <a href="#gbcr-10-35">Rule C10/35</a>.</li>' +
    '</ul>' +
    'The start dot is 8 on every arm, so mode 3 still begins 76 dots into the power-on line; only the length is split.</div>' +
    '<div class="gbemu-why"><b>Why.</b> Only the length is split because only the length is observable. Single speed: the direction of a difference is documented (one published document says the display timings differ on the Color even in compatibility mode and gives no number); the magnitude is ours. Source comment: 450 gives the colour board 3,170&nbsp;px against 10,027 at 451, at the base that was measured on, and costs 128&nbsp;px on one window cartridge that no value of this quantity can buy back. Double speed: the AGE double-speed tests switch the display on in double speed and read that line (<code>stat-mode-ds</code> passes). 448 puts the double-speed line&rsquo;s mode 2, mode 3 and last pixel on the reference&rsquo;s dots. Since every later line is 456 dots, a Color line boundary sits one dot earlier against the processor&rsquo;s machine-cycle grid than the original&rsquo;s does. That one dot is the other half of SCY&rsquo;s lead (<a href="#gbcr-10-26">Rule C10/26</a>): the two were swept as a pair and the board sees only their sum.</div>' +
    '<div class="gbemu-rule" id="gbcr-10-47"><b>Rule C10/47.</b> <b>Which dots a Color machine cycle covers.</b> After a single-speed switch-on the 450-dot power-on line runs from dot 8 to dot 457; the machine cycle covering 456 and 457 also covers dots 0 and 1 of line 1, so from line 1 on <b>every machine cycle covers dots 4k + 2 to 4k + 5</b> (on the original, 4k + 1 to 4k + 4: the Game Boy tab, section 1). A read in a cycle sees the effect of its last dot; a write with no lead is first seen on the dot after it. In double speed a cycle covers two dots, <b>an even-numbered dot and the odd one after it</b>. That holds after a switch-on made in double speed (the power-on line is 448 dots, dot 8 to dot 455, so line 1 starts on a cycle boundary) and after a speed switch made with the display already on (the switch moves the picture unit 2 dots forward onto the same phase; <a href="#gbcr-10-43">Rule C10/43</a>). An LCDC write landing in mode 3 in double speed does not move the picture ahead (<a href="#gbcr-10-4">Rule C10/4</a>). The no-boot fallback of section 2 starts at the booted hand-over, reached by running the picture from line 0, so it runs at the booted Color&rsquo;s phase.</div>' +
    '<div class="gbemu-why"><b>Why.</b> 19,996 in every 20,000 instruction boundaries fall on a dot of the form 4k&nbsp;+&nbsp;2 with and without the boot program. All INSTRUMENT-MEASURED on the shipped core; the 450 that sets the single-speed phase remains FITTED, as <a href="#gbcr-10-46">Rule C10/46</a> says.</div>' +
    '<div class="gbemu-rule" id="gbcr-10-48"><b>Rule C10/48.</b> The original&rsquo;s &ldquo;the dot clock leads the processor by one dot&rdquo; (the Game Boy tab, section 1) is a one-dot tick our core applies at reset on the no-boot path only, on both machines alike. Where the processor lands inside its machine cycle is E.5&rsquo;s seam, unchanged, at <code>B</code> dots per cycle.</div>' +
    '<div class="gbemu-why"><b>Why.</b> Our source records that the reset-time tick is not reached on any booted run, so it plays no part in any Color picture we score.</div>' +
    '<h4 class="gbemu-sub">What is not known</h4>' +
    '<ul class="gbemu-bullets">' +
    '<li>Every Color lead and consumer dot in the hardware. Every Color value above is either our fit to the stored revision-C renders, a reference implementation&rsquo;s shape, or the original&rsquo;s value run unchanged. What would settle any one row: a colour-flagged cartridge writing that register at a known dot inside mode 3, photographed at the first pixel that carries the new value, at each speed.</li>' +
    '<li>Any write lead or pixel in double speed. No cell on the colour board runs there, and the AGE double-speed picture runs still fail (section 16). The LCDC write budget above is balanced and measured on a probe, not on a scored cell. What double speed does have is scored timing the processor can see: STAT&rsquo;s mode bits, LY and the memory access windows pass the AGE hardware tables there (Rules <a href="#gbcr-10-36">C10/36</a> to <a href="#gbcr-10-44">C10/44</a>).</li>' +
    '<li>Whether the Color&rsquo;s window takeover, WX&nbsp;&lt;&nbsp;7 handling and restart cost are the original&rsquo;s. Ours are, and they score; scoring is not establishing.</li>' +
    '<li>The Color&rsquo;s vertical-blank, mode-1 and mode-2 source dots on the hardware. Ours are fitted to the reference (<a href="#gbcr-10-38">Rule C10/38</a>); the line-144 one-shot&rsquo;s order is measured, its dot is not (<a href="#gbcr-10-39">Rule C10/39</a>). The one cartridge that pins the mode-1 interval on the original declares in its own header that it fails on the Color, so the interval it measures is not 4,560 dots there.</li>' +
    '<li>Whether the mode-0 lead&rsquo;s dots (<code>OBJ_M0_LEAD</code>&rsquo;s quantity) exist on Color hardware. On our core the Color&rsquo;s value is 2 because of our Color&rsquo;s phase (the explanation under <a href="#gbcr-10-45">Rule C10/45</a>); that is a statement about our phase, not about the hardware.</li>' +
    '<li>Where LY&rsquo;s early zero on line 153 falls on revisions after C. In double speed the AGE table (CPU CGB B and C) puts 153 on the same dot as every other line and 0 on dot 9 or 10 (ours 9, FITTED). At single speed our Color&rsquo;s dot 4 is the reference&rsquo;s value (FITTED), and the original&rsquo;s dot 2 is not separated from its neighbours by anything we own.</li>' +
    '<li>The processor-to-dot phase as a hardware number. 450 is a fit; its double-speed twin, 448, is a fit too, read by the AGE double-speed tests but not derived.</li>' +
    '</ul>' +
    '<h4 class="gbemu-sub">Questions an implementer asks, answered</h4>' +
    '<p class="hw-readable">An index into the rules above; each answer is our core&rsquo;s, and the rule it points to is the statement.</p>' +
    '<table class="gbemu-table">' +
    '<thead>' +
    '<tr><th>Question</th><th>Answer (our core)</th><th>Where</th></tr>' +
    '</thead>' +
    '<tbody>' +
    '<tr><td>LY on line 153</td><td>On the original: 153 on access dots 0 and 1, then 0 from access dot 2. On the Color: 153 from access dot 0 and 0 from access dot 4 at single speed; in double speed 153 from access dot 3, the same dot as every other line, and 0 from access dot 9 (the 9 is FITTED). Not 0 to 7: that is the comparator&rsquo;s view, which is separately sequenced</td><td><a href="#gbcr-10-36">Rule C10/36</a>; <a href="#gbcr-10-40">Rule C10/40</a></td></tr>' +
    '<tr><td><code>OBJ_M0_LEAD</code> on the Color</td><td>On the Color the timing block replaces it: on a line with objects the report and the request both lead by 2 at single speed, counted with the same owed object dots, and both come 1 dot after the last pixel in double speed. With the original&rsquo;s 3 it fails <code>intr_2_mode0_timing_sprites</code> on our Color at #0A, so the Color runs 2; the lead is a phase (the Game Boy tab, E.6, has the definition of the owed dots and the rule for the number)</td><td><a href="#gbcr-10-37">Rule C10/37</a>; <a href="#gbcr-10-38">Rule C10/38</a>; the explanation under <a href="#gbcr-10-45">Rule C10/45</a></td></tr>' +
    '<tr><td>Mode-1 source on line 144</td><td>On the Color dot 3 at single speed and dot 5 in double speed, together with the vertical-blank request and the mode-1 report. The original uses dot 6</td><td><a href="#gbcr-10-38">Rule C10/38</a>; <a href="#gbcr-10-45">Rule C10/45</a></td></tr>' +
    '<tr><td>The mode-2 source</td><td>On the original: dot 2 on lines 1 to 143 (forced low at dot 4), dot 3 on line 0. On the Color the request rises on dot 1 (line 0: dot 2) at single speed and on dot 3 (line 0: dot 4) in double speed</td><td><a href="#gbcr-10-38">Rule C10/38</a>; <a href="#gbcr-10-45">Rule C10/45</a></td></tr>' +
    '<tr><td>Color leads and consumer dots</td><td>A per-register lead plus a few per-consumer holds and tags, mostly the original&rsquo;s; the Color departures are SCY 0, the SCX map hold, BGP single-stage, LCDC bit 3 tag 9, bit 6 hold, bit 2 desync, bit 4 window tags, object selection forced, STAT intermediates</td><td><a href="#gbcr-10-26">Rule C10/26</a>; <a href="#gbcr-10-28">Rule C10/28</a></td></tr>' +
    '<tr><td>WX&nbsp;&lt;&nbsp;7</td><td>The original&rsquo;s positional comparator, unchanged: the takeover fires during the priming as the position passes WX&nbsp;-&nbsp;7, with <code>7 - WX</code> dropped columns at a dot each</td><td><a href="#gbcr-10-30">Rule C10/30</a></td></tr>' +
    '<tr><td>Restart fetch</td><td>Takes the early push on the Color too: 6 dots, not 8</td><td><a href="#gbcr-10-31">Rule C10/31</a></td></tr>' +
    '<tr><td>Vertical-blank request dot</td><td>On the original: line 144, dot 0, with the mode-1 source 6 dots later. On the Color: dot 3 at single speed and dot 5 in double speed, with the mode-1 report and source on the same dot; <code>vblank_stat_intr-C</code> passes on our core</td><td><a href="#gbcr-10-38">Rule C10/38</a>; <a href="#gbcr-10-39">Rule C10/39</a></td></tr>' +
    '<tr><td>Mode-0 source against reported mode 0</td><td>Not simultaneous. On the Color at single speed the report comes 2 dots before the last pixel and the request 1 dot before it (2 on a line with objects); in double speed both come 1 dot after the last pixel. On the original a line that selected no object reports mode 0 three dots before its last pixel while the request stays on the last pixel; on object lines both move together, 3 dots early (the Game Boy tab, E.6)</td><td><a href="#gbcr-10-37">Rule C10/37</a>; <a href="#gbcr-10-38">Rule C10/38</a></td></tr>' +
    '<tr><td>Priming during a clipped-object stall</td><td>Paused for every dot an object fetch is in progress, so for the whole clipped stall; resumes after; the notice dot&rsquo;s increment is kept on the Color, handed back on the original</td><td><a href="#gbcr-10-32">Rule C10/32</a></td></tr>' +
    '<tr><td>Stalled-fetch input recording</td><td>Applies on the Color unchanged: same closed list, recorded one dot early. No device test. The Color&rsquo;s own widths for the background map (9), window map (hold) and window tile data (10) are the ones recorded</td><td>The Game Boy tab E.3.3; <a href="#gbcr-10-14">Rule C10/14</a></td></tr>' +
    '<tr><td>The processor-to-dot phase</td><td>No separate constant: the power-on line is 450 dots on a Color at single speed (448 in double speed), one dot shorter than the original&rsquo;s 451 at single speed; the reset-time one-dot skew is never reached on a booted run</td><td><a href="#gbcr-10-46">Rule C10/46</a>; <a href="#gbcr-10-48">Rule C10/48</a></td></tr>' +
    '<tr><td>What &ldquo;lead&rdquo; means for BGP and OBP; where the LCDC train sits against the write&rsquo;s machine cycle</td><td>Both palettes take the new value on the third dot of the write&rsquo;s four-dot cycle at single speed (lead 2 in E.1&rsquo;s convention; our source&rsquo;s constant 3 is one more because the palette write spends a dot of its own), and on the second dot of the two-dot cycle in double speed. The LCDC lead dots are the first two dots of the write&rsquo;s cycle, the conflict dot its third and C its last.</td><td><a href="#gbcr-10-28">Rule C10/28</a>; <a href="#gbcr-10-10">Rule C10/10</a>; the Game Boy tab&rsquo;s E.9.1</td></tr>' +
    '<tr><td>The original&rsquo;s window path in compatibility mode</td><td>Yes, and in colour mode as well, apart from the five Color departures of Rule C10/29 (the frame-flag arm of the insertion without a takeover among them): no window code tests the mode. With it our core scores the window cells at 0&nbsp;px against revision C. A large miss on <code>m3_window_timing_wx_0</code> with this path is therefore not evidence for a different Color path; the phase rows (450, SCY 0) are where to look</td><td><a href="#gbcr-10-29">Rule C10/29</a>; <a href="#gbcr-10-46">Rule C10/46</a></td></tr>' +
    '</tbody>' +
    '</table>' +
    '<p class="gbemu-key"><b>More questions in this cluster, answered.</b></p>' +
    '<table class="gbemu-table"><thead><tr><th>Question</th><th>Answer (our core)</th><th>Where</th></tr>' +
    '</thead><tbody>' +
    '<tr><td>Where the LCDC train sits against the write&rsquo;s cycle</td><td><code>C</code> is the last dot of the write&rsquo;s own machine cycle; lead dots and conflict dot are its first three. On our Color, <code>C</code> is a dot of the form 4k&nbsp;+&nbsp;1</td><td><a href="#gbcr-10-10">Rule C10/10</a></td></tr>' +
    '<tr><td>WX&nbsp;=&nbsp;0 during the priming</td><td>The takeover restarts the priming fetch, the fine scroll latched when it completes applies to the window, the drop count is read at the window&rsquo;s first push, and at zero fine scroll the first window fetch starts one dot in. That reading is our core&rsquo;s</td><td>The Game Boy tab, E.8.1; <a href="#gbcr-10-30">Rule C10/30</a></td></tr>' +
    '<tr><td>The stalled-fetch recording during a clipped stall and after the priming fetch</td><td>Yes to both, by one rule: every object fetch records the reads its frozen fetch still owes, and a clipped object at OAM X&nbsp;=&nbsp;0 freezes the first real fetch before it starts</td><td>The Game Boy tab, E.3.3</td></tr>' +
    '<tr><td>What &ldquo;object dots still owed&rdquo; counts</td><td>The stall dots left in the fetch in progress; an unfetched object still ahead blocks the report outright (any other than the one being fetched, which never blocks its own report). And the number is a phase: our own Color fails the cartridge at #0A with 3</td><td>The Game Boy tab, E.6; <a href="#gbcr-10-37">Rule C10/37</a></td></tr>' +
    '<tr><td>The hardest window cells</td><td>Each one is worked line by line from our core, with what each rule is worth when switched off</td><td>The window cells, line by line</td></tr>' +
    '</tbody></table>' +
    '<p class="gbemu-key"><b>And more questions, answered.</b> Each answer is measured on the shipped core.</p>' +
    '<table class="gbemu-table"><thead><tr><th>Question</th><th>Answer (our core)</th><th>Where</th></tr>' +
    '</thead><tbody>' +
    '<tr><td>A start with no boot program</td><td>To match our booted runs (Rule C2/13): load section 9&rsquo;s table and the other 104 bytes as measured, bank 0 tile data as the original&rsquo;s, both tile maps zero. Our own no-boot fallback loads none of that: palette memory stays <code>0x0000</code> and video memory empty (Rule C2/15). Both: <code>0xFF26</code> = <code>0xF1</code> with channel 1 at volume 0</td><td>Section 2</td></tr>' +
    '<tr><td>An OAM X = 8 object under a WX = 7 restart</td><td>The wait has no queue condition; an object at OAM X = 8 is not due until the queue holds a pixel, and holds the pop on the push dot</td><td>The Game Boy tab, E.3.4</td></tr>' +
    '<tr><td>When an object is noticed</td><td>X above 8 by the pixel count, X = 8 by the queue rule, X 0 to 7 by the pre-visible position; a notice dot spent on a takeover moves to the next dot</td><td>The Game Boy tab, E.3.4</td></tr>' +
    '<tr><td>Status sources and the hold</td><td>In absolute dots, with the stat_irq_blocking measurement that the held window refers to</td><td><a href="#gbcr-10-45">Rule C10/45</a>; <a href="#gbcr-10-41">Rule C10/41</a></td></tr>' +
    '<tr><td><code>0xFF6C</code> in compatibility mode</td><td>A write after the hand-over is dropped in compatibility mode; that is why the cartridge passes</td><td>Section 8; appendix A</td></tr>' +
    '<tr><td><code>0xFF02</code>, <code>0xFF56</code></td><td>Both are modelled: bit 1 of SC selects the fast clock in colour mode, and the infrared port stores its LED and read-enable bits and reads no light unless a linked second machine shines (appendix A)</td><td>Appendix A</td></tr>' +
    '<tr><td>The latch, the recording, the start of the dot</td><td>Recording, then the conflict-dot override, then the latch; the WX = 0 test is made on the count just latched</td><td><a href="#gbcr-10-14">Rule C10/14</a>; the Game Boy tab, E.8.1</td></tr>' +
    '<tr><td>Sequencer and clock figures</td><td>1,028 and 2,057 over a stated window; 60 against 59 is one phase of an alternating count</td><td>Section 3</td></tr>' +
    '<tr><td>The 620 against 534</td><td>Our core reads 620; switching our wait to your queue condition moves nothing</td><td>The Game Boy tab, E.8.1</td></tr>' +
    '<tr><td>The early push, and whether a horizontal-blank block stalls the processor</td><td>Only the priming fetch and the window&rsquo;s restart fetch take the early push; each block stalls the processor</td><td>The Game Boy tab, section 9; section 11</td></tr>' +
    '</tbody></table>' +
    '</section>' +

  /* ------------------------------------------------------------------ 11 */
  '</div>';
}
